-- ════════════════════════════════════════════════════════
-- 243 — Huitième recensement : vingt-cinq maisons, d'Estelí
--       à Danlí (lots d'écriture 10, 12, 17, 18 et 19)
-- ────────────────────────────────────────────────────────
-- D'OÙ ELLES VIENNENT. Comme la 239, la 240 et la 241 : des noms que le
-- marché vend et que l'atlas n'avait pas, passés par le tri, le
-- contradicteur, le rédacteur, la relecture et la traduction.
--   Nicaragua         Don Duarte (Tabacalera Pages), Alcazar (PENSA de
--                     J.C. Newman), Los Amigos (Familia Disla), Umnum et
--                     Villa Vieja (TABSA d'Aganorsa Leaf), à Estelí ;
--                     Bahia, Cigarkings, CSC, Despot, Don Zuarin,
--                     Horacio, Ibis, Mara, Marca Fina, May's Cigars,
--                     Nordlicht, Schumacher
--   Rép. dominicaine  Samana (Don Esteban, Santiago), SYN (usine propre,
--                     Tamboril), Valentino Siesto (El Hoyito, Tamboril),
--                     Xhaxhi Bobi (Kelner Boutique Factory), Antonius
--                     (Intercigar, Tamboril), Bauza (Tabacalera A.
--                     Fuente), Butera (Tabacalera de García, La Romana)
--   Honduras          Cuba Aliados (Aladino, Danlí)
--
-- ── LE SILENCE ÉCRIT ────────────────────────────────────
-- Douze fiches : Bahia, Cigarkings, CSC, Despot, Don Zuarin, Horacio,
-- Ibis, Mara, Marca Fina, May's Cigars, Nordlicht et Schumacher. Le
-- propriétaire est identifié et le pays de roulage attesté ; la maison
-- ne nomme pas sa fabrique (décision du 23 septembre).
--
-- ── CE QUE LA RELECTURE A TRANCHÉ ───────────────────────
-- Alcazar garde sa fiche alors que J.C. Newman possède la marque et
-- l'usine qui la roule : son histoire précède le rachat (précédent
-- Cuesta-Rey) ; Bauza aussi, vieille marque cubaine que la famille
-- Fuente relance en 1990. Samana garde la sienne comme Capadura : ce
-- sont les deux marques qu'Oskar Nausch roule dans sa Tabacalera Don
-- Esteban, que l'atlas n'a pas ouverte en maison.
-- Ibis garde la sienne comme Ann-Eks et Canned Heat, marques d'August
-- Schuster dont la fabrique est tue. Don Duarte et Villa Vieja sont deux
-- marques de Fernando Navarro roulées dans deux fabriques, Pages et
-- Aganorsa, chacune dite par sa maison. La fabrique de Valentino Siesto
-- est écrite attribuée : la Tabacalera El Hoyito est l'œuvre de la
-- famille Gómez, la maison la dit sienne depuis 2014 ; celle de Butera
-- aussi : Cigar Coop situe à la Tabacalera de García toute la production
-- dominicaine d'Altadis U.S.A., la maison ne nomme pas la sienne. Marca
-- Fina se range au Nicaragua, où StarkeZigarren.de la dit roulée : le
-- Panama est l'origine du tabac de sa ligne d'origine. La fabrique de
-- Bahia, qu'un seul blog nommait, reste hors du texte. Les lignes de
-- Xhaxhi Bobi rangées en `mentions` passent en gamme ; RVGN n'est pas
-- une mention d'Antonius : c'est une ligne de German Engineered Cigars,
-- qui aura sa fiche. Cuba Aliados (Aliados au recensement) prend le nom
-- sous lequel elle se vend ; Oliva la possède depuis 2021 sans posséder
-- la fabrique Aladino qui la roule, elle garde donc sa fiche.
-- Traductions : « caviste » était devenu « marchand de vin » dans les
-- cinq langues (Don Zuarin) ; la consigne de traduction le dit
-- désormais. « Une combustion meilleure » aurait donné أفضل en arabe,
-- « la ligne Panama est la plus ancienne » un superlatif dans quatre
-- langues : le français dit « choisie pour sa combustion » et « la ligne
-- d'origine ». Deux 第一 chinois (SYN, Mara) deviennent 头一周 et
-- 前三分之一段.
--
-- ── DIVERGENCES ÉCRITES ─────────────────────────────────
-- Valentino Siesto : la maison date sa fabrique de 2014, un portrait
-- paru en espagnol place un premier partenariat en 2005 et le lancement
-- commercial en 2018. Horacio : 2008 selon la maison, 2006 selon House
-- of Grauer. Nordlicht : premiers cigares en 2017, mélange arrêté en
-- 2018. Mara : Cigarworld.de attribue la Marabunta à la fabrique Oveja
-- Negra, qui ne cite pas Mara parmi ses marques. Ibis Nicaragua :
-- corsée pour Cigarworld.de, medium pour Noblego.de.
--
-- Rejouable : INSERT … ON DUPLICATE KEY UPDATE ; le `brands` des pays
-- touchés est relu en base et réécrit en littéral ; sceaux `machine`.
-- ════════════════════════════════════════════════════════

-- ── Cigarkings ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Cigarkings',
        'nicaragua',
        '2016 — Philipp Kugler, Munich',
        'Estelí, Nicaragua — la maison ne nomme pas sa fabrique',
        'cigarkings.de « Nicaragua » (consulté 2026-09-24 : roulage à la main à Estelí, méthode Entubado à triple cape de tête, cape naturelle Sun Grown, six formats du Petit Robusto au Toro, fabrique non nommée) ; cigarkings.de « Impressum » (consulté 2026-09-24 : Philipp Kugler gérant, siège Drosselweg 15, Munich) ; northdata.com « CigarKings GmbH » (consulté 2026-09-24 : société constituée en décembre 2016, gérant Philipp Kugler, Munich, capital de 25 000 €) ; cigarworld.de « Cigarkings: Zigarren kaufen » (consulté 2026-09-24 : lignes Sun Grown et Maduro sur tabac H2000 nicaraguayen, petite fabrique familiale à Estelí tenue secrète, méthode Entubado) ; halfwheel.com « CigarKings Releasing COY 24 Geniales Colorado At Intertabac 2024 » (2024 : robusto 5 x 52, fabrique non nommée) ; halfwheel.com « CigarKings COY 25 Majestic Flag Tail Debuting At Intertabac 2025 » (2025 : COY 25 débute à Intertabac 2025, COY 26 Aero Lancero déjà annoncé pour l''année suivante)',
        NULL,
        'CigarKings GmbH est constituée en décembre 2016 à Munich, où Philipp Kugler en est le gérant, selon le registre du commerce allemand. Sous la marque CigarKings, les Longfiller de la maison sont roulés à la main à Estelí, au Nicaragua, par des rouleurs cubains exilés — seize, dit la maison —, selon la méthode Entubado, à triple cape de tête, qui multiplie les canaux de combustion. La maison dit la fabrique petite et familiale, et la tient secrète : elle ne la nomme pas.

En septembre 2026, le catalogue compte deux assemblages : Sun Grown, en cape naturelle du même nom sur tripe nicaraguayenne H2000, que la maison dit sans Ligero et à teneur en nicotine relativement basse, et Maduro, sur la même tripe, que la maison dit douce et sucrée. Six formats se déclinent en Petit Robusto, Coronita FT, Corona, Robusto, Elegantes et Toro. S''y ajoute une série d''éditions limitées annuelles, les COY, présentées chaque année à Intertabac : COY 24 Geniales Colorado, en robusto (5 x 52), en 2024, puis COY 25 Majestic Flag Tail en 2025, et un COY 26 Aero Lancero déjà annoncé, dit halfwheel. Cigarworld.de tient la marque au catalogue.',
        '[{"name":"Sun Grown","color":"#A0522D","force":null,"wrapper":"Sun Grown","vitolas":[],"story":"Cape naturelle sur tripe nicaraguayenne H2000, roulée en Entubado ; six formats, du Petit Robusto au Toro, dite par la maison sans Ligero et à faible teneur en nicotine."},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"Cape Maduro sur la même tripe H2000, même roulage en Entubado, dite douce et sucrée par la maison."},{"name":"COY","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Série d''éditions limitées présentées chaque année à Intertabac, de cape variable selon le millésime : COY 24 Geniales Colorado en robusto (5 x 52) en 2024, COY 25 Majestic Flag Tail en 2025, puis COY 26 Aero Lancero annoncé, dit halfwheel."}]',
        'CigarKings GmbH was incorporated in Munich in December 2016, where Philipp Kugler is managing director, according to the German commercial register. Under the CigarKings brand, the house''s Longfiller cigars are hand-rolled in Estelí, Nicaragua, by exiled Cuban rollers — sixteen, the house says — using the Entubado method, with a triple-layered head cap, which multiplies the burn channels. The house describes the factory as small and family-run, and keeps it secret: it does not name it.

In September 2026, the catalogue comprises two blends: Sun Grown, in a natural wrapper of the same name on Nicaraguan H2000 filler, which the house says is Ligero-free and relatively low in nicotine, and Maduro, on the same filler, which the house says is mild and sweet. Six formats are offered: Petit Robusto, Coronita FT, Corona, Robusto, Elegantes and Toro. These are joined by a series of annual limited editions, the COY, unveiled each year at Intertabac: COY 24 Geniales Colorado, in robusto (5 x 52), in 2024, then COY 25 Majestic Flag Tail in 2025, and a COY 26 Aero Lancero already announced, says halfwheel. Cigarworld.de keeps the brand in its catalogue.',
        '[{"name":"Sun Grown","color":"#A0522D","force":null,"wrapper":"Sun Grown","vitolas":[],"story":"Natural wrapper on Nicaraguan H2000 filler, rolled in Entubado; six formats, from Petit Robusto to Toro, said by the house to be Ligero-free and low in nicotine."},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"Maduro wrapper on the same H2000 filler, also rolled in Entubado, described by the house as mild and sweet."},{"name":"COY","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Series of limited editions unveiled each year at Intertabac, with wrapper varying by vintage: COY 24 Geniales Colorado in robusto (5 x 52) in 2024, COY 25 Majestic Flag Tail in 2025, then COY 26 Aero Lancero announced, says halfwheel."}]',
        'CigarKings GmbH se constituyó en Múnich en diciembre de 2016, donde Philipp Kugler es el gerente, según el registro mercantil alemán. Bajo la marca CigarKings, los Longfiller de la casa se lían a mano en Estelí, Nicaragua, por torcedores cubanos exiliados —dieciséis, según la casa—, siguiendo el método Entubado, con triple capa en la cabeza, que multiplica los canales de combustión. La casa describe la fábrica como pequeña y familiar, y la mantiene en secreto: no la nombra.

En septiembre de 2026, el catálogo cuenta con dos mezclas: Sun Grown, con capa natural del mismo nombre sobre tripa nicaragüense H2000, que la casa describe sin Ligero y con un contenido de nicotina relativamente bajo, y Maduro, sobre la misma tripa, que la casa describe suave y dulce. Se ofrecen seis formatos: Petit Robusto, Coronita FT, Corona, Robusto, Elegantes y Toro. A ellos se suma una serie de ediciones limitadas anuales, las COY, presentadas cada año en Intertabac: COY 24 Geniales Colorado, en robusto (5 x 52), en 2024, después COY 25 Majestic Flag Tail en 2025, y un COY 26 Aero Lancero ya anunciado, según halfwheel. Cigarworld.de mantiene la marca en su catálogo.',
        '[{"name":"Sun Grown","color":"#A0522D","force":null,"wrapper":"Sun Grown","vitolas":[],"story":"Capa natural sobre tripa nicaragüense H2000, liada en Entubado; seis formatos, de Petit Robusto a Toro, que la casa describe sin Ligero y con bajo contenido de nicotina."},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"Capa Maduro sobre la misma tripa H2000, también liada en Entubado, que la casa describe suave y dulce."},{"name":"COY","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Serie de ediciones limitadas presentadas cada año en Intertabac, de capa variable según la añada: COY 24 Geniales Colorado en robusto (5 x 52) en 2024, COY 25 Majestic Flag Tail en 2025, y después COY 26 Aero Lancero anunciado, según halfwheel."}]',
        'CigarKings GmbH wurde im Dezember 2016 in München gegründet, wo Philipp Kugler laut deutschem Handelsregister Geschäftsführer ist. Unter der Marke CigarKings werden die Longfiller des Hauses in Estelí, Nicaragua, von kubanischen Exilrollern von Hand gerollt — sechzehn, so das Haus —, nach der Entubado-Methode mit dreifacher Kopfkappe, die die Verbrennungskanäle vervielfacht. Das Haus bezeichnet die Fabrik als klein und familiengeführt und hält sie geheim: Es nennt sie nicht.

Im September 2026 umfasst das Sortiment zwei Mischungen: Sun Grown, mit gleichnamigem Naturdeckblatt auf nicaraguanischer H2000-Einlage, die laut Haus ohne Ligero auskommt und relativ nikotinarm ist, und Maduro, auf derselben Einlage, die das Haus als mild und süß bezeichnet. Sechs Formate stehen zur Wahl: Petit Robusto, Coronita FT, Corona, Robusto, Elegantes und Toro. Hinzu kommt eine Reihe jährlicher limitierter Editionen, die COY, die jedes Jahr auf der Intertabac vorgestellt werden: COY 24 Geniales Colorado, als Robusto (5 x 52), im Jahr 2024, dann COY 25 Majestic Flag Tail im Jahr 2025, und ein bereits angekündigter COY 26 Aero Lancero, so halfwheel. Cigarworld.de führt die Marke im Sortiment.',
        '[{"name":"Sun Grown","color":"#A0522D","force":null,"wrapper":"Sun Grown","vitolas":[],"story":"Naturdeckblatt auf nicaraguanischer H2000-Einlage, im Entubado-Verfahren gerollt; sechs Formate, von Petit Robusto bis Toro, laut Haus ohne Ligero und mit niedrigem Nikotingehalt."},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"Maduro-Deckblatt auf derselben H2000-Einlage, ebenfalls im Entubado-Verfahren gerollt, vom Haus als mild und süß beschrieben."},{"name":"COY","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Reihe limitierter Editionen, die jedes Jahr auf der Intertabac vorgestellt werden, mit je nach Jahrgang wechselndem Deckblatt: COY 24 Geniales Colorado als Robusto (5 x 52) im Jahr 2024, COY 25 Majestic Flag Tail im Jahr 2025, dann der angekündigte COY 26 Aero Lancero, so halfwheel."}]',
        'CigarKings GmbH于2016年12月在慕尼黑成立，据德国商业登记记载，Philipp Kugler担任总经理。在CigarKings品牌之下，该厂的Longfiller雪茄由古巴流亡卷烟师在尼加拉瓜埃斯特利手工卷制而成——据厂方称共十六人——采用Entubado卷制法，头部三层包裹，从而增加燃烧通道。厂方称工厂规模小、属家族经营，并对外保密，不透露厂名。

2026年9月，产品目录包括两款配方：Sun Grown采用同名天然茄衣，配尼加拉瓜H2000茄芯，厂方称不含Ligero，烟碱含量相对较低；Maduro配方采用相同茄芯，厂方称口感温和香甜。共有六种规格：Petit Robusto、Coronita FT、Corona、Robusto、Elegantes和Toro。此外还有一系列年度限量版，即COY系列，每年在Intertabac展会上推出：COY 24 Geniales Colorado为Robusto（5 x 52），推出于2024年；其后是2025年的COY 25 Majestic Flag Tail；据halfwheel报道，COY 26 Aero Lancero已预告推出。Cigarworld.de将该品牌保留在产品目录中。',
        '[{"name":"Sun Grown","color":"#A0522D","force":null,"wrapper":"Sun Grown","vitolas":[],"story":"天然茄衣配尼加拉瓜H2000茄芯，采用Entubado卷制法；共六种规格，从Petit Robusto到Toro，厂方称不含Ligero，烟碱含量低。"},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"Maduro茄衣配相同H2000茄芯，同样采用Entubado卷制法，厂方称其口感温和香甜。"},{"name":"COY","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"一系列每年在Intertabac展会推出的限量版，茄衣依年份而异：COY 24 Geniales Colorado为Robusto（5 x 52），推出于2024年；COY 25 Majestic Flag Tail推出于2025年；据halfwheel报道，其后预告推出COY 26 Aero Lancero。"}]',
        'تأسست شركة CigarKings GmbH في ديسمبر 2016 في ميونخ، حيث يشغل Philipp Kugler منصب المدير، وفقًا للسجل التجاري الألماني. تحت علامة CigarKings، تُلف سيجار Longfiller الخاصة بالبيت يدويًا في إستيلي بنيكاراغوا، على يد لفّافين كوبيين منفيين — ستة عشر، بحسب البيت —، باتباع طريقة Entubado، بغطاء رأس ثلاثي الطبقات يضاعف قنوات الاحتراق. يصف البيت المصنع بأنه صغير وعائلي، ويحتفظ بسرّيته: فهو لا يذكر اسمه.

في سبتمبر 2026، تضم القائمة مزيجين: Sun Grown، بغلاف طبيعي يحمل الاسم نفسه فوق حشوة نيكاراغوية من نوع H2000، يصفه البيت بأنه خالٍ من Ligero ومنخفض النيكوتين نسبيًا، وMaduro، على الحشوة نفسها، يصفه البيت بأنه معتدل وحلو المذاق. وتُعرض ستة مقاسات: Petit Robusto وCoronita FT وCorona وRobusto وElegantes وToro. وتضاف إلى ذلك سلسلة إصدارات سنوية محدودة، هي COY، تُعرض كل عام في Intertabac: COY 24 Geniales Colorado، من فئة robusto (5 x 52)، في 2024، ثم COY 25 Majestic Flag Tail في 2025، وCOY 26 Aero Lancero الذي أُعلن عنه بالفعل، بحسب halfwheel. ويحتفظ Cigarworld.de بالعلامة في قائمته.',
        '[{"name":"Sun Grown","color":"#A0522D","force":null,"wrapper":"Sun Grown","vitolas":[],"story":"غلاف طبيعي فوق حشوة نيكاراغوية H2000، يُلف بطريقة Entubado؛ ستة مقاسات، من Petit Robusto إلى Toro، يصفه البيت بأنه خالٍ من Ligero ومنخفض النيكوتين."},{"name":"Maduro","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"غلاف Maduro فوق الحشوة H2000 نفسها، ويُلف بالطريقة نفسها Entubado، ويصفه البيت بأنه معتدل وحلو المذاق."},{"name":"COY","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"سلسلة إصدارات محدودة تُعرض كل عام في Intertabac، بغلاف يتغيّر بحسب سنة الحصاد: COY 24 Geniales Colorado من فئة robusto (5 x 52) في 2024، وCOY 25 Majestic Flag Tail في 2025، ثم COY 26 Aero Lancero الذي أُعلن عنه، بحسب halfwheel."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── CSC ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('CSC',
        'nicaragua',
        '2015 — CSC Cigars GmbH, Pforzheim',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'cigarseedcompany.eu/en « CSC Cigars » (consulté 2026-09-24 : mention « EST. 2015 », commerce direct avec des producteurs du Nicaragua, roulage à la main, collections Notorious et Fire Oak citées) ; cigarseedcompany.eu/en/pages/kontakt « Contact » (consulté 2026-09-24 : cigares roulés à la main par des experts au Nicaragua, ni fondateur ni fabrique nommés) ; cigarseedcompany.eu/en/collections/cigars « Cigars » (consulté 2026-09-24 : vingt-deux références listées, dont Turtle Short, Castro Robusto, Fire Oak, Genios, Winston Dream, 18 Years, Baron No.1 et Diamond Signature, sans détail de cape, de sous-cape, de tripe ou de force) ; cigarworld.de « CSC Fire Oak Zigarre kaufen » (consulté 2026-09-24 : tabac en partie fermenté en fûts de whisky calcinés, vieilli au moins sept ans, quatre formats — Churchill, Gigante, Toro, Robusto —, classée Nicaragua par le revendeur)',
        NULL,
        'CSC — Cigar Seed Company — est une maison allemande de Pforzheim, qui dit avoir été fondée en 2015. Elle dit pratiquer un commerce direct avec des producteurs du Nicaragua, où ses cigares sont roulés à la main ; elle ne nomme ni son fondateur ni sa fabrique.

En septembre 2026, la maison propose une vingtaine de références, dont elle ne publie le plus souvent que le nom. Fire Oak, dont une partie du tabac est fermentée dans d''anciens fûts de whisky calcinés puis vieillie au moins sept ans, dit Cigarworld.de, se décline en quatre formats — Churchill, Gigante, Toro et Robusto. Notorious, que la maison présente comme sa collection principale, compte trois variantes, Crème de la Crème, O.G. et Unapologetic. Une ligne 18 Years, en Robusto, complète l''ensemble.',
        '[{"name":"Fire Oak","color":"#6B4226","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Tabac en partie fermenté dans d''anciens fûts de whisky calcinés et vieilli au moins sept ans, dit Cigarworld.de ; en quatre formats, Churchill, Gigante, Toro et Robusto."},{"name":"Notorious","color":"#4A3728","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Collection que la maison présente comme sa ligne principale, en trois variantes : Crème de la Crème, O.G. et Unapologetic."},{"name":"18 Years","color":"#4A2C1A","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne en Robusto ; la maison n''en publie ni cape ni force."}]',
        'CSC — Cigar Seed Company — is a German house based in Pforzheim, which says it was founded in 2015. It says it trades directly with producers in Nicaragua, where its cigars are hand-rolled; it names neither its founder nor its factory.

In September 2026, the house offers around twenty references, for most of which it publishes only the name. Fire Oak, part of whose tobacco is fermented in former charred whisky barrels and then aged at least seven years, says Cigarworld.de, comes in four formats — Churchill, Gigante, Toro and Robusto. Notorious, which the house presents as its main line, has three variants, Crème de la Crème, O.G. and Unapologetic. An 18 Years line, in Robusto, completes the range.',
        '[{"name":"Fire Oak","color":"#6B4226","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Tobacco partly fermented in former charred whisky barrels and aged at least seven years, says Cigarworld.de; in four formats, Churchill, Gigante, Toro and Robusto."},{"name":"Notorious","color":"#4A3728","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Collection presented by the house as its main line, in three variants: Crème de la Crème, O.G. and Unapologetic."},{"name":"18 Years","color":"#4A2C1A","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Robusto line; the house publishes neither wrapper nor strength for it."}]',
        'CSC — Cigar Seed Company — es una casa alemana de Pforzheim que dice haber sido fundada en 2015. Dice comerciar directamente con productores de Nicaragua, donde sus puros se lían a mano; no nombra ni a su fundador ni a su fábrica.

En septiembre de 2026, la casa ofrece una veintena de referencias, de las que casi siempre publica solo el nombre. Fire Oak, cuyo tabaco se fermenta en parte en antiguos barriles de whisky calcinados y después se añeja al menos siete años, según Cigarworld.de, se presenta en cuatro formatos —Churchill, Gigante, Toro y Robusto—. Notorious, que la casa presenta como su línea principal, cuenta con tres variantes, Crème de la Crème, O.G. y Unapologetic. Una línea 18 Years, en Robusto, completa el conjunto.',
        '[{"name":"Fire Oak","color":"#6B4226","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Tabaco en parte fermentado en antiguos barriles de whisky calcinados y añejado al menos siete años, según Cigarworld.de; en cuatro formatos, Churchill, Gigante, Toro y Robusto."},{"name":"Notorious","color":"#4A3728","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Colección que la casa presenta como su línea principal, en tres variantes: Crème de la Crème, O.G. y Unapologetic."},{"name":"18 Years","color":"#4A2C1A","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea en Robusto; la casa no publica ni capa ni fuerza para ella."}]',
        'CSC — Cigar Seed Company — ist ein deutsches Haus aus Pforzheim, das angibt, 2015 gegründet worden zu sein. Es gibt an, direkt mit Erzeugern aus Nicaragua zu handeln, wo seine Zigarren von Hand gerollt werden; weder Gründer noch Fabrik werden genannt.

Im September 2026 bietet das Haus rund zwanzig Sorten an, von denen es meist nur den Namen veröffentlicht. Fire Oak, dessen Tabak laut Cigarworld.de teilweise in ehemaligen, ausgebrannten Whiskyfässern fermentiert und danach mindestens sieben Jahre gelagert wird, gibt es in vier Formaten — Churchill, Gigante, Toro und Robusto. Notorious, das das Haus als seine Hauptlinie bezeichnet, umfasst drei Varianten, Crème de la Crème, O.G. und Unapologetic. Eine Linie 18 Years, als Robusto, vervollständigt das Sortiment.',
        '[{"name":"Fire Oak","color":"#6B4226","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Tabak, der laut Cigarworld.de teilweise in ehemaligen, ausgebrannten Whiskyfässern fermentiert und mindestens sieben Jahre gelagert wird; in vier Formaten, Churchill, Gigante, Toro und Robusto."},{"name":"Notorious","color":"#4A3728","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Kollektion, die das Haus als seine Hauptlinie bezeichnet, in drei Varianten: Crème de la Crème, O.G. und Unapologetic."},{"name":"18 Years","color":"#4A2C1A","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie als Robusto; das Haus nennt dafür weder Deckblatt noch Stärke."}]',
        'CSC——Cigar Seed Company——是一家总部位于普福尔茨海姆的德国厂牌，据称成立于2015年。该厂称与尼加拉瓜的烟农直接交易，其雪茄在当地手工卷制；厂方未透露创始人姓名，也未公开工厂名称。

2026年9月，该厂提供约二十款产品，多数只公开名称。据Cigarworld.de报道，Fire Oak部分烟叶在旧威士忌炭化酒桶中发酵，随后陈化至少七年，有Churchill、Gigante、Toro和Robusto四种规格。Notorious系列被厂方称为其主要系列，包含三个版本：Crème de la Crème、O.G.和Unapologetic。18 Years系列为Robusto规格，完善了整体产品线。',
        '[{"name":"Fire Oak","color":"#6B4226","force":null,"wrapper":"未公开","vitolas":[],"story":"据Cigarworld.de报道，部分烟叶在旧威士忌炭化酒桶中发酵，陈化至少七年；共四种规格：Churchill、Gigante、Toro和Robusto。"},{"name":"Notorious","color":"#4A3728","force":null,"wrapper":"未公开","vitolas":[],"story":"厂方称为其主要系列的产品线，包含三个版本：Crème de la Crème、O.G.和Unapologetic。"},{"name":"18 Years","color":"#4A2C1A","force":null,"wrapper":"未公开","vitolas":[],"story":"Robusto规格产品线；厂方未公开其茄衣或力度。"}]',
        'CSC — Cigar Seed Company — بيت ألماني مقرّه بفورتسهايم، يقول إنه تأسس في 2015. ويذكر أنه يتاجر مباشرة مع منتِجين من نيكاراغوا، حيث تُلف سيجاراته يدويًا؛ ولا يذكر مؤسسه ولا مصنعه.

في سبتمبر 2026، يعرض البيت نحو عشرين صنفًا، لا ينشر عن معظمها سوى الاسم. Fire Oak، الذي يُخمَّر جزء من تبغه في براميل ويسكي قديمة محروقة ثم يُعتَّق مدة سبع سنوات على الأقل، بحسب Cigarworld.de، يُقدَّم في أربعة مقاسات — Churchill وGigante وToro وRobusto. أما Notorious، الذي يقدّمه البيت باعتباره خطّه الرئيسي، فيضم ثلاثة أصناف: Crème de la Crème وO.G. وUnapologetic. ويكمل المجموعة خط 18 Years، من فئة Robusto.',
        '[{"name":"Fire Oak","color":"#6B4226","force":null,"wrapper":"غير معلن","vitolas":[],"story":"تبغ يُخمَّر جزء منه في براميل ويسكي قديمة محروقة ويُعتَّق مدة سبع سنوات على الأقل، بحسب Cigarworld.de؛ في أربعة مقاسات، Churchill وGigante وToro وRobusto."},{"name":"Notorious","color":"#4A3728","force":null,"wrapper":"غير معلن","vitolas":[],"story":"مجموعة يقدّمها البيت باعتبارها خطّه الرئيسي، بثلاثة أصناف: Crème de la Crème وO.G. وUnapologetic."},{"name":"18 Years","color":"#4A2C1A","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط من فئة Robusto؛ لا ينشر البيت له غلافًا ولا قوة."}]')
