-- ── Despot ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Despot',
        'nicaragua',
        '2019 — Jovan et Ugljesa Despot, Serbie',
        'Estelí, Nicaragua — la maison ne nomme pas sa fabrique',
        'despotcigars.com « Home » (consulté 2026-09-24 : Jovan et Ugljesa Despot, deuxième génération familiale, leur père ayant lancé le marché du cigare en Serbie en 2004, lancement de leur propre marque en 2019, cigares roulés main en feuilles entières à Estelí, fabrique non nommée) ; luxurycigarclub.com « Despot Cigars » (consulté 2026-09-23 : longfiller roulé main à Estelí) ; blindmanspuff.com « Despot Series J Lancero – Blind Cigar Review » (2022-10 : revue du Series J Lancero, longfiller roulé main à Estelí) ; hall4d21.com « Despot » (2024 : présence de la marque au salon Intertabac de Dortmund) ; cigarcentury.com « Despot » (consulté 2026-09-24 : cape, sous-cape, tripe et force détaillées des Series J, U et Z)',
        NULL,
        'Despot Cigars est fondée en 2019 par les frères serbes Jovan et Ugljesa Despot, dit la maison : deuxième génération de leur famille dans le cigare, leur père ayant lancé le marché du cigare en Serbie en 2004. Les deux frères choisissent le Nicaragua pour assembler et rouler leur marque, à partir de feuilles entières roulées à la main à Estelí ; la maison ne nomme pas la fabrique.

Le catalogue compte trois séries. La Series J, la première, rend hommage aux formats classiques, dit la maison : cape et sous-cape en Habano équatorien, tripe nicaraguayenne d''Estelí, force medium, en Corona, Lancero, Pirámides et Robusto. La Series U mise sur l''arôme plus que sur la puissance, dit la maison, avec la même cape et une tripe mêlant Pennsylvanie (États-Unis), Jalapa et Estelí, en formats Salomone et Double Corona notamment. La Series Z, plus récente, associe une cape équatorienne — décrite tantôt en Rosado, tantôt en Claro selon les revendeurs — à une tripe de Jalapa et d''Ometepe, pour une force medium à medium-full, en formats R54, T54, Piramides Grande et A Size.

En 2024, la marque se présente au salon Intertabac de Dortmund ; en septembre 2026, elle est en vente chez Luxury Cigar Club et Cigar Century.',
        '[{"name":"Series J","color":"#A0522D","force":"Medium","wrapper":"Habano équatorien","vitolas":[],"story":"Première série de la marque, en hommage aux formats classiques ; tripe nicaraguayenne d''Estelí, en Corona, Lancero, Pirámides et Robusto."},{"name":"Series U","color":"#8B5A2B","force":"Medium","wrapper":"Habano équatorien","vitolas":[],"story":"Axée sur l''arôme plus que sur la puissance, dit la maison ; tripe de Pennsylvanie (États-Unis), de Jalapa et d''Estelí, en Salomone et Double Corona notamment."},{"name":"Series Z","color":"#6B4226","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Cape équatorienne décrite tantôt en Rosado, tantôt en Claro selon les revendeurs ; tripe de Jalapa et d''Ometepe, en formats R54, T54, Piramides Grande et A Size."}]',
        'Despot Cigars was founded in 2019 by Serbian brothers Jovan and Ugljesa Despot, says the house: the second generation of their family in cigars, their father having launched the cigar market in Serbia in 2004. The two brothers chose Nicaragua to blend and roll their brand, from whole leaves hand-rolled in Estelí; the house does not name the factory.

The catalogue comprises three series. The Series J, the first, pays tribute to classic formats, says the house: wrapper and binder in Ecuadorian Habano, Nicaraguan filler from Estelí, medium strength, in Corona, Lancero, Pirámides and Robusto. The Series U focuses on aroma rather than power, says the house, with the same wrapper and a filler blending Pennsylvania (United States), Jalapa and Estelí, in Salomone and Double Corona formats among others. The Series Z, more recent, pairs an Ecuadorian wrapper — described variously as Rosado or Claro depending on the retailer — with a Jalapa and Ometepe filler, for a medium to medium-full strength, in R54, T54, Piramides Grande and A Size formats.

In 2024, the brand appeared at the Intertabac trade fair in Dortmund; in September 2026, it is sold at Luxury Cigar Club and Cigar Century.',
        '[{"name":"Series J","color":"#A0522D","force":"Medium","wrapper":"Ecuadorian Habano","vitolas":[],"story":"The brand''s first series, paying tribute to classic formats; Nicaraguan filler from Estelí, in Corona, Lancero, Pirámides and Robusto."},{"name":"Series U","color":"#8B5A2B","force":"Medium","wrapper":"Ecuadorian Habano","vitolas":[],"story":"Focused on aroma rather than power, says the house; filler from Pennsylvania (United States), Jalapa and Estelí, in Salomone and Double Corona among others."},{"name":"Series Z","color":"#6B4226","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"Ecuadorian wrapper described variously as Rosado or Claro depending on the retailer; filler from Jalapa and Ometepe, in R54, T54, Piramides Grande and A Size formats."}]',
        'Despot Cigars se funda en 2019 por los hermanos serbios Jovan y Ugljesa Despot, dice la casa: segunda generación de su familia en el mundo del puro, ya que su padre lanzó el mercado del puro en Serbia en 2004. Los dos hermanos eligen Nicaragua para mezclar y liar su marca, a partir de hojas enteras liadas a mano en Estelí; la casa no nombra la fábrica.

El catálogo cuenta con tres series. La Series J, la primera, rinde homenaje a los formatos clásicos, dice la casa: capa y capote en Habano ecuatoriano, tripa nicaragüense de Estelí, fuerza medium, en Corona, Lancero, Pirámides y Robusto. La Series U apuesta por el aroma más que por la potencia, dice la casa, con la misma capa y una tripa que mezcla Pensilvania (Estados Unidos), Jalapa y Estelí, en formatos Salomone y Double Corona entre otros. La Series Z, más reciente, combina una capa ecuatoriana —descrita a veces como Rosado, a veces como Claro según el vendedor— con una tripa de Jalapa y Ometepe, para una fuerza medium a medium-full, en formatos R54, T54, Piramides Grande y A Size.

En 2024, la marca se presenta en el salón Intertabac de Dortmund; en septiembre de 2026, se vende en Luxury Cigar Club y Cigar Century.',
        '[{"name":"Series J","color":"#A0522D","force":"Medium","wrapper":"Habano ecuatoriano","vitolas":[],"story":"Primera serie de la marca, en homenaje a los formatos clásicos; tripa nicaragüense de Estelí, en Corona, Lancero, Pirámides y Robusto."},{"name":"Series U","color":"#8B5A2B","force":"Medium","wrapper":"Habano ecuatoriano","vitolas":[],"story":"Centrada en el aroma más que en la potencia, dice la casa; tripa de Pensilvania (Estados Unidos), Jalapa y Estelí, en Salomone y Double Corona entre otros."},{"name":"Series Z","color":"#6B4226","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Capa ecuatoriana descrita a veces como Rosado, a veces como Claro según el vendedor; tripa de Jalapa y Ometepe, en formatos R54, T54, Piramides Grande y A Size."}]',
        'Despot Cigars wird 2019 von den serbischen Brüdern Jovan und Ugljesa Despot gegründet, so das Haus: zweite Generation ihrer Familie im Zigarrengeschäft, nachdem ihr Vater 2004 den Zigarrenmarkt in Serbien begründet hatte. Die beiden Brüder wählen Nicaragua, um ihre Marke zu mischen und zu rollen, aus ganzen Blättern, die in Estelí von Hand gerollt werden; das Haus nennt die Fabrik nicht.

Das Sortiment umfasst drei Serien. Die Series J, die erste, würdigt die klassischen Formate, so das Haus: Deckblatt und Umblatt aus ecuadorianischem Habano, nicaraguanische Einlage aus Estelí, Stärke medium, als Corona, Lancero, Pirámides und Robusto. Die Series U setzt eher auf Aroma als auf Kraft, so das Haus, mit demselben Deckblatt und einer Einlage aus Pennsylvania (USA), Jalapa und Estelí, unter anderem in den Formaten Salomone und Double Corona. Die Series Z, jüngeren Datums, verbindet ein ecuadorianisches Deckblatt — je nach Händler mal als Rosado, mal als Claro beschrieben — mit einer Einlage aus Jalapa und Ometepe, Stärke medium bis medium-full, in den Formaten R54, T54, Piramides Grande und A Size.

Im Jahr 2024 präsentiert sich die Marke auf der Intertabac in Dortmund; im September 2026 wird sie bei Luxury Cigar Club und Cigar Century verkauft.',
        '[{"name":"Series J","color":"#A0522D","force":"Medium","wrapper":"ecuadorianischer Habano","vitolas":[],"story":"Erste Serie der Marke, eine Hommage an die klassischen Formate; nicaraguanische Einlage aus Estelí, als Corona, Lancero, Pirámides und Robusto."},{"name":"Series U","color":"#8B5A2B","force":"Medium","wrapper":"ecuadorianischer Habano","vitolas":[],"story":"Setzt eher auf Aroma als auf Kraft, so das Haus; Einlage aus Pennsylvania (USA), Jalapa und Estelí, unter anderem als Salomone und Double Corona."},{"name":"Series Z","color":"#6B4226","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Ecuadorianisches Deckblatt, je nach Händler mal als Rosado, mal als Claro beschrieben; Einlage aus Jalapa und Ometepe, in den Formaten R54, T54, Piramides Grande und A Size."}]',
        'Despot Cigars由塞尔维亚兄弟Jovan和Ugljesa Despot于2019年创立，据厂方介绍：这是他们家族在雪茄行业的第二代，其父亲曾于2004年开创塞尔维亚的雪茄市场。两兄弟选择在尼加拉瓜调配和卷制自己的品牌，采用在埃斯特利手工卷制的整片烟叶；厂方未公开工厂名称。

产品目录包括三个系列。Series J是首个系列，向经典规格致敬，据厂方介绍：茄衣和茄套采用厄瓜多尔Habano，茄芯为尼加拉瓜埃斯特利烟叶，力度medium，规格有Corona、Lancero、Pirámides和Robusto。Series U更侧重香气而非力度，据厂方介绍，茄衣相同，茄芯混合了宾夕法尼亚（美国）、哈拉帕和埃斯特利烟叶，规格包括Salomone和Double Corona等。较新推出的Series Z，茄衣产自厄瓜多尔——据经销商描述有时为Rosado，有时为Claro——搭配哈拉帕和奥梅特佩的茄芯，力度medium至medium-full，规格有R54、T54、Piramides Grande和A Size。

2024年，该品牌亮相多特蒙德Intertabac展会；截至2026年9月，其产品在Luxury Cigar Club和Cigar Century有售。',
        '[{"name":"Series J","color":"#A0522D","force":"Medium","wrapper":"厄瓜多尔Habano","vitolas":[],"story":"品牌首个系列，向经典规格致敬；茄芯为尼加拉瓜埃斯特利烟叶，规格有Corona、Lancero、Pirámides和Robusto。"},{"name":"Series U","color":"#8B5A2B","force":"Medium","wrapper":"厄瓜多尔Habano","vitolas":[],"story":"据厂方介绍，更侧重香气而非力度；茄芯来自宾夕法尼亚（美国）、哈拉帕和埃斯特利，规格包括Salomone和Double Corona等。"},{"name":"Series Z","color":"#6B4226","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"厄瓜多尔茄衣，据经销商描述有时为Rosado，有时为Claro；茄芯来自哈拉帕和奥梅特佩，规格有R54、T54、Piramides Grande和A Size。"}]',
        'تأسست Despot Cigars عام 2019 على يد الأخوين الصربيين Jovan وUgljesa Despot، بحسب البيت: وهما الجيل الثاني من أسرتهما في عالم السيجار، إذ كان والدهما قد أطلق سوق السيجار في صربيا عام 2004. اختار الأخوان نيكاراغوا لمزج علامتهما ولفّها، انطلاقًا من أوراق كاملة تُلف يدويًا في إستيلي؛ ولا يذكر البيت اسم المصنع.

تضم القائمة ثلاث سلاسل. Series J، وهي الأولى، تكرّم المقاسات الكلاسيكية، بحسب البيت: غلاف ورباط من Habano إكوادوري، وحشوة نيكاراغوية من إستيلي، بقوة medium، في مقاسات Corona وLancero وPirámides وRobusto. أما Series U فتراهن على النكهة أكثر من القوة، بحسب البيت، بالغلاف نفسه وحشوة تمزج بنسلفانيا (الولايات المتحدة) وخالابا وإستيلي، في مقاسات منها Salomone وDouble Corona. أما Series Z، الأحدث، فتجمع بين غلاف إكوادوري — يوصف تارة بأنه Rosado وتارة بأنه Claro بحسب البائعين — وحشوة من خالابا وأوميتيبي، بقوة medium إلى medium-full، في مقاسات R54 وT54 وPiramides Grande وA Size.

في 2024، ظهرت العلامة في معرض Intertabac بدورتموند؛ وفي سبتمبر 2026، تُباع لدى Luxury Cigar Club وCigar Century.',
        '[{"name":"Series J","color":"#A0522D","force":"Medium","wrapper":"Habano إكوادوري","vitolas":[],"story":"أول سلسلة للعلامة، تكريمًا للمقاسات الكلاسيكية؛ حشوة نيكاراغوية من إستيلي، في مقاسات Corona وLancero وPirámides وRobusto."},{"name":"Series U","color":"#8B5A2B","force":"Medium","wrapper":"Habano إكوادوري","vitolas":[],"story":"تركّز على النكهة أكثر من القوة، بحسب البيت؛ حشوة من بنسلفانيا (الولايات المتحدة) وخالابا وإستيلي، في مقاسات منها Salomone وDouble Corona."},{"name":"Series Z","color":"#6B4226","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"غلاف إكوادوري يوصف تارة بأنه Rosado وتارة بأنه Claro بحسب البائعين؛ حشوة من خالابا وأوميتيبي، في مقاسات R54 وT54 وPiramides Grande وA Size."}]')
