-- ── Don Duarte ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Don Duarte',
        'nicaragua',
        '2008 — Roger Duarte Rodriguez, Estelí',
        'Chez Tabacalera Pages, en partenariat avec Cigar Conexion, Estelí',
        'donduarte.com « About Us » (consulté 2026-09-24 : fondateur Roger Duarte Rodriguez, famille pionnière d''Estelí, rencontre en 2001 avec le maître assembleur Evelio Oviedo et usage des services de Plasencia, reprise en 2020 par Cigar Conexion sous Fernando Navarro, production transférée en 2022 à la Tabacalera Pages, cape Jalapa remplacée par une cape équatorienne) ; donduarte.com « Products » (consulté 2026-09-24 : trois assemblages — Habano Clásico, Big Boys Clásico et Habano Reserva —, capes, vieillissement et force détaillés) ; donduarte.com « Reserva Privada » (consulté 2026-09-24 : cape Habano Rosado, sous-cape Habano, tripe nicaraguayenne vieillie au moins trois ans, force medium à forte, formats Pirámide 52, Robusto et Toro Grande 60) ; cigarinspector.com « Don Duarte is Back » (consulté 2026-09-24 : histoire familiale de Roger Duarte Rodriguez, fondation 2008, pause pour raisons de santé, retour de la marque) ; cigarjournal.com « Don Duarte and Villa Vieja Go Bigger » (2026-09-17 : Fernando Navarro fabrique chez son partenaire Raymond Pages, à la Tabacalera Pages d''Estelí, où se roule aussi Cuervo y Sobrinos ; deux nouveaux calibres 60 présentés à Intertabac 2026, le Super Ancho de Don Duarte et le Grandeur de la marque sœur Villa Vieja)',
        NULL,
        'Don Duarte naît en 2008, portée par le docteur Roger Duarte Rodriguez, dont la maison dit la famille pionnière d''Estelí. Dès 2001, il travaille avec le maître assembleur Evelio Oviedo à la mise au point de son cigare, d''abord roulé avec le concours de Plasencia, dit la maison. La marque connaît ensuite une pause, pour raisons de santé, avant de revenir, dit Cigarinspector.com.

En 2020, Cigar Conexion, que dirige Fernando Navarro, reprend Don Duarte, dit la maison ; en 2022, la fabrication passe à la Tabacalera Pages, à Estelí — l''usine de son partenaire Raymond Pages, où se roule aussi Cuervo y Sobrinos. La cape Jalapa d''origine cède la place à une cape équatorienne, choisie pour sa combustion, dit la maison. À l''Intertabac de septembre 2026, Navarro présente pour Don Duarte un nouveau calibre 60, le Super Ancho (4½ x 60), et pour sa marque sœur Villa Vieja un Grandeur (5½ x 60) : les deux gammes manquaient de calibres 60, dit-il.

En septembre 2026, le catalogue compte trois assemblages, dit la maison : le Habano Clásico, en cape Habano Rosado ou, en version Golden, en cape plus claire, tabacs vieillis deux ans, décliné aussi en formats plus larges sous le nom Big Boys ; le Habano Reserva, en cape Habano Rosado Oscuro, dite aussi Colorado, tabacs vieillis trois ans ; et la Reserva Privada, cape Habano Rosado et sous-cape Habano, tripe vieillie trois ans, jusqu''au calibre 60 (Toro Grande).',
        '[{"name":"Habano Clásico","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"En cape Habano Rosado (Intermedio) ou, en version Golden, en cape plus claire Habano Rosado Claro, tabacs vieillis deux ans, dit la maison, de force mild-medium à medium-full selon la vitola ; décliné aussi en formats plus larges sous le nom Big Boys."},{"name":"Habano Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano Rosado Oscuro","vitolas":[],"story":"Cape dite aussi Colorado par la maison, tabacs nicaraguayens vieillis trois ans."},{"name":"Reserva Privada","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Rosado","vitolas":[],"story":"Sous-cape Habano, tripe nicaraguayenne vieillie au moins trois ans, dit la maison ; trois formats dont un Toro Grande 60 (6 x 60)."}]',
        'Don Duarte was born in 2008, driven by Dr Roger Duarte Rodriguez, whose family the house describes as pioneers of Estelí. From 2001, he worked with master blender Evelio Oviedo to develop his cigar, at first rolled with the help of Plasencia, says the house. The brand then went through a pause, for health reasons, before returning, says Cigarinspector.com.

In 2020, Cigar Conexion, led by Fernando Navarro, took over Don Duarte, says the house; in 2022, production moved to the Tabacalera Pages, in Estelí — the factory of his partner Raymond Pages, where Cuervo y Sobrinos is also rolled. The original Jalapa wrapper gave way to an Ecuadorian wrapper, chosen for its burn, says the house. At Intertabac in September 2026, Navarro presented, for Don Duarte, a new 60 ring gauge, the Super Ancho (4½ x 60), and for its sister brand Villa Vieja, a Grandeur (5½ x 60): both ranges lacked a 60 ring gauge, he says.

In September 2026, the catalogue comprises three blends, says the house: the Habano Clásico, in Habano Rosado wrapper or, in the Golden version, a lighter wrapper, tobaccos aged two years, also offered in larger formats under the name Big Boys; the Habano Reserva, in Habano Rosado Oscuro wrapper, also called Colorado, tobaccos aged three years; and the Reserva Privada, Habano Rosado wrapper and Habano binder, filler aged three years, up to a 60 ring gauge (Toro Grande).',
        '[{"name":"Habano Clásico","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"In Habano Rosado (Intermedio) wrapper or, in the Golden version, a lighter Habano Rosado Claro wrapper, tobaccos aged two years, says the house, mild-medium to medium-full strength depending on the vitola; also offered in larger formats under the name Big Boys."},{"name":"Habano Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano Rosado Oscuro","vitolas":[],"story":"Wrapper also called Colorado by the house, Nicaraguan tobaccos aged three years."},{"name":"Reserva Privada","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Rosado","vitolas":[],"story":"Habano binder, Nicaraguan filler aged at least three years, says the house; three formats including a Toro Grande 60 (6 x 60)."}]',
        'Don Duarte nace en 2008, impulsada por el doctor Roger Duarte Rodriguez, cuya familia la casa describe como pionera de Estelí. Desde 2001, trabaja con el maestro mezclador Evelio Oviedo en la puesta a punto de su puro, liado al principio con el concurso de Plasencia, dice la casa. La marca conoce después una pausa, por motivos de salud, antes de regresar, dice Cigarinspector.com.

En 2020, Cigar Conexion, dirigida por Fernando Navarro, retoma Don Duarte, dice la casa; en 2022, la fabricación pasa a la Tabacalera Pages, en Estelí —la fábrica de su socio Raymond Pages, donde también se lía Cuervo y Sobrinos—. La capa Jalapa original cede su lugar a una capa ecuatoriana, elegida por su combustión, dice la casa. En el Intertabac de septiembre de 2026, Navarro presenta para Don Duarte un nuevo calibre 60, el Super Ancho (4½ x 60), y para su marca hermana Villa Vieja un Grandeur (5½ x 60): a ambas gamas les faltaba un calibre 60, dice él.

En septiembre de 2026, el catálogo cuenta con tres mezclas, dice la casa: el Habano Clásico, en capa Habano Rosado o, en versión Golden, en capa más clara, tabacos añejados dos años, disponible también en formatos más anchos bajo el nombre Big Boys; el Habano Reserva, en capa Habano Rosado Oscuro, llamada también Colorado, tabacos añejados tres años; y la Reserva Privada, capa Habano Rosado y capote Habano, tripa añejada tres años, hasta el calibre 60 (Toro Grande).',
        '[{"name":"Habano Clásico","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"En capa Habano Rosado (Intermedio) o, en versión Golden, en capa más clara Habano Rosado Claro, tabacos añejados dos años, dice la casa, de fuerza mild-medium a medium-full según la vitola; disponible también en formatos más anchos bajo el nombre Big Boys."},{"name":"Habano Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano Rosado Oscuro","vitolas":[],"story":"Capa llamada también Colorado por la casa, tabacos nicaragüenses añejados tres años."},{"name":"Reserva Privada","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Rosado","vitolas":[],"story":"Capote Habano, tripa nicaragüense añejada al menos tres años, dice la casa; tres formatos, entre ellos un Toro Grande 60 (6 x 60)."}]',
        'Don Duarte entsteht 2008, angestoßen von Dr. Roger Duarte Rodriguez, dessen Familie das Haus als Pioniere von Estelí bezeichnet. Ab 2001 arbeitet er mit dem Meisterblender Evelio Oviedo an der Entwicklung seiner Zigarre, zunächst mit Unterstützung von Plasencia gerollt, so das Haus. Die Marke legt danach aus gesundheitlichen Gründen eine Pause ein, bevor sie zurückkehrt, so Cigarinspector.com.

2020 übernimmt Cigar Conexion unter der Leitung von Fernando Navarro Don Duarte, so das Haus; 2022 wechselt die Fertigung zur Tabacalera Pages in Estelí — der Fabrik seines Partners Raymond Pages, wo auch Cuervo y Sobrinos gerollt wird. Das ursprüngliche Jalapa-Deckblatt weicht einem ecuadorianischen Deckblatt, gewählt wegen seines Abbrands, so das Haus. Auf der Intertabac im September 2026 stellt Navarro für Don Duarte ein neues Ringmaß 60 vor, den Super Ancho (4½ x 60), und für die Schwestermarke Villa Vieja einen Grandeur (5½ x 60): Beiden Linien habe ein Ringmaß 60 gefehlt, so Navarro.

Im September 2026 umfasst das Sortiment drei Mischungen, so das Haus: den Habano Clásico, mit Habano-Rosado-Deckblatt oder, in der Golden-Version, mit hellerem Deckblatt, Tabake zwei Jahre gelagert, auch in breiteren Formaten unter dem Namen Big Boys erhältlich; den Habano Reserva, mit Habano-Rosado-Oscuro-Deckblatt, auch Colorado genannt, Tabake drei Jahre gelagert; und die Reserva Privada, Habano-Rosado-Deckblatt und Habano-Umblatt, Einlage drei Jahre gelagert, bis zum Ringmaß 60 (Toro Grande).',
        '[{"name":"Habano Clásico","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Mit Habano-Rosado-Deckblatt (Intermedio) oder, in der Golden-Version, mit hellerem Habano-Rosado-Claro-Deckblatt, Tabake zwei Jahre gelagert, so das Haus, Stärke mild-medium bis medium-full je nach Vitola; auch in breiteren Formaten unter dem Namen Big Boys erhältlich."},{"name":"Habano Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano Rosado Oscuro","vitolas":[],"story":"Vom Haus auch als Colorado bezeichnetes Deckblatt, nicaraguanische Tabake drei Jahre gelagert."},{"name":"Reserva Privada","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Rosado","vitolas":[],"story":"Habano-Umblatt, nicaraguanische Einlage mindestens drei Jahre gelagert, so das Haus; drei Formate, darunter ein Toro Grande 60 (6 x 60)."}]',
        'Don Duarte品牌诞生于2008年，由医生Roger Duarte Rodriguez创立，厂方称其家族是埃斯特利的先驱。自2001年起，他与首席调配师Evelio Oviedo合作研发自己的雪茄，据厂方介绍，最初借助Plasencia卷制。此后，因健康原因，品牌一度停摆，后来重新回归，据Cigarinspector.com报道。

2020年，由Fernando Navarro执掌的Cigar Conexion接手Don Duarte，据厂方介绍；2022年，生产转移至埃斯特利的Tabacalera Pages——其合伙人Raymond Pages名下的工厂，Cuervo y Sobrinos同样在此卷制。原有的哈拉帕茄衣被厄瓜多尔茄衣取代，据厂方介绍，是因其燃烧特性而选定。2026年9月的Intertabac展会上，Navarro为Don Duarte推出新的60环径规格Super Ancho（4½ x 60），并为其姊妹品牌Villa Vieja推出Grandeur（5½ x 60）：据他介绍，两个系列此前都缺少60环径的规格。

2026年9月，产品目录包括三款配方，据厂方介绍：Habano Clásico采用Habano Rosado茄衣，或在Golden版本中采用颜色更浅的茄衣，烟叶陈化两年，另有更粗规格版本，命名为Big Boys；Habano Reserva采用Habano Rosado Oscuro茄衣，也称为Colorado，烟叶陈化三年；以及Reserva Privada，Habano Rosado茄衣配Habano茄套，茄芯陈化三年，规格至60环径（Toro Grande）。',
        '[{"name":"Habano Clásico","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"采用Habano Rosado（Intermedio）茄衣，或在Golden版本中采用颜色更浅的Habano Rosado Claro茄衣，烟叶陈化两年，据厂方介绍，力度依规格在mild-medium至medium-full之间；另有更粗规格版本，命名为Big Boys。"},{"name":"Habano Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano Rosado Oscuro","vitolas":[],"story":"厂方也称该茄衣为Colorado，尼加拉瓜烟叶陈化三年。"},{"name":"Reserva Privada","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Rosado","vitolas":[],"story":"Habano茄套，尼加拉瓜茄芯陈化至少三年，据厂方介绍；共三种规格，其中包括Toro Grande 60（6 x 60）。"}]',
        'وُلدت Don Duarte عام 2008، بدفع من الطبيب Roger Duarte Rodriguez، الذي يصف البيت أسرته بأنها من رواد إستيلي. ومنذ 2001، عمل مع كبير الخبراء في المزج Evelio Oviedo على تطوير سيجاره، الذي كان يُلف في البداية بمساعدة Plasencia، بحسب البيت. ثم مرّت العلامة بفترة توقف لأسباب صحية، قبل أن تعود، بحسب Cigarinspector.com.

في 2020، تولت Cigar Conexion، التي يديرها Fernando Navarro، إدارة Don Duarte، بحسب البيت؛ وفي 2022، انتقل الإنتاج إلى Tabacalera Pages في إستيلي — مصنع شريكه Raymond Pages، حيث يُلف أيضًا Cuervo y Sobrinos. وحلّ غلاف إكوادوري محل غلاف خالابا الأصلي، اختير بسبب احتراقه، بحسب البيت. وفي معرض Intertabac في سبتمبر 2026، قدّم Navarro لعلامة Don Duarte مقاسًا جديدًا بقياس 60، هو Super Ancho (4½ x 60)، ولعلامته الشقيقة Villa Vieja مقاس Grandeur (5½ x 60): إذ كانت كلتا المجموعتين تفتقران إلى مقاس 60، بحسب قوله.

في سبتمبر 2026، تضم القائمة ثلاثة مزيجات، بحسب البيت: Habano Clásico، بغلاف Habano Rosado أو، في نسخة Golden، بغلاف أفتح لونًا، تبغ معتَّق سنتين، ويُقدَّم أيضًا في مقاسات أعرض تحت اسم Big Boys؛ وHabano Reserva، بغلاف Habano Rosado Oscuro، ويُعرف أيضًا باسم Colorado، تبغ معتَّق ثلاث سنوات؛ وReserva Privada، بغلاف Habano Rosado ورباط Habano، وحشوة معتَّقة ثلاث سنوات، حتى مقاس 60 (Toro Grande).',
        '[{"name":"Habano Clásico","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"بغلاف Habano Rosado (Intermedio) أو، في نسخة Golden، بغلاف أفتح لونًا Habano Rosado Claro، تبغ معتَّق سنتين، بحسب البيت، بقوة تتراوح بين mild-medium وmedium-full بحسب المقاس؛ ويُقدَّم أيضًا في مقاسات أعرض تحت اسم Big Boys."},{"name":"Habano Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano Rosado Oscuro","vitolas":[],"story":"غلاف يسمّيه البيت أيضًا Colorado، تبغ نيكاراغوي معتَّق ثلاث سنوات."},{"name":"Reserva Privada","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Rosado","vitolas":[],"story":"رباط Habano، وحشوة نيكاراغوية معتَّقة ثلاث سنوات على الأقل، بحسب البيت؛ ثلاثة مقاسات من بينها Toro Grande 60 (6 x 60)."}]')
