-- ── Don Zuarin ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Don Zuarin',
        'nicaragua',
        '2022 — Steffen Brinkmann, Schwerin',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'smokersplanet.de « Tobaccohouse Brinkmann » (consulté 2026-09-24, en allemand : boutique ouverte par Steffen Brinkmann en 1998 à Schwerin) ; starkezigarren.de « Don Zuarin Edición Privada Sampler » (consulté 2026-09-24 : cigares premium roulés à la main du Nicaragua, marque maison de Tobaccohouse Brinkmann) ; cigarworld.de « Don Zuarin » (consulté 2026-09-23 : marque créée en 2022 par Steffen Brinkmann) ; brinkmannfinest.de « Don Zuarin » (consulté 2026-09-24, en allemand : éditions Privada, Barberpole, 25th Anniversary, Friendship, Rugia et Claro, formats, capes et profils de goût, maître assembleur Kurt Brandt) ; smokersplanet.de « Markante Brinkmann-Botschaft: Don Zuarin macht sich breit » (consulté 2026-09-24, en allemand : cigares nicaraguayens développés avec le maître assembleur Kurt Brandt) ; smokersplanet.de « Ein weiteres Meisterwerk von Kurt Brandt: die Don Zuarin Edición Barberpole » (consulté 2026-09-24, en allemand : cape Sumatra Colorado et Connecticut Dorado équatorien, méthode Entubado, format Gigante 6 x 58) ; smokersplanet.de « Kurt Joachim Brandt: Isthmus ist Vergangenheit » (2019-05-06, en allemand : Kurt Brandt, assembleur d''Isthmus puis de Flor Real, a déplacé sa production du Costa Rica vers Estelí, au Nicaragua, en 2009 ; marque Isthmus arrêtée en 2019, aucune fabrique à son nom identifiée)',
        NULL,
        'Don Zuarin est la marque maison de Steffen Brinkmann, caviste qui ouvre sa boutique à Schwerin en 1998 sous le nom Tobaccohouse Brinkmann, devenue depuis BRINKMANNfinest. Il crée Don Zuarin en 2022, d''un nom qu''il dit tiré de Zuarin, forme slave médiévale de Schwerin attestée dans les Annales de Pöhlde au XIIe siècle. Les cigares sont roulés à la main au Nicaragua, dans une fabrique que la maison ne nomme pas.

Le mélange est mis au point avec le maître assembleur Kurt Brandt, dit la maison. Brandt avait auparavant créé les marques Isthmus, arrêtée en 2019, et Flor Real, et déplacé sa production du Costa Rica vers Estelí en 2009, dit Smokersplanet.de. En septembre 2026, le catalogue compte plusieurs éditions : l''Edición Privada, assemblage tout nicaraguayen que la maison dit boisé et cuiré, en cinq formats de Petit à Magnum ; l''Edición Barberpole, cape bicolore de Sumatra Colorado et de Connecticut équatorien roulée en Entubado — procédé que la maison dit aussi connu comme le style cubain ancien —, en Gigante (6 x 58) ; la Claro Edition, à cape claire, en Double Toro ; la Friendship Edition, en Robusto Extra et Double Robusto ; et la Rugia Edition, nommée pour l''île baltique de Rügen, en Robusto.

En septembre 2026, ces éditions sont en vente chez StarkeZigarren.de et Cigarworld.de.',
        '[{"name":"Edición Privada","color":"#A0522D","force":"Mild-Medium","wrapper":"Non divulguée","vitolas":[],"story":"Assemblage tout nicaraguayen, dit la maison, au caractère boisé et cuiré ; cinq formats, de Petit à Magnum."},{"name":"Edición Barberpole","color":"#C9A96E","force":"Mild","wrapper":"Sumatra & Connecticut Équateur","vitolas":[],"story":"Cape bicolore roulée en Entubado, en Gigante (6 x 58) ; profil dit doux par la maison."},{"name":"Claro Edition","color":"#C9A96E","force":"Mild","wrapper":"Claro","vitolas":[],"story":"Cape claire, tabac dit doux et crémeux par la maison, en Double Toro."},{"name":"Friendship Edition","color":"#6B4226","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"En deux formats, Robusto Extra et Double Robusto, décrite par la maison comme chocolatée et épicée."},{"name":"Rugia Edition","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Nommée pour l''île baltique de Rügen (Rugia en latin), en Robusto."}]',
        'Don Zuarin is the house brand of Steffen Brinkmann, a tobacconist who opened his shop in Schwerin in 1998 under the name Tobaccohouse Brinkmann, since renamed BRINKMANNfinest. He created Don Zuarin in 2022, a name he says is drawn from Zuarin, a medieval Slavic form of Schwerin attested in the Annals of Pöhlde in the twelfth century. The cigars are hand-rolled in Nicaragua, in a factory the house does not name.

The blend was developed with master blender Kurt Brandt, says the house. Brandt had previously created the brands Isthmus, discontinued in 2019, and Flor Real, and moved his production from Costa Rica to Estelí in 2009, says Smokersplanet.de. In September 2026, the catalogue comprises several editions: the Edición Privada, an all-Nicaraguan blend the house describes as woody and leathery, in five formats from Petit to Magnum; the Edición Barberpole, a two-tone wrapper of Sumatra Colorado and Ecuadorian Connecticut rolled in Entubado — a method the house also says is known as the old Cuban style —, in Gigante (6 x 58); the Claro Edition, in a light wrapper, in Double Toro; the Friendship Edition, in Robusto Extra and Double Robusto; and the Rugia Edition, named for the Baltic island of Rügen, in Robusto.

In September 2026, these editions are sold at StarkeZigarren.de and Cigarworld.de.',
        '[{"name":"Edición Privada","color":"#A0522D","force":"Mild-Medium","wrapper":"Undisclosed","vitolas":[],"story":"All-Nicaraguan blend, says the house, with a woody, leathery character; five formats, from Petit to Magnum."},{"name":"Edición Barberpole","color":"#C9A96E","force":"Mild","wrapper":"Sumatra & Ecuadorian Connecticut","vitolas":[],"story":"Two-tone wrapper rolled in Entubado, in Gigante (6 x 58); profile described as mild by the house."},{"name":"Claro Edition","color":"#C9A96E","force":"Mild","wrapper":"Claro","vitolas":[],"story":"Light wrapper, tobacco described by the house as mild and creamy, in Double Toro."},{"name":"Friendship Edition","color":"#6B4226","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"In two formats, Robusto Extra and Double Robusto, described by the house as chocolatey and spicy."},{"name":"Rugia Edition","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Named for the Baltic island of Rügen (Rugia in Latin), in Robusto."}]',
        'Don Zuarin es la marca propia de Steffen Brinkmann, comerciante de puros que abre su tienda en Schwerin en 1998 bajo el nombre Tobaccohouse Brinkmann, convertida después en BRINKMANNfinest. Crea Don Zuarin en 2022, con un nombre que dice tomado de Zuarin, forma eslava medieval de Schwerin atestiguada en los Anales de Pöhlde en el siglo XII. Los puros se lían a mano en Nicaragua, en una fábrica que la casa no nombra.

La mezcla se pone a punto con el maestro mezclador Kurt Brandt, dice la casa. Brandt había creado antes las marcas Isthmus, interrumpida en 2019, y Flor Real, y había trasladado su producción de Costa Rica a Estelí en 2009, dice Smokersplanet.de. En septiembre de 2026, el catálogo cuenta con varias ediciones: la Edición Privada, mezcla totalmente nicaragüense que la casa describe como amaderada y acuerada, en cinco formatos de Petit a Magnum; la Edición Barberpole, capa bicolor de Sumatra Colorado y Connecticut ecuatoriano liada en Entubado —método que la casa dice también conocido como el estilo cubano antiguo—, en Gigante (6 x 58); la Claro Edition, de capa clara, en Double Toro; la Friendship Edition, en Robusto Extra y Double Robusto; y la Rugia Edition, nombrada por la isla báltica de Rügen, en Robusto.

En septiembre de 2026, estas ediciones se venden en StarkeZigarren.de y Cigarworld.de.',
        '[{"name":"Edición Privada","color":"#A0522D","force":"Mild-Medium","wrapper":"No divulgada","vitolas":[],"story":"Mezcla totalmente nicaragüense, dice la casa, de carácter amaderado y acuerado; cinco formatos, de Petit a Magnum."},{"name":"Edición Barberpole","color":"#C9A96E","force":"Mild","wrapper":"Sumatra y Connecticut ecuatoriano","vitolas":[],"story":"Capa bicolor liada en Entubado, en Gigante (6 x 58); perfil descrito como suave por la casa."},{"name":"Claro Edition","color":"#C9A96E","force":"Mild","wrapper":"Claro","vitolas":[],"story":"Capa clara, tabaco descrito como suave y cremoso por la casa, en Double Toro."},{"name":"Friendship Edition","color":"#6B4226","force":null,"wrapper":"No divulgada","vitolas":[],"story":"En dos formatos, Robusto Extra y Double Robusto, descrita por la casa como achocolatada y especiada."},{"name":"Rugia Edition","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Nombrada por la isla báltica de Rügen (Rugia en latín), en Robusto."}]',
        'Don Zuarin ist die Hausmarke von Steffen Brinkmann, einem Tabakwarenhändler, der sein Geschäft 1998 in Schwerin unter dem Namen Tobaccohouse Brinkmann eröffnet, das seither zu BRINKMANNfinest geworden ist. Er schafft Don Zuarin 2022, mit einem Namen, den er von Zuarin ableitet, der mittelalterlichen slawischen Form von Schwerin, die in den Pöhlder Annalen im 12. Jahrhundert belegt ist. Die Zigarren werden in Nicaragua von Hand gerollt, in einer Fabrik, die das Haus nicht nennt.

Die Mischung wird gemeinsam mit dem Meisterblender Kurt Brandt entwickelt, so das Haus. Brandt hatte zuvor die Marken Isthmus, 2019 eingestellt, und Flor Real geschaffen und seine Produktion 2009 von Costa Rica nach Estelí verlegt, so Smokersplanet.de. Im September 2026 umfasst das Sortiment mehrere Editionen: die Edición Privada, eine rein nicaraguanische Mischung, die das Haus als holzig und ledrig bezeichnet, in fünf Formaten von Petit bis Magnum; die Edición Barberpole, ein zweifarbiges Deckblatt aus Sumatra Colorado und ecuadorianischem Connecticut, im Entubado-Verfahren gerollt — ein Verfahren, das laut Haus auch als alter kubanischer Stil bekannt ist —, als Gigante (6 x 58); die Claro Edition, mit hellem Deckblatt, als Double Toro; die Friendship Edition, als Robusto Extra und Double Robusto; und die Rugia Edition, benannt nach der Ostseeinsel Rügen, als Robusto.

Im September 2026 sind diese Editionen bei StarkeZigarren.de und Cigarworld.de erhältlich.',
        '[{"name":"Edición Privada","color":"#A0522D","force":"Mild-Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Rein nicaraguanische Mischung, so das Haus, mit holzigem, ledrigem Charakter; fünf Formate, von Petit bis Magnum."},{"name":"Edición Barberpole","color":"#C9A96E","force":"Mild","wrapper":"Sumatra & ecuadorianischer Connecticut","vitolas":[],"story":"Zweifarbiges Deckblatt, im Entubado-Verfahren gerollt, als Gigante (6 x 58); vom Haus als mild beschriebenes Profil."},{"name":"Claro Edition","color":"#C9A96E","force":"Mild","wrapper":"Claro","vitolas":[],"story":"Helles Deckblatt, vom Haus als mild und cremig beschriebener Tabak, als Double Toro."},{"name":"Friendship Edition","color":"#6B4226","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"In zwei Formaten, Robusto Extra und Double Robusto, vom Haus als schokoladig und würzig beschrieben."},{"name":"Rugia Edition","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Benannt nach der Ostseeinsel Rügen (lateinisch Rugia), als Robusto."}]',
        'Don Zuarin是Steffen Brinkmann的自有品牌；Brinkmann是一位雪茄零售商，1998年在什未林开设店铺，取名Tobaccohouse Brinkmann，后更名为BRINKMANNfinest。他于2022年创立Don Zuarin，据他说，这个名字源自Zuarin，即什未林的中世纪斯拉夫语名称，见于12世纪的《珀尔德年鉴》。雪茄在尼加拉瓜手工卷制，工厂名称厂方未公开。

据厂方介绍，该配方与首席调配师Kurt Brandt共同研发而成。据Smokersplanet.de报道，Brandt此前曾创立Isthmus品牌（已于2019年停产）和Flor Real品牌，并于2009年将生产从哥斯达黎加迁至埃斯特利。2026年9月，产品目录包括多个版本：Edición Privada为纯尼加拉瓜配方，厂方称其带有木质和皮革风味，共五种规格，从Petit到Magnum；Edición Barberpole采用双色茄衣，由Sumatra Colorado和厄瓜多尔Connecticut拼合，以Entubado法卷制——厂方称该工艺也被称为古巴老式卷法——规格为Gigante（6 x 58）；Claro Edition采用浅色茄衣，规格为Double Toro；Friendship Edition规格为Robusto Extra和Double Robusto；Rugia Edition以波罗的海的吕根岛命名，规格为Robusto。

截至2026年9月，这些版本在StarkeZigarren.de和Cigarworld.de有售。',
        '[{"name":"Edición Privada","color":"#A0522D","force":"Mild-Medium","wrapper":"未公开","vitolas":[],"story":"据厂方介绍，为纯尼加拉瓜配方，带有木质与皮革风味；共五种规格，从Petit到Magnum。"},{"name":"Edición Barberpole","color":"#C9A96E","force":"Mild","wrapper":"Sumatra与厄瓜多尔Connecticut","vitolas":[],"story":"双色茄衣，以Entubado法卷制，规格为Gigante（6 x 58）；厂方称其风味温和。"},{"name":"Claro Edition","color":"#C9A96E","force":"Mild","wrapper":"Claro","vitolas":[],"story":"浅色茄衣，厂方称烟叶口感温和绵密，规格为Double Toro。"},{"name":"Friendship Edition","color":"#6B4226","force":null,"wrapper":"未公开","vitolas":[],"story":"共两种规格，Robusto Extra和Double Robusto，厂方称其带有巧克力与香料风味。"},{"name":"Rugia Edition","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"以波罗的海的吕根岛（拉丁语称Rugia）命名，规格为Robusto。"}]',
        'Don Zuarin هي العلامة الخاصة لـSteffen Brinkmann، تاجر سيجار افتتح متجره في شفيرين عام 1998 تحت اسم Tobaccohouse Brinkmann، الذي أصبح منذ ذلك الحين BRINKMANNfinest. أنشأ Don Zuarin عام 2022، باسم يقول إنه مستمد من Zuarin، الصيغة السلافية القروسطية لشفيرين، والموثّقة في حوليات بولده في القرن الثاني عشر. تُلف السيجار يدويًا في نيكاراغوا، في مصنع لا يذكر البيت اسمه.

طُوِّر المزيج بالتعاون مع كبير خبراء المزج Kurt Brandt، بحسب البيت. وكان Brandt قد أنشأ من قبل علامتَي Isthmus، التي توقفت عام 2019، وFlor Real، ونقل إنتاجه من كوستاريكا إلى إستيلي عام 2009، بحسب Smokersplanet.de. وفي سبتمبر 2026، تضم القائمة عدة إصدارات: Edición Privada، مزيج نيكاراغوي بالكامل يصفه البيت بأنه خشبي وجلدي النكهة، في خمسة مقاسات من Petit إلى Magnum؛ وEdición Barberpole، بغلاف ثنائي اللون من Sumatra Colorado وConnecticut إكوادوري، يُلف بطريقة Entubado — وهي طريقة يقول البيت إنها تُعرف أيضًا بالطراز الكوبي القديم —، بمقاس Gigante (6 x 58)؛ وClaro Edition، بغلاف فاتح، بمقاس Double Toro؛ وFriendship Edition، بمقاسَي Robusto Extra وDouble Robusto؛ وRugia Edition، المسمّاة نسبة إلى جزيرة روغن البلطيقية، بمقاس Robusto.

في سبتمبر 2026، تُباع هذه الإصدارات لدى StarkeZigarren.de وCigarworld.de.',
        '[{"name":"Edición Privada","color":"#A0522D","force":"Mild-Medium","wrapper":"غير معلن","vitolas":[],"story":"مزيج نيكاراغوي بالكامل، بحسب البيت، بطابع خشبي وجلدي؛ خمسة مقاسات، من Petit إلى Magnum."},{"name":"Edición Barberpole","color":"#C9A96E","force":"Mild","wrapper":"Sumatra وConnecticut إكوادوري","vitolas":[],"story":"غلاف ثنائي اللون يُلف بطريقة Entubado، بمقاس Gigante (6 x 58)؛ يصفه البيت بأنه معتدل النكهة."},{"name":"Claro Edition","color":"#C9A96E","force":"Mild","wrapper":"Claro","vitolas":[],"story":"غلاف فاتح، تبغ يصفه البيت بأنه معتدل وقشدي، بمقاس Double Toro."},{"name":"Friendship Edition","color":"#6B4226","force":null,"wrapper":"غير معلن","vitolas":[],"story":"بمقاسين، Robusto Extra وDouble Robusto، يصفها البيت بأنها ذات نكهة شوكولاتة وتوابل."},{"name":"Rugia Edition","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"سُمّيت نسبة إلى جزيرة روغن البلطيقية (Rugia باللاتينية)، بمقاس Robusto."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Alcazar ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Alcazar',
        'nicaragua',
        '1898 — relancée par J.C. Newman',
        'Usine propre — J.C. Newman PENSA (Puros de Estelí, Nicaragua S.A.), Estelí, Nicaragua',
        'jcnewman.com « Alcazar Cigars | Nicaraguan Cigars | J.C. Newman Cigar Co. » (24 septembre 2026 : création en 1898 d''après un cheval de course, disparition pendant la Grande Dépression, rachat et relance par J.C. Newman, fabrique PENSA) ; jcnewman.com « J.C. Newman PENSA - Nicaraguan Cigar Factory » (24 septembre 2026 : PENSA = Puros de Estelí, Nicaragua Sociedad Anónima, à Estelí, plus de 800 employés) ; cigarplace.biz « Alcazar Maduro Cigars by JC Newman » (24 septembre 2026 : gamme Alcazar Maduro en quatre numéros, cape Connecticut Broadleaf, tripe et sous-cape nicaraguayennes, corps moyen, vente en bundles de vingt)',
        NULL,
        'Alcazar naît en 1898, son nom emprunté à un cheval de course célèbre de l''époque, dit J.C. Newman Cigar Co., propriétaire actuel de la marque. Le puro disparaît pendant la Grande Dépression ; la maison ne date pas précisément l''année où elle en a racheté les droits, seulement qu''elle a choisi de relancer ce nom ancien pour une nouvelle génération de fumeurs.

Alcazar est roulée à la PENSA — Puros de Estelí, Nicaragua Sociedad Anónima —, la fabrique nicaraguayenne de J.C. Newman à Estelí, qui emploie plus de huit cents personnes, selon la maison. J.C. Newman vend aussi sous son propre nom Cuesta-Rey, autre marque ancienne qu''elle a reprise.

Le catalogue se limite à une ligne, Alcazar Maduro, en quatre numéros du No. 1 (8 x 52) au No. 4 (5 x 52) : cape Connecticut Broadleaf cultivée aux États-Unis, tripe et sous-cape nicaraguayennes, corps moyen, dit CigarPlace.biz. En septembre 2026, ce détaillant la vend toujours, en bundles de vingt, en lots de cinq ou à l''unité.',
        '[{"name":"Alcazar Maduro","color":"#4A3728","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"En quatre numéros, du No. 1 (8 x 52) au No. 4 (5 x 52), cape cultivée aux États-Unis, tripe et sous-cape nicaraguayennes, corps moyen, dit CigarPlace.biz."}]',
        'Alcazar was born in 1898, its name borrowed from a famous racehorse of the day, says J.C. Newman Cigar Co., the brand''s current owner. The puro disappeared during the Great Depression; the house does not give a precise date for the year it bought back the rights, only that it chose to relaunch this old name for a new generation of smokers.

Alcazar is rolled at PENSA — Puros de Estelí, Nicaragua Sociedad Anónima —, J.C. Newman''s Nicaraguan factory in Estelí, which employs more than eight hundred people, according to the house. J.C. Newman also sells Cuesta-Rey under its own name, another old brand it has taken over.

The catalogue is limited to one line, Alcazar Maduro, in four numbers from the No. 1 (8 x 52) to the No. 4 (5 x 52): Connecticut Broadleaf wrapper grown in the United States, Nicaraguan filler and binder, medium body, says CigarPlace.biz. As of September 2026, this retailer still sells it, in bundles of twenty, in lots of five or individually.',
        '[{"name":"Alcazar Maduro","color":"#4A3728","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"In four numbers, from the No. 1 (8 x 52) to the No. 4 (5 x 52), wrapper grown in the United States, Nicaraguan filler and binder, medium body, says CigarPlace.biz."}]',
        'Alcazar nace en 1898, su nombre tomado de un célebre caballo de carreras de la época, dice J.C. Newman Cigar Co., actual propietaria de la marca. El puro desaparece durante la Gran Depresión; la casa no precisa el año en que recompró los derechos, solo que decidió relanzar este nombre antiguo para una nueva generación de fumadores.

Alcazar se elabora en la PENSA — Puros de Estelí, Nicaragua Sociedad Anónima —, la fábrica nicaragüense de J.C. Newman en Estelí, que emplea a más de ochocientas personas, según la casa. J.C. Newman también vende bajo su propio nombre Cuesta-Rey, otra marca antigua que ha retomado.

El catálogo se limita a una línea, Alcazar Maduro, en cuatro números del No. 1 (8 x 52) al No. 4 (5 x 52): capa Connecticut Broadleaf cultivada en Estados Unidos, tripa y capote nicaragüenses, cuerpo medio, dice CigarPlace.biz. En septiembre de 2026, este minorista sigue vendiéndola, en paquetes de veinte, en lotes de cinco o por unidad.',
        '[{"name":"Alcazar Maduro","color":"#4A3728","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"En cuatro números, del No. 1 (8 x 52) al No. 4 (5 x 52), capa cultivada en Estados Unidos, tripa y capote nicaragüenses, cuerpo medio, dice CigarPlace.biz."}]',
        'Alcazar entsteht 1898; der Name ist einem berühmten Rennpferd jener Zeit entlehnt, so J.C. Newman Cigar Co., die heutige Eigentümerin der Marke. Die Puro verschwindet während der Weltwirtschaftskrise; das Haus nennt kein genaues Jahr, in dem es die Rechte zurückkaufte, nur dass es sich entschied, diesen alten Namen für eine neue Generation von Rauchern wiederzubeleben.

Alcazar wird in der PENSA gedreht — Puros de Estelí, Nicaragua Sociedad Anónima —, der nicaraguanischen Fabrik von J.C. Newman in Estelí, die nach Angaben des Hauses mehr als achthundert Personen beschäftigt. J.C. Newman verkauft unter eigenem Namen auch Cuesta-Rey, eine weitere alte Marke, die es übernommen hat.

Das Sortiment beschränkt sich auf eine Linie, Alcazar Maduro, in vier Nummern von der No. 1 (8 x 52) bis zur No. 4 (5 x 52): Deckblatt Connecticut Broadleaf, angebaut in den Vereinigten Staaten, Einlage und Umblatt aus Nicaragua, mittlerer Körper, so CigarPlace.biz. Im September 2026 verkauft dieser Händler sie weiterhin, in Bundles zu zwanzig Stück, in Fünferlosen oder einzeln.',
        '[{"name":"Alcazar Maduro","color":"#4A3728","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"In vier Nummern, von der No. 1 (8 x 52) bis zur No. 4 (5 x 52), Deckblatt angebaut in den Vereinigten Staaten, Einlage und Umblatt aus Nicaragua, mittlerer Körper, so CigarPlace.biz."}]',
        'Alcazar诞生于1898年，其名字取自当时一匹著名赛马，品牌现任所有者J.C. Newman Cigar Co.如是说。这款puro在大萧条期间一度消失；该公司并未说明具体是哪一年购回了品牌权利，只表示选择让这个古老的名字为新一代烟民重现。

Alcazar在PENSA（即Puros de Estelí，Nicaragua Sociedad Anónima）卷制，那是J.C. Newman位于埃斯特利的尼加拉瓜工厂，据该公司介绍，员工超过八百人。J.C. Newman还以自身名义销售Cuesta-Rey，这是其接手的另一个历史悠久的品牌。

该系列仅有一条产品线，Alcazar Maduro，共四个编号，从No. 1（8 x 52）到No. 4（5 x 52）：茄衣为在美国种植的Connecticut Broadleaf，茄芯与茄套产自尼加拉瓜，浓度中等，CigarPlace.biz如是说。截至2026年9月，该零售商仍在销售，包装为二十支一捆，或五支一组，亦可单支购买。',
        '[{"name":"Alcazar Maduro","color":"#4A3728","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"共四个编号，从No. 1（8 x 52）到No. 4（5 x 52），茄衣在美国种植，茄芯与茄套产自尼加拉瓜，浓度中等，CigarPlace.biz如是说。"}]',
        'وُلدت Alcazar عام 1898، واسمها مستوحى من حصان سباق شهير في ذلك العصر، كما تقول J.C. Newman Cigar Co.، المالكة الحالية للعلامة. اختفى الـpuro خلال الكساد الكبير؛ ولا تحدد الشركة بدقة السنة التي استعادت فيها الحقوق، بل تكتفي بالقول إنها اختارت إحياء هذا الاسم القديم لجيل جديد من المدخنين.

تُلَفّ Alcazar في PENSA — أي Puros de Estelí, Nicaragua Sociedad Anónima — مصنع J.C. Newman في نيكاراغوا بمدينة إستيلي، الذي يوظف، بحسب الشركة، ما يزيد على ثمانمئة شخص. وتبيع J.C. Newman أيضًا تحت اسمها الخاص علامة Cuesta-Rey، وهي علامة قديمة أخرى استعادتها.

تقتصر التشكيلة على خط واحد هو Alcazar Maduro، بأربعة أرقام من No. 1 (8 x 52) إلى No. 4 (5 x 52): غلاف Connecticut Broadleaf مزروع في الولايات المتحدة، وحشوة ورباط من نيكاراغوا، بقوة متوسطة، كما تقول CigarPlace.biz. وحتى سبتمبر 2026، لا يزال هذا التاجر يبيعها، في حزم من عشرين، أو في مجموعات من خمس، أو منفردة.',
        '[{"name":"Alcazar Maduro","color":"#4A3728","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"بأربعة أرقام، من No. 1 (8 x 52) إلى No. 4 (5 x 52)، غلاف مزروع في الولايات المتحدة، وحشوة ورباط من نيكاراغوا، بقوة متوسطة، كما تقول CigarPlace.biz."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Los Amigos ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Los Amigos',
        'nicaragua',
        '2024 — Ramos, Saes, Lahsen',
        'Chez Tabacalera Familia Disla S.A., Estelí, Nicaragua',
        'wantedonline.co.za « Inside the birth of Los Amigos Cigars » (26 février 2026 : fondation en 2024 par Pedro Ramos, Walter Saes et Eduardo Lahsen, un an de recherche d''usine) ; cigar-coop.com « Esteban Disla and Daniel Lance Form Tabacalera Familia Disla S.A. and Launch Domain Cigars » (mars 2024 : fabrique à Estelí, Nicaragua, établie par Esteban Disla et Daniel Lance) ; tbfdsa.com « site de Tabacalera Familia Disla S.A. » (24 septembre 2026 : implantation à Estelí et environs, quatre-vingts hectares de terres, clients dont Domain Cigars) ; cigardojo.com « Domain Launches Distribution Company, Adds Los Amigos Cigars » (août 2026 : quatre lignes de la collection Small Batch 2025 — Epiphany, The Sacred Blend, Legacy of the Leaf, Hedonism —, capes, liants, tripes et formats)',
        NULL,
        'Los Amigos naît en 2024 de l''amitié entre trois hommes que le tabac a réunis lors de voyages professionnels : Pedro Ramos, sud-africain, dans l''industrie du cigare aux côtés de son père depuis dix-sept ans, le Brésilien Walter Saes et le Chilien Eduardo Lahsen, amis depuis une dizaine d''années, dit Wanted Online. Le trio passe environ un an à visiter des manufactures avant de s''arrêter sur une petite fabrique nicaraguayenne, selon Ramos.

Cette fabrique est la Tabacalera Familia Disla S.A., à Estelí, établie la même année par Esteban Disla — dans le tabac depuis l''enfance en République dominicaine — et Daniel Lance, dit Cigar Coop. Leur manufacture cultive quatre-vingts hectares de terres et roule aussi, entre autres, Domain Cigars, selon le site de la tabacalera.

En août 2026, Los Amigos fait ses débuts sur le marché américain par Domain Distribution, service que lance Domain Cigars, la maison de Disla et Lance, avec la collection Small Batch 2025, dit Cigar Dojo : Epiphany, cape Habano équatorienne, en Robusto (5 x 50) ; The Sacred Blend, même cape, en Grand Robusto (5 x 56) ; Legacy of the Leaf, cape San Andrés mexicaine, box-pressée (4½ x 60) ; et Hedonism, cape Connecticut Broadleaf, en Toro (6 x 52).',
        '[{"name":"Epiphany","color":"#A0522D","force":"Mild-Medium","wrapper":"Habano équatorien","vitolas":[],"story":"Sous-cape indonésienne Besuki, tripe dominicaine et nicaraguayenne, en Robusto (5 x 50), dit Cigar Dojo."},{"name":"The Sacred Blend","color":"#A0522D","force":"Medium","wrapper":"Habano équatorien","vitolas":[],"story":"Même cape et même sous-cape qu''Epiphany, en Grand Robusto (5 x 56), dit Cigar Dojo."},{"name":"Legacy of the Leaf","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Tripe entièrement nicaraguayenne, format box-pressé (4½ x 60), dit Cigar Dojo."},{"name":"Hedonism","color":"#4A2C1A","force":"Medium-Full","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Sous-cape de Condega, tripe broadleaf de Pennsylvanie, dominicaine et nicaraguayenne, en Toro (6 x 52), dit Cigar Dojo."}]',
        'Los Amigos was born in 2024 out of the friendship between three men brought together by tobacco during business trips: Pedro Ramos, a South African who has worked in the cigar industry alongside his father for seventeen years, the Brazilian Walter Saes and the Chilean Eduardo Lahsen, friends for around ten years, says Wanted Online. The trio spent about a year visiting factories before settling on a small Nicaraguan factory, according to Ramos.

That factory is Tabacalera Familia Disla S.A., in Estelí, established the same year by Esteban Disla — in tobacco since childhood in the Dominican Republic — and Daniel Lance, says Cigar Coop. Their factory farms eighty hectares of land and also rolls, among others, Domain Cigars, according to the tabacalera''s website.

In August 2026, Los Amigos made its debut on the American market through Domain Distribution, a service launched by Domain Cigars, Disla and Lance''s house, with the Small Batch 2025 collection, says Cigar Dojo: Epiphany, Ecuadorian Habano wrapper, in Robusto (5 x 50); The Sacred Blend, same wrapper, in Grand Robusto (5 x 56); Legacy of the Leaf, Mexican San Andrés wrapper, box-pressed (4½ x 60); and Hedonism, Connecticut Broadleaf wrapper, in Toro (6 x 52).',
        '[{"name":"Epiphany","color":"#A0522D","force":"Mild-Medium","wrapper":"Ecuadorian Habano","vitolas":[],"story":"Indonesian Besuki binder, Dominican and Nicaraguan filler, in Robusto (5 x 50), says Cigar Dojo."},{"name":"The Sacred Blend","color":"#A0522D","force":"Medium","wrapper":"Ecuadorian Habano","vitolas":[],"story":"Same wrapper and same binder as Epiphany, in Grand Robusto (5 x 56), says Cigar Dojo."},{"name":"Legacy of the Leaf","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Fully Nicaraguan filler, box-pressed format (4½ x 60), says Cigar Dojo."},{"name":"Hedonism","color":"#4A2C1A","force":"Medium-Full","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Condega binder, Pennsylvania broadleaf, Dominican and Nicaraguan filler, in Toro (6 x 52), says Cigar Dojo."}]',
        'Los Amigos nace en 2024 de la amistad entre tres hombres a quienes el tabaco unió durante viajes de trabajo: Pedro Ramos, sudafricano, en la industria del cigarro junto a su padre desde hace diecisiete años, el brasileño Walter Saes y el chileno Eduardo Lahsen, amigos desde hace una decena de años, dice Wanted Online. El trío pasa cerca de un año visitando manufacturas antes de decidirse por una pequeña fábrica nicaragüense, según Ramos.

Esa fábrica es la Tabacalera Familia Disla S.A., en Estelí, establecida ese mismo año por Esteban Disla —en el tabaco desde la infancia en República Dominicana— y Daniel Lance, dice Cigar Coop. Su manufactura cultiva ochenta hectáreas de tierra y también elabora, entre otras, Domain Cigars, según el sitio de la tabacalera.

En agosto de 2026, Los Amigos debuta en el mercado estadounidense a través de Domain Distribution, servicio que lanza Domain Cigars, la casa de Disla y Lance, con la colección Small Batch 2025, dice Cigar Dojo: Epiphany, capa Habano ecuatoriana, en Robusto (5 x 50); The Sacred Blend, misma capa, en Grand Robusto (5 x 56); Legacy of the Leaf, capa San Andrés mexicana, prensada (4½ x 60); y Hedonism, capa Connecticut Broadleaf, en Toro (6 x 52).',
        '[{"name":"Epiphany","color":"#A0522D","force":"Mild-Medium","wrapper":"Habano ecuatoriano","vitolas":[],"story":"Capote indonesio Besuki, tripa dominicana y nicaragüense, en Robusto (5 x 50), dice Cigar Dojo."},{"name":"The Sacred Blend","color":"#A0522D","force":"Medium","wrapper":"Habano ecuatoriano","vitolas":[],"story":"Misma capa y mismo capote que Epiphany, en Grand Robusto (5 x 56), dice Cigar Dojo."},{"name":"Legacy of the Leaf","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (México)","vitolas":[],"story":"Tripa enteramente nicaragüense, formato prensado (4½ x 60), dice Cigar Dojo."},{"name":"Hedonism","color":"#4A2C1A","force":"Medium-Full","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Capote de Condega, tripa broadleaf de Pensilvania, dominicana y nicaragüense, en Toro (6 x 52), dice Cigar Dojo."}]',
        'Los Amigos entsteht 2024 aus der Freundschaft dreier Männer, die der Tabak auf Geschäftsreisen zusammengeführt hat: der Südafrikaner Pedro Ramos, seit siebzehn Jahren an der Seite seines Vaters in der Zigarrenbranche tätig, der Brasilianer Walter Saes und der Chilene Eduardo Lahsen, seit etwa zehn Jahren befreundet, so Wanted Online. Das Trio verbringt etwa ein Jahr damit, Manufakturen zu besuchen, bevor es sich für eine kleine nicaraguanische Fabrik entscheidet, so Ramos.

Diese Fabrik ist die Tabacalera Familia Disla S.A. in Estelí, im selben Jahr gegründet von Esteban Disla — seit seiner Kindheit in der Dominikanischen Republik im Tabak tätig — und Daniel Lance, so Cigar Coop. Ihre Manufaktur bewirtschaftet achtzig Hektar Land und dreht unter anderem auch Domain Cigars, laut der Website der Tabacalera.

Im August 2026 gibt Los Amigos sein Debüt auf dem amerikanischen Markt über Domain Distribution, einen Dienst, den Domain Cigars, das Haus von Disla und Lance, mit der Kollektion Small Batch 2025 startet, so Cigar Dojo: Epiphany, ecuadorianisches Habano-Deckblatt, in Robusto (5 x 50); The Sacred Blend, gleiches Deckblatt, in Grand Robusto (5 x 56); Legacy of the Leaf, mexikanisches San-Andrés-Deckblatt, boxpressed (4½ x 60); und Hedonism, Connecticut-Broadleaf-Deckblatt, in Toro (6 x 52).',
        '[{"name":"Epiphany","color":"#A0522D","force":"Mild-Medium","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"Indonesisches Besuki-Umblatt, dominikanische und nicaraguanische Einlage, in Robusto (5 x 50), so Cigar Dojo."},{"name":"The Sacred Blend","color":"#A0522D","force":"Medium","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"Gleiches Deckblatt und gleiches Umblatt wie Epiphany, in Grand Robusto (5 x 56), so Cigar Dojo."},{"name":"Legacy of the Leaf","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Vollständig nicaraguanische Einlage, boxpressed (4½ x 60), so Cigar Dojo."},{"name":"Hedonism","color":"#4A2C1A","force":"Medium-Full","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Umblatt aus Condega, Broadleaf-Einlage aus Pennsylvania, dominikanisch und nicaraguanisch, in Toro (6 x 52), so Cigar Dojo."}]',
        'Los Amigos于2024年诞生，源于三位因烟草结缘的商旅友人之间的情谊：南非人Pedro Ramos，随父亲从事雪茄行业已十七年；巴西人Walter Saes；以及智利人Eduardo Lahsen，三人相识约十年，Wanted Online如是说。三人花了大约一年时间考察各家工厂，之后选定了一家尼加拉瓜的小型工厂，Ramos表示。

这家工厂就是位于埃斯特利的Tabacalera Familia Disla S.A.，同年由Esteban Disla——自幼在多米尼加共和国接触烟草——与Daniel Lance共同创立，Cigar Coop如是说。据该雪茄厂网站介绍，其工厂种植着八十公顷土地，除其他品牌外也卷制Domain Cigars。

2026年8月，Los Amigos通过Domain Distribution在美国市场首次亮相，这是Disla与Lance旗下公司Domain Cigars推出的一项服务，随Small Batch 2025系列一同发布，Cigar Dojo如是说：Epiphany，厄瓜多尔Habano茄衣，Robusto（5 x 50）；The Sacred Blend，茄衣相同，Grand Robusto（5 x 56）；Legacy of the Leaf，墨西哥San Andrés茄衣，盒压（4½ x 60）；以及Hedonism，Connecticut Broadleaf茄衣，Toro（6 x 52）。',
        '[{"name":"Epiphany","color":"#A0522D","force":"Mild-Medium","wrapper":"厄瓜多尔Habano","vitolas":[],"story":"印尼Besuki茄套，多米尼加与尼加拉瓜茄芯，Robusto（5 x 50），Cigar Dojo如是说。"},{"name":"The Sacred Blend","color":"#A0522D","force":"Medium","wrapper":"厄瓜多尔Habano","vitolas":[],"story":"茄衣与茄套均与Epiphany相同，Grand Robusto（5 x 56），Cigar Dojo如是说。"},{"name":"Legacy of the Leaf","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"茄芯全部产自尼加拉瓜，盒压造型（4½ x 60），Cigar Dojo如是说。"},{"name":"Hedonism","color":"#4A2C1A","force":"Medium-Full","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"茄套产自孔德加，茄芯混合宾夕法尼亚Broadleaf、多米尼加与尼加拉瓜烟叶，Toro（6 x 52），Cigar Dojo如是说。"}]',
        'وُلدت Los Amigos عام 2024 من صداقة جمعت ثلاثة رجال قرّبهم التبغ خلال رحلات عمل: Pedro Ramos، وهو جنوب أفريقي يعمل في صناعة السيجار إلى جانب والده منذ سبعة عشر عامًا، والبرازيلي Walter Saes، والتشيلي Eduardo Lahsen، وهما صديقان له منذ نحو عشر سنوات، كما تقول Wanted Online. أمضى الثلاثة نحو عام في زيارة المصانع قبل أن يستقروا على مصنع نيكاراغوي صغير، بحسب Ramos.

هذا المصنع هو Tabacalera Familia Disla S.A.، في إستيلي، الذي أسسه في العام نفسه Esteban Disla — العامل في التبغ منذ طفولته في جمهورية الدومينيكان — وDaniel Lance، كما تقول Cigar Coop. ويزرع مصنعهما ثمانين هكتارًا من الأراضي، ويلف أيضًا، من ضمن علامات أخرى، Domain Cigars، بحسب موقع المصنع.

في أغسطس 2026، دخلت Los Amigos السوق الأمريكية لأول مرة عبر Domain Distribution، وهي خدمة أطلقتها Domain Cigars، دار Disla وLance، مع مجموعة Small Batch 2025، كما تقول Cigar Dojo: Epiphany، غلاف Habano إكوادوري، بقياس Robusto (5 x 50)؛ The Sacred Blend، الغلاف نفسه، بقياس Grand Robusto (5 x 56)؛ Legacy of the Leaf، غلاف San Andrés مكسيكي، Box-pressed (4½ x 60)؛ وHedonism، غلاف Connecticut Broadleaf، بقياس Toro (6 x 52).',
        '[{"name":"Epiphany","color":"#A0522D","force":"Mild-Medium","wrapper":"Habano إكوادوري","vitolas":[],"story":"رباط Besuki إندونيسي، وحشوة دومينيكية ونيكاراغوية، بقياس Robusto (5 x 50)، كما تقول Cigar Dojo."},{"name":"The Sacred Blend","color":"#A0522D","force":"Medium","wrapper":"Habano إكوادوري","vitolas":[],"story":"الغلاف والرباط نفسهما كما في Epiphany، بقياس Grand Robusto (5 x 56)، كما تقول Cigar Dojo."},{"name":"Legacy of the Leaf","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"حشوة نيكاراغوية بالكامل، بقصة Box-pressed (4½ x 60)، كما تقول Cigar Dojo."},{"name":"Hedonism","color":"#4A2C1A","force":"Medium-Full","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"رباط من كونديغا، وحشوة من تبغ Broadleaf من بنسلفانيا إضافة إلى تبغ دومينيكي ونيكاراغوي، بقياس Toro (6 x 52)، كما تقول Cigar Dojo."}]')
