-- ── Schumacher ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Schumacher',
        'nicaragua',
        'Non précisée — Ralf Schumacher et Paul Bugge',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'cigarworld.de « Schumacher Selection » (24 septembre 2026 : roulage entièrement manuel au Nicaragua, cape Connecticut Shade, fabrique non nommée, format Double Toro puis Robusto) ; paul-bugge.com « Schumacher Selection » (24 septembre 2026, en allemand : distribution exclusive par Paul Bugge GmbH, tabacs nicaraguayens, fabrique non nommée) ; mynewschannel.net « Leidenschaft, die Genuss verbindet » (15 août 2025, en allemand : partenariat Ralf Schumacher / Paul Bugge GmbH, maison établie en 1951 à Villingen-Schwenningen) ; zigarrenwelt.de « Casa Culinaria » (24 septembre 2026 : Casa Culinaria développée et distribuée par Paul Bugge, fabriquée au Nicaragua)',
        NULL,
        'La ligne Schumacher Selection associe l''ancien pilote de Formule 1 Ralf Schumacher — à ne pas confondre avec Michael Schumacher — et Paul Bugge GmbH, maison de cigares de Villingen-Schwenningen, en Allemagne, qui la distribue en exclusivité, dit Cigarworld.de. Établie en 1951, la maison Paul Bugge annonce le partenariat en août 2025 comme une collaboration construite autour des goûts du pilote ; sa branche Paul Bugge Vertrieb, qui produit et distribue ses propres cigares, en assure la diffusion, dit MyNewsChannel.

Les cigares sont entièrement roulés à la main au Nicaragua, à partir d''une tripe nicaraguayenne fermentée et d''une cape Connecticut Shade claire, dit Paul Bugge GmbH, qui ne nomme pas sa fabrique. En septembre 2026, Cigarworld.de la vend en Double Toro (6 x 60) et en Robusto, d''un profil qu''il dit léger à moyen.

Paul Bugge vend aussi sa propre marque Casa Culinaria, roulée elle aussi au Nicaragua.',
        '[{"name":"Schumacher Selection","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade","vitolas":[],"story":"Tripe nicaraguayenne, en Double Toro (6 x 60) et en Robusto, dit Cigarworld.de."}]',
        'The Schumacher Selection line brings together the former Formula 1 driver Ralf Schumacher — not to be confused with Michael Schumacher — and Paul Bugge GmbH, a cigar house from Villingen-Schwenningen, Germany, which distributes it exclusively, says Cigarworld.de. Established in 1951, the Paul Bugge house announces the partnership in August 2025 as a collaboration built around the driver''s tastes; its branch Paul Bugge Vertrieb, which produces and distributes its own cigars, handles the distribution, says MyNewsChannel.

The cigars are entirely hand-rolled in Nicaragua, from a fermented Nicaraguan filler and a light Connecticut Shade wrapper, says Paul Bugge GmbH, which does not name its factory. As of September 2026, Cigarworld.de sells it in Double Toro (6 x 60) and Robusto, in a profile it describes as mild to medium.

Paul Bugge also sells its own brand Casa Culinaria, likewise rolled in Nicaragua.',
        '[{"name":"Schumacher Selection","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade","vitolas":[],"story":"Nicaraguan filler, in Double Toro (6 x 60) and Robusto, says Cigarworld.de."}]',
        'La línea Schumacher Selection une al expiloto de Fórmula 1 Ralf Schumacher —que no debe confundirse con Michael Schumacher— y Paul Bugge GmbH, casa de cigarros de Villingen-Schwenningen, en Alemania, que la distribuye en exclusiva, dice Cigarworld.de. Establecida en 1951, la casa Paul Bugge anuncia la alianza en agosto de 2025 como una colaboración construida en torno a los gustos del piloto; su filial Paul Bugge Vertrieb, que produce y distribuye sus propios cigarros, se encarga de la distribución, dice MyNewsChannel.

Los cigarros se elaboran totalmente a mano en Nicaragua, a partir de una tripa nicaragüense fermentada y una capa Connecticut Shade clara, dice Paul Bugge GmbH, que no nombra su fábrica. En septiembre de 2026, Cigarworld.de la vende en Double Toro (6 x 60) y en Robusto, con un perfil que describe como suave a medio.

Paul Bugge también vende su propia marca Casa Culinaria, elaborada igualmente en Nicaragua.',
        '[{"name":"Schumacher Selection","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade","vitolas":[],"story":"Tripa nicaragüense, en Double Toro (6 x 60) y en Robusto, dice Cigarworld.de."}]',
        'Die Linie Schumacher Selection verbindet den ehemaligen Formel-1-Piloten Ralf Schumacher — nicht zu verwechseln mit Michael Schumacher — und die Paul Bugge GmbH, ein Zigarrenhaus aus Villingen-Schwenningen in Deutschland, das sie exklusiv vertreibt, so Cigarworld.de. Das 1951 gegründete Haus Paul Bugge kündigt die Partnerschaft im August 2025 als eine um den Geschmack des Piloten herum aufgebaute Zusammenarbeit an; ihr Geschäftsbereich Paul Bugge Vertrieb, der eigene Zigarren produziert und vertreibt, übernimmt den Vertrieb, so MyNewsChannel.

Die Zigarren werden vollständig von Hand in Nicaragua gerollt, aus einer fermentierten nicaraguanischen Einlage und einem hellen Connecticut-Shade-Deckblatt, so Paul Bugge GmbH, die ihre Fabrik nicht nennt. Im September 2026 verkauft Cigarworld.de sie in Double Toro (6 x 60) und in Robusto, mit einem Profil, das es als leicht bis mittelkräftig bezeichnet.

Paul Bugge verkauft auch seine eigene Marke Casa Culinaria, die ebenfalls in Nicaragua gedreht wird.',
        '[{"name":"Schumacher Selection","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade","vitolas":[],"story":"Nicaraguanische Einlage, in Double Toro (6 x 60) und in Robusto, so Cigarworld.de."}]',
        'Schumacher Selection系列由前一级方程式赛车手Ralf Schumacher——不要与Michael Schumacher混淆——与德国菲林根-施文宁根的雪茄公司Paul Bugge GmbH联合推出，后者对其享有独家经销权，Cigarworld.de如是说。成立于1951年的Paul Bugge公司在2025年8月宣布这项合作，称其围绕这位车手的口味打造；其旗下负责生产与经销自有雪茄的分支机构Paul Bugge Vertrieb负责该系列的经销，MyNewsChannel如是说。

这些雪茄完全在尼加拉瓜手工卷制，采用经发酵的尼加拉瓜茄芯与浅色Connecticut Shade茄衣，Paul Bugge GmbH表示，但并未透露其工厂名称。截至2026年9月，Cigarworld.de以Double Toro（6 x 60）与Robusto两种规格销售，其浓度被描述为轻至中等。

Paul Bugge还销售其自有品牌Casa Culinaria，同样在尼加拉瓜卷制。',
        '[{"name":"Schumacher Selection","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade","vitolas":[],"story":"尼加拉瓜茄芯，Double Toro（6 x 60）与Robusto两种规格，Cigarworld.de如是说。"}]',
        'تجمع سلسلة Schumacher Selection بين سائق الفورمولا 1 السابق Ralf Schumacher — الذي لا ينبغي الخلط بينه وبين Michael Schumacher — وشركة Paul Bugge GmbH، دار سيجار من فيلينغن-شفينينغن بألمانيا، التي توزّعها حصريًا، كما تقول Cigarworld.de. وتعلن دار Paul Bugge، المؤسَّسة عام 1951، عن هذه الشراكة في أغسطس 2025 بوصفها تعاونًا بُني حول أذواق السائق؛ ويتولى فرعها Paul Bugge Vertrieb، الذي ينتج ويوزّع سيجاراته الخاصة، مهمة التوزيع، كما تقول MyNewsChannel.

تُلَفّ السيجار بالكامل يدويًا في نيكاراغوا، من حشوة نيكاراغوية مخمَّرة وغلاف Connecticut Shade فاتح، كما تقول Paul Bugge GmbH التي لا تسمي مصنعها. وحتى سبتمبر 2026، تبيعها Cigarworld.de بقياس Double Toro (6 x 60) وبقياس Robusto، بقوة تصفها بأنها خفيفة إلى متوسطة.

تبيع Paul Bugge أيضًا علامتها الخاصة Casa Culinaria، التي تُلَفّ هي الأخرى في نيكاراغوا.',
        '[{"name":"Schumacher Selection","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade","vitolas":[],"story":"حشوة نيكاراغوية، بقياس Double Toro (6 x 60) وبقياس Robusto، كما تقول Cigarworld.de."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Umnum ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Umnum',
        'nicaragua',
        'Non précisée — Gesinta (Ramón Zapata), Valence',
        'Chez Aganorsa Leaf (Tabacos Valle de Jalapa S.A., TABSA), Estelí, Nicaragua',
        'cigarworld.de « Umnum: Buy cigars online » (24 septembre 2026 : propriété de Gesinta International Tobacco Company, établie en 1997 par Ramón Zapata à Valence, marque sœur de Condega, deux lignes Umnum Nicaragua et Umnum Honduras avec capes, liants, tripes et formats) ; cuencacigars.com « Tabacos Valle de Jalapa S.A. Guide » (24 septembre 2026 : TABSA, fondation agricole et industrielle d''Aganorsa Leaf à Estelí, Jalapa et Condega, propriété d''Eduardo et Max Fernández)',
        NULL,
        'Umnum appartient à Gesinta International Tobacco Company, maison espagnole établie en 1997 par Ramón Zapata à Valence, dit Cigarworld.de. La maison ne date pas la création d''Umnum, que Cigarworld.de décrit comme la ligne économique sœur de Condega.

Les Umnum sont roulés au Nicaragua chez Aganorsa Leaf, à travers sa manufacture Tabacos Valle de Jalapa S.A. (TABSA), fondation agricole et industrielle du groupe à Estelí, Jalapa et Condega, propriété d''Eduardo Fernández et de son fils Max, dit Cuenca Cigars. La tripe mêle tabacs du Nicaragua et du Honduras, cultivés à Jalapa et à Estelí.

Le catalogue distingue deux lignes, dit Cigarworld.de : Umnum Nicaragua, cape Sungrown nicaraguayenne et sous-cape indonésienne, aux arômes terreux, café et noisette, en cinq formats dont le Canonazo (Robusto), le Hurakan et le Chaman ; et Umnum Honduras, cape hondurienne et sous-cape mexicaine, au profil plus corsé et plus sucré, en formats Champion et Robusto. En septembre 2026, Cigarworld.de vend toujours les deux lignes.',
        '[{"name":"Umnum Nicaragua","color":"#8B5A2B","force":null,"wrapper":"Sungrown (Nicaragua)","vitolas":[],"story":"Sous-cape indonésienne, tripe de Jalapa et d''Estelí, arômes terreux, café et noisette, en cinq formats dont Canonazo (Robusto), Hurakan et Chaman, dit Cigarworld.de."},{"name":"Umnum Honduras","color":"#6B4226","force":null,"wrapper":"Hondurien","vitolas":[],"story":"Sous-cape mexicaine, même tripe que la ligne Nicaragua, profil plus corsé et plus sucré, en Champion et Robusto, dit Cigarworld.de."}]',
        'Umnum belongs to Gesinta International Tobacco Company, a Spanish house established in 1997 by Ramón Zapata in Valencia, says Cigarworld.de. The house does not date the creation of Umnum, which Cigarworld.de describes as Condega''s cheaper sister line.

Umnum cigars are rolled in Nicaragua at Aganorsa Leaf, through its factory Tabacos Valle de Jalapa S.A. (TABSA), the group''s agricultural and industrial foundation in Estelí, Jalapa and Condega, owned by Eduardo Fernández and his son Max, says Cuenca Cigars. The filler blends tobaccos from Nicaragua and Honduras, grown in Jalapa and Estelí.

The catalogue distinguishes two lines, says Cigarworld.de: Umnum Nicaragua, Nicaraguan Sungrown wrapper and Indonesian binder, with earthy, coffee and hazelnut aromas, in five formats including the Canonazo (Robusto), the Hurakan and the Chaman; and Umnum Honduras, Honduran wrapper and Mexican binder, with a fuller-bodied, sweeter profile, in Champion and Robusto formats. As of September 2026, Cigarworld.de still sells both lines.',
        '[{"name":"Umnum Nicaragua","color":"#8B5A2B","force":null,"wrapper":"Sungrown (Nicaragua)","vitolas":[],"story":"Indonesian binder, filler from Jalapa and Estelí, earthy, coffee and hazelnut aromas, in five formats including Canonazo (Robusto), Hurakan and Chaman, says Cigarworld.de."},{"name":"Umnum Honduras","color":"#6B4226","force":null,"wrapper":"Honduran","vitolas":[],"story":"Mexican binder, same filler as the Nicaragua line, fuller-bodied, sweeter profile, in Champion and Robusto, says Cigarworld.de."}]',
        'Umnum pertenece a Gesinta International Tobacco Company, casa española establecida en 1997 por Ramón Zapata en Valencia, dice Cigarworld.de. La casa no data la creación de Umnum, que Cigarworld.de describe como la línea económica hermana de Condega.

Los Umnum se elaboran en Nicaragua en Aganorsa Leaf, a través de su manufactura Tabacos Valle de Jalapa S.A. (TABSA), fundación agrícola e industrial del grupo en Estelí, Jalapa y Condega, propiedad de Eduardo Fernández y su hijo Max, dice Cuenca Cigars. La tripa mezcla tabacos de Nicaragua y Honduras, cultivados en Jalapa y en Estelí.

El catálogo distingue dos líneas, dice Cigarworld.de: Umnum Nicaragua, capa Sungrown nicaragüense y capote indonesio, con aromas terrosos, a café y avellana, en cinco formatos entre ellos el Canonazo (Robusto), el Hurakan y el Chaman; y Umnum Honduras, capa hondureña y capote mexicano, de perfil más corpulento y más dulce, en formatos Champion y Robusto. En septiembre de 2026, Cigarworld.de sigue vendiendo ambas líneas.',
        '[{"name":"Umnum Nicaragua","color":"#8B5A2B","force":null,"wrapper":"Sungrown (Nicaragua)","vitolas":[],"story":"Capote indonesio, tripa de Jalapa y Estelí, aromas terrosos, a café y avellana, en cinco formatos entre ellos Canonazo (Robusto), Hurakan y Chaman, dice Cigarworld.de."},{"name":"Umnum Honduras","color":"#6B4226","force":null,"wrapper":"Hondureño","vitolas":[],"story":"Capote mexicano, misma tripa que la línea Nicaragua, perfil más corpulento y más dulce, en Champion y Robusto, dice Cigarworld.de."}]',
        'Umnum gehört zur Gesinta International Tobacco Company, einem spanischen Haus, das 1997 von Ramón Zapata in Valencia gegründet wurde, so Cigarworld.de. Das Haus datiert die Entstehung von Umnum nicht; Cigarworld.de beschreibt sie als die preisgünstigere Schwesterlinie von Condega.

Die Umnum werden in Nicaragua bei Aganorsa Leaf gedreht, über dessen Manufaktur Tabacos Valle de Jalapa S.A. (TABSA), die landwirtschaftliche und industrielle Grundlage der Gruppe in Estelí, Jalapa und Condega, im Besitz von Eduardo Fernández und seinem Sohn Max, so Cuenca Cigars. Die Einlage mischt Tabake aus Nicaragua und Honduras, angebaut in Jalapa und in Estelí.

Das Sortiment unterscheidet zwei Linien, so Cigarworld.de: Umnum Nicaragua, nicaraguanisches Sungrown-Deckblatt und indonesisches Umblatt, mit erdigen Aromen, Kaffee und Haselnuss, in fünf Formaten, darunter der Canonazo (Robusto), der Hurakan und der Chaman; und Umnum Honduras, honduranisches Deckblatt und mexikanisches Umblatt, mit einem kräftigeren und süßeren Profil, in den Formaten Champion und Robusto. Im September 2026 verkauft Cigarworld.de weiterhin beide Linien.',
        '[{"name":"Umnum Nicaragua","color":"#8B5A2B","force":null,"wrapper":"Sungrown (Nicaragua)","vitolas":[],"story":"Indonesisches Umblatt, Einlage aus Jalapa und Estelí, erdige Aromen, Kaffee und Haselnuss, in fünf Formaten, darunter Canonazo (Robusto), Hurakan und Chaman, so Cigarworld.de."},{"name":"Umnum Honduras","color":"#6B4226","force":null,"wrapper":"Honduranisch","vitolas":[],"story":"Mexikanisches Umblatt, gleiche Einlage wie die Linie Nicaragua, kräftigeres und süßeres Profil, in Champion und Robusto, so Cigarworld.de."}]',
        'Umnum隶属于Gesinta International Tobacco Company，这是一家由Ramón Zapata于1997年在巴伦西亚创立的西班牙公司，Cigarworld.de如是说。该公司并未说明Umnum的创立时间，Cigarworld.de将其描述为Condega旗下价格更亲民的姊妹系列。

Umnum在尼加拉瓜由Aganorsa Leaf卷制，具体通过其旗下的Tabacos Valle de Jalapa S.A.（TABSA）工厂完成，后者是该集团在埃斯特利、哈拉帕与孔德加的农业与工业根基，归Eduardo Fernández与其子Max所有，Cuenca Cigars如是说。茄芯混合了产自尼加拉瓜与洪都拉斯、种植于哈拉帕与埃斯特利的烟叶。

该系列分为两条产品线，Cigarworld.de如是说：Umnum Nicaragua，尼加拉瓜Sungrown茄衣与印尼茄套，带有泥土、咖啡与榛子香气，共五种规格，其中包括Canonazo（Robusto规格）、Hurakan与Chaman；以及Umnum Honduras，洪都拉斯茄衣与墨西哥茄套，风味更浓郁、更甜，规格为Champion与Robusto。截至2026年9月，Cigarworld.de仍在销售这两条系列。',
        '[{"name":"Umnum Nicaragua","color":"#8B5A2B","force":null,"wrapper":"Sungrown（尼加拉瓜）","vitolas":[],"story":"印尼茄套，茄芯产自哈拉帕与埃斯特利，带有泥土、咖啡与榛子香气，共五种规格，其中包括Canonazo（Robusto规格）、Hurakan与Chaman，Cigarworld.de如是说。"},{"name":"Umnum Honduras","color":"#6B4226","force":null,"wrapper":"洪都拉斯","vitolas":[],"story":"墨西哥茄套，茄芯与Nicaragua系列相同，风味更浓郁、更甜，规格为Champion与Robusto，Cigarworld.de如是说。"}]',
        'تنتمي Umnum إلى Gesinta International Tobacco Company، وهي دار إسبانية أسسها Ramón Zapata عام 1997 في بلنسية، كما تقول Cigarworld.de. ولا تحدد الدار تاريخ نشأة Umnum، التي تصفها Cigarworld.de بأنها الخط الشقيق لعلامة Condega، وإن كان أرخص منها.

تُلَفّ سيجار Umnum في نيكاراغوا لدى Aganorsa Leaf، عبر مصنعها Tabacos Valle de Jalapa S.A. (TABSA)، القاعدة الزراعية والصناعية للمجموعة في إستيلي وخالابا وكونديغا، المملوكة لـEduardo Fernández ونجله Max، كما تقول Cuenca Cigars. وتمزج الحشوة تبغًا من نيكاراغوا وهندوراس، مزروعًا في خالابا وإستيلي.

تميّز التشكيلة بين خطين، كما تقول Cigarworld.de: Umnum Nicaragua، بغلاف Sungrown نيكاراغوي ورباط إندونيسي، بنكهات ترابية وقهوة وبندق، بخمسة قياسات من بينها Canonazo (بقياس Robusto)، وHurakan، وChaman؛ وUmnum Honduras، بغلاف هندوراسي ورباط مكسيكي، بطابع أشدّ قوةً وأشدّ حلاوةً، بقياسَي Champion وRobusto. وحتى سبتمبر 2026، لا تزال Cigarworld.de تبيع الخطين معًا.',
        '[{"name":"Umnum Nicaragua","color":"#8B5A2B","force":null,"wrapper":"Sungrown (نيكاراغوا)","vitolas":[],"story":"رباط إندونيسي، وحشوة من خالابا وإستيلي، بنكهات ترابية وقهوة وبندق، بخمسة قياسات من بينها Canonazo (بقياس Robusto)، وHurakan، وChaman، كما تقول Cigarworld.de."},{"name":"Umnum Honduras","color":"#6B4226","force":null,"wrapper":"هندوراسي","vitolas":[],"story":"رباط مكسيكي، الحشوة نفسها المستخدمة في خط Nicaragua، بطابع أشدّ قوةً وأشدّ حلاوةً، بقياسَي Champion وRobusto، كما تقول Cigarworld.de."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Villa Vieja ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Villa Vieja',
        'nicaragua',
        '2022 — Fernando Navarro (Cigar Conexion)',
        'Chez Aganorsa Leaf (Tabacos Valle de Jalapa S.A., TABSA), Estelí, Nicaragua',
        'villaviejacigars.com « History » (24 septembre 2026 : Fernando Navarro crée Villa Vieja en hommage à Estelí, développement dès le 26 novembre 2019, première production en avril 2022, lancement mi-2022, roulage chez Aganorsa) ; villaviejacigars.com « Products » (24 septembre 2026 : ligne Clásico, cape Habano de Jalapa, corps moyen à complet, formats Short, Robusto, Toro) ; cigarcentury.com « Villa Vieja » (24 septembre 2026 : confirme la ligne Clásico et ses capes) ; cigarconexion.com « Brands » (24 septembre 2026 : Don Duarte roulée chez Pages depuis 2020, Villa Vieja roulée chez Aganorsa, les deux marques appartenant à Fernando Navarro / Tabamundo S.A.) ; cigarjournal.com « Don Duarte and Villa Vieja Go Bigger » (17 septembre 2026 : nouveaux formats Super Ancho pour Don Duarte et Grandeur pour Villa Vieja présentés à l''InterTabac 2026 ; Navarro dit rouler Don Duarte et Cuervo y Sobrinos chez Tabacalera Pages, à Estelí)',
        NULL,
        'Fernando Navarro crée Villa Vieja en hommage à Estelí, sa ville d''origine, à travers son enseigne Cigar Conexion, dit la maison. Les premiers essais de mélange datent du 26 novembre 2019 ; la première production commerciale remonte à avril 2022 et la marque est lancée au public au milieu de la même année. La maison cite parmi les artisans du mélange Eduardo et Max Fernández, ainsi que Jacinto Iglesias et Harold Zeledón.

Villa Vieja est roulée chez Aganorsa Leaf, dit la maison — la manufacture Tabacos Valle de Jalapa S.A. que la famille Fernández possède à Estelí. Navarro y roule une ligne unique, Clásico, cape Habano cultivée à Jalapa, tripe et sous-cape nicaraguayennes, corps moyen à complet, en trois formats (Short, Robusto, Toro) ; à l''InterTabac de septembre 2026, il présente un quatrième format, Grandeur (5½ x 60) : la ligne n''avait pas de vitola en cepo 60, dit-il.

Navarro fait rouler sa marque sœur Don Duarte, ainsi que Cuervo y Sobrinos, chez son partenaire Raymond Pages, à la Tabacalera Pages d''Estelí.',
        '[{"name":"Clásico","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (Jalapa, Nicaragua)","vitolas":[],"story":"Tripe et sous-cape nicaraguayennes, cape cultivée à Jalapa, en Short, Robusto et Toro, puis en Grandeur (5½ x 60), présenté à l''InterTabac 2026."}]',
        'Fernando Navarro creates Villa Vieja as a tribute to Estelí, his home town, through his company Cigar Conexion, says the house. The first blending trials date from 26 November 2019; the first commercial production dates back to April 2022, and the brand is launched to the public in the middle of that same year. The house names among the blend''s craftsmen Eduardo and Max Fernández, as well as Jacinto Iglesias and Harold Zeledón.

Villa Vieja is rolled at Aganorsa Leaf, says the house — the factory Tabacos Valle de Jalapa S.A. that the Fernández family owns in Estelí. There, Navarro rolls a single line, Clásico, Habano wrapper grown in Jalapa, Nicaraguan filler and binder, medium to full body, in three formats (Short, Robusto, Toro); at InterTabac in September 2026, he presents a fourth format, Grandeur (5½ x 60): the line had no vitola in a 60 ring gauge, he says.

Navarro has his sister brand Don Duarte, as well as Cuervo y Sobrinos, rolled by his partner Raymond Pages, at the Tabacalera Pages in Estelí.',
        '[{"name":"Clásico","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (Jalapa, Nicaragua)","vitolas":[],"story":"Nicaraguan filler and binder, wrapper grown in Jalapa, in Short, Robusto and Toro, then in Grandeur (5½ x 60), presented at InterTabac 2026."}]',
        'Fernando Navarro crea Villa Vieja como homenaje a Estelí, su ciudad natal, a través de su empresa Cigar Conexion, dice la casa. Las primeras pruebas de mezcla datan del 26 de noviembre de 2019; la primera producción comercial se remonta a abril de 2022 y la marca se lanza al público a mediados de ese mismo año. La casa cita entre los artífices de la mezcla a Eduardo y Max Fernández, así como a Jacinto Iglesias y Harold Zeledón.

Villa Vieja se elabora en Aganorsa Leaf, dice la casa —la manufactura Tabacos Valle de Jalapa S.A. que la familia Fernández posee en Estelí. Allí Navarro elabora una única línea, Clásico, capa Habano cultivada en Jalapa, tripa y capote nicaragüenses, cuerpo medio a completo, en tres formatos (Short, Robusto, Toro); en la InterTabac de septiembre de 2026 presenta un cuarto formato, Grandeur (5½ x 60): la línea no tenía vitola de cepo 60, dice.

Navarro hace elaborar su marca hermana Don Duarte, así como Cuervo y Sobrinos, con su socio Raymond Pages, en la Tabacalera Pages de Estelí.',
        '[{"name":"Clásico","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (Jalapa, Nicaragua)","vitolas":[],"story":"Tripa y capote nicaragüenses, capa cultivada en Jalapa, en Short, Robusto y Toro, luego en Grandeur (5½ x 60), presentado en la InterTabac 2026."}]',
        'Fernando Navarro schafft Villa Vieja als Hommage an Estelí, seine Heimatstadt, über sein Unternehmen Cigar Conexion, so das Haus. Die ersten Mischungsversuche stammen vom 26. November 2019; die erste kommerzielle Produktion geht auf April 2022 zurück, und die Marke wird Mitte desselben Jahres der Öffentlichkeit vorgestellt. Das Haus nennt unter den Machern der Mischung Eduardo und Max Fernández sowie Jacinto Iglesias und Harold Zeledón.

Villa Vieja wird bei Aganorsa Leaf gedreht, so das Haus — der Manufaktur Tabacos Valle de Jalapa S.A., die der Familie Fernández in Estelí gehört. Dort dreht Navarro eine einzige Linie, Clásico, Habano-Deckblatt, angebaut in Jalapa, nicaraguanische Einlage und Umblatt, mittlerer bis voller Körper, in drei Formaten (Short, Robusto, Toro); auf der InterTabac im September 2026 stellt er ein viertes Format vor, Grandeur (5½ x 60): Der Linie fehlte bislang eine Vitola mit Ringmaß 60, so Navarro.

Navarro lässt seine Schwestermarke Don Duarte sowie Cuervo y Sobrinos bei seinem Partner Raymond Pages in der Tabacalera Pages in Estelí drehen.',
        '[{"name":"Clásico","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (Jalapa, Nicaragua)","vitolas":[],"story":"Nicaraguanische Einlage und Umblatt, Deckblatt angebaut in Jalapa, in Short, Robusto und Toro, dann in Grandeur (5½ x 60), vorgestellt auf der InterTabac 2026."}]',
        'Fernando Navarro通过自己的公司Cigar Conexion创立了Villa Vieja，以致敬他的家乡埃斯特利，该品牌介绍如是说。最初的调配试验可追溯到2019年11月26日；首次商业化生产始于2022年4月，品牌于同年年中正式面向公众推出。该品牌提到参与调配的匠人包括Eduardo与Max Fernández，以及Jacinto Iglesias与Harold Zeledón。

Villa Vieja在Aganorsa Leaf卷制，该品牌介绍如是说——即Fernández家族在埃斯特利拥有的Tabacos Valle de Jalapa S.A.工厂。Navarro在那里卷制唯一一条产品线Clásico，茄衣为产自哈拉帕的Habano，茄芯与茄套产自尼加拉瓜，浓度中等偏浓，共三种规格（Short、Robusto、Toro）；在2026年9月的InterTabac展会上，他推出第四种规格Grandeur（5½ x 60）：该系列此前没有60环径的规格，他表示。

Navarro让合作伙伴Raymond Pages在埃斯特利的Tabacalera Pages卷制他的姊妹品牌Don Duarte，以及Cuervo y Sobrinos。',
        '[{"name":"Clásico","color":"#A0522D","force":"Medium-Full","wrapper":"Habano（哈拉帕，尼加拉瓜）","vitolas":[],"story":"茄芯与茄套产自尼加拉瓜，茄衣种植于哈拉帕，规格为Short、Robusto与Toro，随后推出Grandeur（5½ x 60），于2026年InterTabac展会上发布。"}]',
        'أنشأ Fernando Navarro علامة Villa Vieja تكريمًا لمدينته إستيلي، عبر شركته Cigar Conexion، كما تقول الدار. تعود أولى تجارب المزج إلى 26 نوفمبر 2019؛ ويعود أول إنتاج تجاري إلى أبريل 2022، وأُطلقت العلامة للجمهور في منتصف العام نفسه. وتذكر الدار من بين صانعي المزيج Eduardo وMax Fernández، إضافة إلى Jacinto Iglesias وHarold Zeledón.

تُلَفّ Villa Vieja لدى Aganorsa Leaf، كما تقول الدار — وهو مصنع Tabacos Valle de Jalapa S.A. الذي تملكه عائلة Fernández في إستيلي. وهناك يلف Navarro خطًا واحدًا هو Clásico، بغلاف Habano مزروع في خالابا، وحشوة ورباط من نيكاراغوا، بقوة متوسطة إلى كاملة، بثلاثة قياسات (Short، وRobusto، وToro)؛ وفي معرض InterTabac في سبتمبر 2026، قدّم قياسًا رابعًا هو Grandeur (5½ x 60): إذ لم يكن للخط سابقًا قياس بمحيط 60، كما يقول.

يجعل Navarro علامته الشقيقة Don Duarte، وكذلك Cuervo y Sobrinos، تُلَفّ لدى شريكه Raymond Pages، في Tabacalera Pages بإستيلي.',
        '[{"name":"Clásico","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (خالابا، نيكاراغوا)","vitolas":[],"story":"حشوة ورباط من نيكاراغوا، وغلاف مزروع في خالابا، بقياسات Short وRobusto وToro، ثم Grandeur (5½ x 60)، الذي قُدِّم في معرض InterTabac 2026."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Samana ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Samana',
        'dominican',
        'Non précisée — Oskar Nausch, Santiago',
        'Chez Tabacalera Don Esteban (Oskar Nausch), Santiago de los Caballeros (République dominicaine)',
        'cigarworld.de « Capadura Cigars » (s. d. : établit qu''Oskar Nausch, originaire de Wuppertal, est propriétaire et directeur de la Tabacalera Don Esteban, à Santiago de los Caballeros, et y fait rouler notamment Samana, distribué surtout en Suisse et en Autriche) ; cigarworld.de « Samana Cigars » (s. d. : établit l''orthographe « Samana », le fabricant Oskar Nausch et sa Tabacalera Don Esteban, le pays de roulage, la cape Connecticut Shade Claro et une quinzaine de formats pour la ligne classique) ; cigarworld.de « Samana » (page de marque, s. d. : liste quatre lignes au catalogue — Cigars, 1756, Special Edition, Oscuro) ; cigar.ch « Die Herkunft im Blick » (en allemand ; s. d. : établit la fondation de la Tabacalera Don Esteban en 1997 par Peter Rohner pour la maison suisse Wellauer AG, le parcours médical d''Oskar Nausch avant qu''il n''en prenne la direction, et une production annuelle proche de 1,2 million de cigares) ; fumar.ch « Samana Zigarren aus der Dominikanischen Republik » (en allemand ; s. d. : établit l''installation d''Oskar Nausch en République dominicaine depuis plus de trente ans, la ligne 1756 Series et la Nicaragua Line, le tabac du Cibao) ; noblego.de « Samana 1756 Corona » (en allemand ; s. d. : établit pour la ligne 1756 une cape Connecticut d''Équateur, une sous-cape dominicaine, une tripe du Cibao Valley et un corps medium) ; zigarrenversand.ch « Samaná Robusto » (en allemand ; s. d. : établit pour la ligne classique une cape US-Connecticut Shade Claro et un corps léger) ; zigarrenversand.ch « Samaná Nicaragua Line » (en allemand ; s. d. : établit pour la Nicaragua Line une cape Habano 2000 d''Équateur, une sous-cape Olor, une tripe de ligero et de seco d''Estelí et un corps plein, en coffret bleu et blanc) ; smokersplanet.de « Welcome „Samana Flair“ » (en allemand ; s. d. : établit la ligne Flair, assemblée par Oskar et Adrian Nausch, sous cape US-Connecticut)',
        NULL,
        'Oskar Nausch, médecin allemand originaire de Wuppertal spécialisé dans la médecine des pays en développement, est propriétaire et directeur de la Tabacalera Don Esteban, à Santiago de los Caballeros, en République dominicaine, dit cigarworld.de. La fabrique elle-même a été établie en 1997 par Peter Rohner pour la maison suisse Wellauer AG ; un premier essai avait échoué avant que Nausch n''en prenne la direction, dit cigar.ch, qui la situe autour de 1,2 million de cigares par an. Nausch y roule aussi une autre marque, Capadura. La maison ne date pas la création de Samana.

Samana se roule entièrement à la main à Don Esteban, en plusieurs lignes. La ligne classique porte une cape Connecticut Shade Claro américaine et une sous-cape dominicaine, en une quinzaine de formats, du Chico au Piramide, pour un corps léger, dit cigarworld.de. La ligne 1756 reprend une cape Connecticut d''Équateur sur une tripe du Cibao, pour un corps medium, dit noblego.de. La Nicaragua Line, plus récente, associe une cape Habano 2000 d''Équateur à une tripe de ligero et de seco d''Estelí, pour un corps plein, en coffret bleu et blanc, dit zigarrenversand.ch. La ligne Flair est un assemblage conçu par Nausch et son fils Adrian, sous cape Connecticut, dit smokersplanet.de.

La marque se distribue surtout en Suisse et en Autriche, avec une relation ancienne de vingt ans avec le détaillant cigarworld.de, qui la tient au catalogue avec noblego.de, fumar.ch et zigarrenversand.ch en septembre 2026.',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade Claro (USA)","vitolas":[],"story":"En une quinzaine de formats, du Chico au Piramide, dit cigarworld.de."},{"name":"1756","color":"#A0522D","force":"Medium","wrapper":"Connecticut Shade (Équateur)","vitolas":[],"story":"Tripe du Cibao Valley et sous-cape dominicaine, dit noblego.de."},{"name":"Nicaragua Line","color":"#6B4226","force":"Full","wrapper":"Habano 2000 (Équateur)","vitolas":[],"story":"Tripe de ligero et de seco d''Estelí, en coffret bleu et blanc, dit zigarrenversand.ch."},{"name":"Flair","color":"#C9A96E","force":null,"wrapper":"Connecticut (USA)","vitolas":[],"story":"Assemblage conçu par Oskar Nausch et son fils Adrian, dit smokersplanet.de."}]',
        'Oskar Nausch, a German doctor from Wuppertal specialising in medicine for developing countries, is the owner and director of Tabacalera Don Esteban, in Santiago de los Caballeros, Dominican Republic, says cigarworld.de. The factory itself was established in 1997 by Peter Rohner for the Swiss house Wellauer AG; a first attempt had failed before Nausch took over its direction, says cigar.ch, which puts output at around 1.2 million cigars a year. Nausch also rolls another brand there, Capadura. The house does not date the creation of Samana.

Samana is rolled entirely by hand at Don Esteban, in several lines. The classic line carries an American Connecticut Shade Claro wrapper and a Dominican binder, in around fifteen formats, from Chico to Piramide, for a mild body, says cigarworld.de. The 1756 line uses an Ecuadorian Connecticut wrapper over a Cibao Valley filler, for a medium body, says noblego.de. The Nicaragua Line, more recent, pairs an Ecuadorian Habano 2000 wrapper with a ligero and seco filler from Estelí, for a full body, in a blue and white box, says zigarrenversand.ch. The Flair line is a blend created by Nausch and his son Adrian, under a Connecticut wrapper, says smokersplanet.de.

The brand is distributed mainly in Switzerland and Austria, with a twenty-year relationship with the retailer cigarworld.de, which stocks it alongside noblego.de, fumar.ch and zigarrenversand.ch as of September 2026.',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade Claro (USA)","vitolas":[],"story":"In around fifteen formats, from Chico to Piramide, says cigarworld.de."},{"name":"1756","color":"#A0522D","force":"Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Cibao Valley filler and Dominican binder, says noblego.de."},{"name":"Nicaragua Line","color":"#6B4226","force":"Full","wrapper":"Habano 2000 (Ecuador)","vitolas":[],"story":"Ligero and seco filler from Estelí, in a blue and white box, says zigarrenversand.ch."},{"name":"Flair","color":"#C9A96E","force":null,"wrapper":"Connecticut (USA)","vitolas":[],"story":"Blend created by Oskar Nausch and his son Adrian, says smokersplanet.de."}]',
        'Oskar Nausch, médico alemán originario de Wuppertal especializado en medicina de los países en desarrollo, es propietario y director de la Tabacalera Don Esteban, en Santiago de los Caballeros, República Dominicana, dice cigarworld.de. La propia fábrica fue fundada en 1997 por Peter Rohner para la casa suiza Wellauer AG; un primer intento había fracasado antes de que Nausch asumiera su dirección, dice cigar.ch, que la sitúa en torno a 1,2 millones de cigarros al año. Nausch también elabora allí otra marca, Capadura. La casa no fecha la creación de Samana.

Samana se elabora enteramente a mano en Don Esteban, en varias líneas. La línea clásica lleva una capa Connecticut Shade Claro estadounidense y una capote dominicana, en una quincena de formatos, del Chico al Piramide, para un cuerpo suave, dice cigarworld.de. La línea 1756 recurre a una capa Connecticut de Ecuador sobre una tripa del Cibao Valley, para un cuerpo medio, dice noblego.de. La Nicaragua Line, más reciente, combina una capa Habano 2000 de Ecuador con una tripa de ligero y seco de Estelí, para un cuerpo pleno, en estuche azul y blanco, dice zigarrenversand.ch. La línea Flair es una liga creada por Nausch y su hijo Adrian, con capa Connecticut, dice smokersplanet.de.

La marca se distribuye sobre todo en Suiza y Austria, con una relación de veinte años con el comerciante cigarworld.de, que la mantiene en catálogo junto con noblego.de, fumar.ch y zigarrenversand.ch en septiembre de 2026.',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade Claro (EE. UU.)","vitolas":[],"story":"En una quincena de formatos, del Chico al Piramide, dice cigarworld.de."},{"name":"1756","color":"#A0522D","force":"Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Tripa del Cibao Valley y capote dominicana, dice noblego.de."},{"name":"Nicaragua Line","color":"#6B4226","force":"Full","wrapper":"Habano 2000 (Ecuador)","vitolas":[],"story":"Tripa de ligero y seco de Estelí, en estuche azul y blanco, dice zigarrenversand.ch."},{"name":"Flair","color":"#C9A96E","force":null,"wrapper":"Connecticut (EE. UU.)","vitolas":[],"story":"Liga creada por Oskar Nausch y su hijo Adrian, dice smokersplanet.de."}]',
        'Oskar Nausch, ein deutscher Arzt aus Wuppertal mit Spezialisierung auf Entwicklungsländermedizin, ist Eigentümer und Leiter der Tabacalera Don Esteban in Santiago de los Caballeros, Dominikanische Republik, so cigarworld.de. Die Fabrik selbst wurde 1997 von Peter Rohner für das Schweizer Haus Wellauer AG gegründet; ein erster Versuch war gescheitert, bevor Nausch die Leitung übernahm, so cigar.ch, das die Produktion auf rund 1,2 Millionen Zigarren pro Jahr beziffert. Nausch rollt dort auch eine weitere Marke, Capadura. Das Haus datiert die Gründung von Samana nicht.

Samana wird bei Don Esteban vollständig von Hand gerollt, in mehreren Linien. Die klassische Linie trägt ein amerikanisches Connecticut-Shade-Claro-Deckblatt und ein dominikanisches Umblatt, in rund fünfzehn Formaten, vom Chico bis zum Piramide, für einen milden Körper, so cigarworld.de. Die Linie 1756 verwendet ein ecuadorianisches Connecticut-Deckblatt über einer Einlage aus dem Cibao Valley, für einen mittleren Körper, so noblego.de. Die neuere Nicaragua Line verbindet ein ecuadorianisches Habano-2000-Deckblatt mit einer Einlage aus Ligero und Seco aus Estelí, für einen vollen Körper, in blau-weißer Kiste, so zigarrenversand.ch. Die Linie Flair ist eine von Nausch und seinem Sohn Adrian entwickelte Mischung unter Connecticut-Deckblatt, so smokersplanet.de.

Die Marke wird vor allem in der Schweiz und in Österreich vertrieben, mit einer zwanzigjährigen Beziehung zum Händler cigarworld.de, der sie im September 2026 zusammen mit noblego.de, fumar.ch und zigarrenversand.ch im Sortiment führt.',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade Claro (USA)","vitolas":[],"story":"In rund fünfzehn Formaten, vom Chico bis zum Piramide, so cigarworld.de."},{"name":"1756","color":"#A0522D","force":"Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Einlage aus dem Cibao Valley und dominikanisches Umblatt, so noblego.de."},{"name":"Nicaragua Line","color":"#6B4226","force":"Full","wrapper":"Habano 2000 (Ecuador)","vitolas":[],"story":"Einlage aus Ligero und Seco aus Estelí, in blau-weißer Kiste, so zigarrenversand.ch."},{"name":"Flair","color":"#C9A96E","force":null,"wrapper":"Connecticut (USA)","vitolas":[],"story":"Von Oskar Nausch und seinem Sohn Adrian entwickelte Mischung, so smokersplanet.de."}]',
        '据cigarworld.de介绍，Oskar Nausch是来自伍珀塔尔的德国医生，专攻发展中国家医学，现任多米尼加共和国圣地亚哥-德洛斯卡瓦列罗斯的Tabacalera Don Esteban雪茄厂所有者兼负责人。据cigar.ch介绍，该厂由Peter Rohner于1997年为瑞士的Wellauer AG创办；首次尝试曾失败，此后由Nausch接手管理，年产量约为120万支雪茄。Nausch在此还制作另一品牌Capadura。该厂未标明Samana品牌的创立年份。

Samana在Don Esteban完全手工卷制，共有多个系列。经典系列采用美国产Connecticut Shade Claro茄衣与多米尼加茄套，规格约十五种，从Chico到Piramide，力度温和，据cigarworld.de介绍。1756系列采用厄瓜多尔产Connecticut茄衣，茄芯来自Cibao Valley，力度适中，据noblego.de介绍。较新推出的Nicaragua Line将厄瓜多尔产Habano 2000茄衣与产自埃斯特利的ligero和seco茄芯结合，力度浓郁，装于蓝白礼盒，据zigarrenversand.ch介绍。Flair系列是Nausch与其子Adrian共同调配的配方，采用Connecticut茄衣，据smokersplanet.de介绍。

该品牌主要在瑞士和奥地利销售，与零售商cigarworld.de保持着二十年的合作关系；截至2026年9月，该店与noblego.de、fumar.ch及zigarrenversand.ch一同将其列入目录。',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade Claro（美国）","vitolas":[],"story":"规格约十五种，从Chico到Piramide，据cigarworld.de介绍。"},{"name":"1756","color":"#A0522D","force":"Medium","wrapper":"Connecticut Shade（厄瓜多尔）","vitolas":[],"story":"茄芯来自Cibao Valley，茄套为多米尼加烟叶，据noblego.de介绍。"},{"name":"Nicaragua Line","color":"#6B4226","force":"Full","wrapper":"Habano 2000（厄瓜多尔）","vitolas":[],"story":"茄芯采用产自埃斯特利的ligero与seco烟叶，装于蓝白礼盒，据zigarrenversand.ch介绍。"},{"name":"Flair","color":"#C9A96E","force":null,"wrapper":"Connecticut（美国）","vitolas":[],"story":"由Oskar Nausch与其子Adrian共同调配，据smokersplanet.de介绍。"}]',
        'يقول cigarworld.de إن Oskar Nausch، وهو طبيب ألماني من فوبرتال متخصص في طب البلدان النامية، هو مالك ومدير Tabacalera Don Esteban في سانتياغو دي لوس كاباييروس بالجمهورية الدومينيكية. ويقول cigar.ch إن المصنع نفسه أسسه Peter Rohner سنة 1997 لحساب دار Wellauer AG السويسرية؛ وقد باءت محاولة أولى بالفشل قبل أن يتولى Nausch إدارته، وتقدّر cigar.ch إنتاجه بنحو 1.2 مليون سيجار سنويًا. ويصنع Nausch هناك أيضًا علامة أخرى هي Capadura. ولا تحدد الدار تاريخ تأسيس Samana.

تُلف Samana يدويًا بالكامل في Don Esteban، ضمن عدة خطوط. يحمل الخط الكلاسيكي غلافًا أمريكيًا من نوع Connecticut Shade Claro ورباطًا دومينيكيًا، في نحو خمسة عشر مقاسًا، من Chico إلى Piramide، بقوة خفيفة، وفق cigarworld.de. ويعتمد خط 1756 غلاف Connecticut من الإكوادور فوق حشوة من Cibao Valley، بقوة متوسطة، وفق noblego.de. أما Nicaragua Line، الأحدث عهدًا، فيجمع بين غلاف Habano 2000 من الإكوادور وحشوة من ligero وseco من إستيلي، بقوة كاملة، في علبة زرقاء وبيضاء، وفق zigarrenversand.ch. وخط Flair مزيج ابتكره Nausch وابنه Adrian، تحت غلاف Connecticut، وفق smokersplanet.de.

تُوزَّع العلامة أساسًا في سويسرا والنمسا، بعلاقة تمتد عشرين عامًا مع تاجر السيجار cigarworld.de، الذي يعرضها في كتالوجه إلى جانب noblego.de وfumar.ch وzigarrenversand.ch في سبتمبر 2026.',
        '[{"name":"Classic","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade Claro (الولايات المتحدة)","vitolas":[],"story":"في نحو خمسة عشر مقاسًا، من Chico إلى Piramide، وفق cigarworld.de."},{"name":"1756","color":"#A0522D","force":"Medium","wrapper":"Connecticut Shade (الإكوادور)","vitolas":[],"story":"حشوة من Cibao Valley ورباط دومينيكي، وفق noblego.de."},{"name":"Nicaragua Line","color":"#6B4226","force":"Full","wrapper":"Habano 2000 (الإكوادور)","vitolas":[],"story":"حشوة من ligero وseco من إستيلي، في علبة زرقاء وبيضاء، وفق zigarrenversand.ch."},{"name":"Flair","color":"#C9A96E","force":null,"wrapper":"Connecticut (الولايات المتحدة)","vitolas":[],"story":"مزيج ابتكره Oskar Nausch وابنه Adrian، وفق smokersplanet.de."}]')
