INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('SYN',
        'dominican',
        'Non précisée — Joseph Casimir, Tamboril',
        'Usine propre — Tabacalera SYN, Tamboril, province de Santiago, République dominicaine',
        'synbrands.com « The Land » (s. d. : dit la maison, situe Tabacalera SYN à Tamboril, province de Santiago, présentée comme la capitale mondiale du cigare) ; synbrands.com « The Inspiration » (s. d. : dit la maison, Joseph Casimir a découvert le cigare en 1990 à l''université et a fondé Tabacalera SYN trois décennies plus tard, après diverses aventures commerciales, sans année précisée) ; synbrands.com « The Master Blender » (s. d. : dit la maison, Juan Rodriguez, maître assembleur et responsable de la fabrique, plus de trente-cinq ans d''expérience, travaille étroitement avec Leo Reyes, propriétaire actuel de De Los Reyes, pour le choix des tabacs) ; synbrands.com, page d''accueil (s. d. : dit la maison, structures commerciales SYN Cigars, Inc. à Miami, SYN Europe GmbH en Allemagne, SYN Asia, Ltd. au Vietnam, Olmaq Trading NV pour les Caraïbes, représentants en Israël, en Afrique et en Inde) ; synbrands.com « The Original SYN » (s. d. : dit la maison, ligne en deux versions de cape — Habano HVA vieilli cinq ans et Corojo Maduro vieilli cinq ans —, sous-cape dominicaine vieillie cinq ans, tripe de Corojo cubain cultivé en République dominicaine vieilli deux ans, en Petit Robusto et en Salomon) ; synbrands.com « The Seven SYN.s » (s. d. : dit la maison, collection de sept assemblages nommés d''après les péchés capitaux, tabac vieilli cinq ans principalement dominicain) ; synbrands.com « Story » (s. d. : dit la maison ; aucune année de fondation n''y figure)',
        NULL,
        'Joseph Casimir a fondé Tabacalera SYN à Tamboril, dans la province de Santiago, en République dominicaine, dit synbrands.com. Sa passion pour le cigare remonte à 1990, sa première semaine d''université ; il a fondé la maison trois décennies plus tard, après diverses aventures commerciales ; la maison ne date pas cette fondation.

Juan Rodriguez dirige la fabrique comme maître assembleur, fort de plus de trente-cinq ans d''expérience acquise auprès d''autres marques avant de rejoindre SYN, dit la maison. Il travaille étroitement avec Leo Reyes, propriétaire actuel de De Los Reyes Cigars, pour le choix des tabacs.

En septembre 2026, le catalogue compte deux lignes. The Original SYN se roule en deux versions de cape, l''une en Habano HVA vieilli cinq ans, l''autre en Corojo Maduro vieilli cinq ans, sur une sous-cape dominicaine et une tripe de Corojo cubain cultivé en République dominicaine, en Petit Robusto et en Salomon. The Seven Syns rassemble sept assemblages nommés d''après les péchés capitaux — GULA, IRA, ACEDIA, AVARITIA, LUXURIA, SUPERBIA, INVIDIA —, en tabac vieilli cinq ans, principalement dominicain, dit la maison.

SYN se vend par des structures propres : SYN Cigars, Inc. (Miami), SYN Europe GmbH (Allemagne), SYN Asia, Ltd. (Vietnam) et Olmaq Trading NV pour les Caraïbes, avec des représentants en Israël, en Afrique et en Inde.',
        '[{"name":"The Original SYN","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"En deux versions de cape — Habano HVA ou Corojo Maduro, vieillies cinq ans —, sur tripe de Corojo cubain cultivé en République dominicaine, en Petit Robusto et en Salomon, dit la maison."},{"name":"The Seven Syns","color":"#6B4226","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Sept assemblages nommés d''après les péchés capitaux — GULA (Habano 2000), IRA (San Andres Maduro), ACEDIA (Habano 2000), AVARITIA (Corojo Habano d''Équateur), LUXURIA (Habano 2000), SUPERBIA (Connecticut d''Équateur), INVIDIA (San Andres Maduro) —, tabac vieilli cinq ans, dit la maison."}]',
        'Joseph Casimir founded Tabacalera SYN in Tamboril, in Santiago province, Dominican Republic, says synbrands.com. His passion for cigars dates back to 1990, his first week at university; he founded the house three decades later, after various business ventures; the house does not date this founding.

Juan Rodriguez runs the factory as master blender, with more than thirty-five years of experience gained with other brands before joining SYN, says the house. He works closely with Leo Reyes, the current owner of De Los Reyes Cigars, on the choice of tobaccos.

As of September 2026, the catalogue holds two lines. The Original SYN is rolled in two wrapper versions, one in Habano HVA aged five years, the other in Corojo Maduro aged five years, over a Dominican binder and a filler of Cuban-seed Corojo grown in the Dominican Republic, in Petit Robusto and Salomon. The Seven Syns brings together seven blends named after the deadly sins — GULA, IRA, ACEDIA, AVARITIA, LUXURIA, SUPERBIA, INVIDIA — in tobacco aged five years, mostly Dominican, says the house.

SYN sells through its own structures: SYN Cigars, Inc. (Miami), SYN Europe GmbH (Germany), SYN Asia, Ltd. (Vietnam) and Olmaq Trading NV for the Caribbean, with representatives in Israel, Africa and India.',
        '[{"name":"The Original SYN","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"In two wrapper versions — Habano HVA or Corojo Maduro, both aged five years — over a filler of Cuban-seed Corojo grown in the Dominican Republic, in Petit Robusto and Salomon, says the house."},{"name":"The Seven Syns","color":"#6B4226","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Seven blends named after the deadly sins — GULA (Habano 2000), IRA (San Andres Maduro), ACEDIA (Habano 2000), AVARITIA (Corojo Habano from Ecuador), LUXURIA (Habano 2000), SUPERBIA (Connecticut from Ecuador), INVIDIA (San Andres Maduro) — in tobacco aged five years, says the house."}]',
        'Joseph Casimir fundó Tabacalera SYN en Tamboril, en la provincia de Santiago, República Dominicana, dice synbrands.com. Su pasión por el cigarro se remonta a 1990, su primera semana de universidad; fundó la casa tres décadas después, tras diversas aventuras comerciales; la casa no fecha esta fundación.

Juan Rodriguez dirige la fábrica como maestro ligador, con más de treinta y cinco años de experiencia adquirida en otras marcas antes de incorporarse a SYN, dice la casa. Trabaja estrechamente con Leo Reyes, actual propietario de De Los Reyes Cigars, en la selección de los tabacos.

En septiembre de 2026, el catálogo cuenta con dos líneas. The Original SYN se elabora en dos versiones de capa, una en Habano HVA añejado cinco años, la otra en Corojo Maduro añejado cinco años, sobre capote dominicana y tripa de Corojo cubano cultivado en República Dominicana, en Petit Robusto y en Salomon. The Seven Syns reúne siete ligas bautizadas con los pecados capitales — GULA, IRA, ACEDIA, AVARITIA, LUXURIA, SUPERBIA, INVIDIA —, en tabaco añejado cinco años, mayoritariamente dominicano, dice la casa.

SYN se comercializa a través de estructuras propias: SYN Cigars, Inc. (Miami), SYN Europe GmbH (Alemania), SYN Asia, Ltd. (Vietnam) y Olmaq Trading NV para el Caribe, con representantes en Israel, África e India.',
        '[{"name":"The Original SYN","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"En dos versiones de capa — Habano HVA o Corojo Maduro, añejadas cinco años —, sobre tripa de Corojo cubano cultivado en República Dominicana, en Petit Robusto y en Salomon, dice la casa."},{"name":"The Seven Syns","color":"#6B4226","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Siete ligas bautizadas con los pecados capitales — GULA (Habano 2000), IRA (San Andres Maduro), ACEDIA (Habano 2000), AVARITIA (Corojo Habano de Ecuador), LUXURIA (Habano 2000), SUPERBIA (Connecticut de Ecuador), INVIDIA (San Andres Maduro) —, tabaco añejado cinco años, dice la casa."}]',
        'Joseph Casimir gründete Tabacalera SYN in Tamboril, in der Provinz Santiago, Dominikanische Republik, so synbrands.com. Seine Leidenschaft für Zigarren geht auf das Jahr 1990 zurück, seine erste Studienwoche; er gründete das Haus drei Jahrzehnte später, nach verschiedenen geschäftlichen Unternehmungen; das Haus datiert diese Gründung nicht.

Juan Rodriguez leitet die Fabrik als Blendmeister, mit mehr als fünfunddreißig Jahren Erfahrung, die er bei anderen Marken sammelte, bevor er zu SYN kam, so das Haus. Er arbeitet bei der Tabakauswahl eng mit Leo Reyes zusammen, dem heutigen Eigentümer von De Los Reyes Cigars.

Im September 2026 umfasst das Sortiment zwei Linien. The Original SYN wird in zwei Deckblattversionen gerollt, eine in fünf Jahre gereiftem Habano HVA, die andere in fünf Jahre gereiftem Corojo Maduro, über dominikanischem Umblatt und einer Einlage aus kubanischstämmigem, in der Dominikanischen Republik angebautem Corojo, in Petit Robusto und Salomon. The Seven Syns vereint sieben nach den Todsünden benannte Mischungen — GULA, IRA, ACEDIA, AVARITIA, LUXURIA, SUPERBIA, INVIDIA — aus fünf Jahre gereiftem, überwiegend dominikanischem Tabak, so das Haus.

SYN wird über eigene Strukturen vertrieben: SYN Cigars, Inc. (Miami), SYN Europe GmbH (Deutschland), SYN Asia, Ltd. (Vietnam) und Olmaq Trading NV für die Karibik, mit Vertretern in Israel, Afrika und Indien.',
        '[{"name":"The Original SYN","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"In zwei Deckblattversionen — Habano HVA oder Corojo Maduro, beide fünf Jahre gereift — über einer Einlage aus kubanischstämmigem, in der Dominikanischen Republik angebautem Corojo, in Petit Robusto und Salomon, so das Haus."},{"name":"The Seven Syns","color":"#6B4226","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Sieben nach den Todsünden benannte Mischungen — GULA (Habano 2000), IRA (San Andres Maduro), ACEDIA (Habano 2000), AVARITIA (Corojo Habano aus Ecuador), LUXURIA (Habano 2000), SUPERBIA (Connecticut aus Ecuador), INVIDIA (San Andres Maduro) — aus fünf Jahre gereiftem Tabak, so das Haus."}]',
        '据synbrands.com介绍，Joseph Casimir在多米尼加共和国圣地亚哥省坦博里尔创立了Tabacalera SYN。他对雪茄的热情始于1990年，即他上大学的头一周；三十年后，历经多次商业尝试，他才创立了这家公司；该厂并未标明这一创立年份。

据该厂介绍，Juan Rodriguez以首席调配师身份执掌工厂，拥有三十五年以上经验，这些经验是他加入SYN之前在其他品牌积累的。他与De Los Reyes Cigars现任所有者Leo Reyes密切合作，共同挑选烟叶。

截至2026年9月，产品目录共有两个系列。The Original SYN以两种茄衣版本卷制而成，一种为陈化五年的Habano HVA，另一种为陈化五年的Corojo Maduro，茄套为多米尼加烟叶，茄芯采用在多米尼加共和国种植的古巴品种Corojo，规格为Petit Robusto和Salomon。The Seven Syns汇集七款以七宗罪命名的配方——GULA、IRA、ACEDIA、AVARITIA、LUXURIA、SUPERBIA、INVIDIA——采用陈化五年、以多米尼加烟叶为主的烟草，据该厂介绍。

SYN通过自有机构销售：SYN Cigars，Inc.（迈阿密）、SYN Europe GmbH（德国）、SYN Asia，Ltd.（越南）以及负责加勒比地区的Olmaq Trading NV，并在以色列、非洲和印度设有代表。',
        '[{"name":"The Original SYN","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"有两种茄衣版本——陈化五年的Habano HVA或陈化五年的Corojo Maduro——茄芯为在多米尼加共和国种植的古巴品种Corojo，规格为Petit Robusto和Salomon，据该厂介绍。"},{"name":"The Seven Syns","color":"#6B4226","force":null,"wrapper":"未公开","vitolas":[],"story":"七款以七宗罪命名的配方——GULA（Habano 2000）、IRA（San Andres Maduro）、ACEDIA（Habano 2000）、AVARITIA（产自厄瓜多尔的Corojo Habano）、LUXURIA（Habano 2000）、SUPERBIA（产自厄瓜多尔的Connecticut）、INVIDIA（San Andres Maduro）——采用陈化五年的烟草，据该厂介绍。"}]',
        'يقول synbrands.com إن Joseph Casimir أسس Tabacalera SYN في تامبوريل، بمقاطعة سانتياغو، في الجمهورية الدومينيكية. ويعود شغفه بالسيجار إلى سنة 1990، أي أسبوعه الجامعي الأول؛ وأسس الدار بعد ذلك بثلاثة عقود، عقب مغامرات تجارية متنوعة؛ ولا تحدد الدار تاريخ هذا التأسيس.

يقول الدار إن Juan Rodriguez يدير المصنع بصفته كبير خبراء المزج، وله أكثر من خمسة وثلاثين عامًا من الخبرة اكتسبها لدى علامات أخرى قبل انضمامه إلى SYN. ويعمل عن كثب مع Leo Reyes، المالك الحالي لـDe Los Reyes Cigars، في اختيار التبوغ.

حتى سبتمبر 2026، يضم الكتالوج خطين. يُلف The Original SYN بنسختين من الغلاف، إحداهما من Habano HVA معتّق خمس سنوات، والأخرى من Corojo Maduro معتّق خمس سنوات، فوق رباط دومينيكي وحشوة من Corojo كوبي الأصل مزروع في الجمهورية الدومينيكية، بمقاسي Petit Robusto وSalomon. ويجمع The Seven Syns سبعة مزائج تحمل أسماء الخطايا السبع — GULA وIRA وACEDIA وAVARITIA وLUXURIA وSUPERBIA وINVIDIA — من تبغ معتّق خمس سنوات، معظمه دومينيكي، وفق الدار.

تُباع SYN عبر كيانات خاصة بها: SYN Cigars, Inc. (ميامي)، وSYN Europe GmbH (ألمانيا)، وSYN Asia, Ltd. (فيتنام)، وOlmaq Trading NV لمنطقة الكاريبي، مع ممثلين في إسرائيل وأفريقيا والهند.',
        '[{"name":"The Original SYN","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"بنسختين من الغلاف — Habano HVA أو Corojo Maduro، معتّقتين خمس سنوات — فوق حشوة من Corojo كوبي الأصل مزروع في الجمهورية الدومينيكية، بمقاسي Petit Robusto وSalomon، وفق الدار."},{"name":"The Seven Syns","color":"#6B4226","force":null,"wrapper":"غير معلن","vitolas":[],"story":"سبعة مزائج تحمل أسماء الخطايا السبع — GULA (Habano 2000)، وIRA (San Andres Maduro)، وACEDIA (Habano 2000)، وAVARITIA (Corojo Habano من الإكوادور)، وLUXURIA (Habano 2000)، وSUPERBIA (Connecticut من الإكوادور)، وINVIDIA (San Andres Maduro) — من تبغ معتّق خمس سنوات، وفق الدار."}]')
