-- ── Valentino Siesto ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Valentino Siesto',
        'dominican',
        '2014 — Valentino Siesto, Tamboril',
        'Tabacalera El Hoyito, Tamboril — usine propre depuis 2014, dit la maison',
        'valentinosiestocigars.com, page d''accueil (s. d. : dit la maison, Valentino Siesto a commencé sa fabrique à Tamboril en 2014, une production couvrant de nombreuses vitolas depuis 2019, équipe dirigeante Gianluca Berti (PDG) et Julio Moltó (président)) ; cigar-coop.com « Valentino Siesto Cigars to Debut PCA Exclusive at 2025 PCA Trade Show » (2025-03 : établit une production à la Tabacalera El Hoyito, Tamboril, depuis 2014, et une première exclusivité PCA, un Robusto sous cape Connecticut, prévue pour avril 2025) ; cigar-coop.com « Valentino Siesto Cigars to Unveil Black Series at InterTabac 2025 » (2025-09 : établit la ligne Black Series, en Nero Black — cape Connecticut ou Sun Grown d''Équateur, tripe dominicaine, en Toro et en Robusto — et Yellow Black — tripe entièrement dominicaine, en 46 x 6 —, roulée à la fabrique dominicaine de la maison) ; tributarycigars.com « About Us » (s. d. : établit l''histoire de la Tabacalera El Hoyito, à Tamboril, depuis le travail artisanal de Marcelo Gómez au milieu des années 1960, un projet familial établi en 1978, puis la formalisation de « Tabacalera El Hoyito S.R.L. » en 2011) ; klarocigars.com « Valentino Siesto Premium Series Maduro Review » (s. d. : détaillant américain, établit pour la ligne Premium Series une cape San Andrés Maduro du Mexique, une sous-cape dominicaine, une tripe Criollo ''98, un corps plein, en Robusto 5 x 52 ; une version numérotée « 67 » y est réservée au marché américain) ; humolatino.com « Valentino Siesto. Llegó buscando oro… encontró tabaco » (en espagnol ; s. d. : établit que Valentino Siesto, entrepreneur italien né en 1967, arrivé en République dominicaine en 1997, s''associe en 2005 à une fabrique de tabac de Santiago de los Caballeros, développe ses assemblages quatre ans durant puis lance commercialement sa marque en 2018 ; Juan Gomez, son maître ligador, y apporte quarante ans d''expérience)',
        NULL,
        'Valentino Siesto, entrepreneur italien né en 1967, arrive en République dominicaine en 1997 pour y ouvrir une bijouterie et découvre le cigare, dit humolatino.com, qui situe en 2005 un premier partenariat avec une fabrique de Santiago de los Caballeros et en 2018 le lancement commercial de sa marque. La maison, elle, date de 2014 le début de sa propre fabrique à Tamboril et de 2019 une production couvrant de nombreuses vitolas, dit valentinosiestocigars.com ; Cigar Coop confirme une production à la Tabacalera El Hoyito depuis 2014. Juan Gomez, associé à l''aventure, est le maître ligador de la maison, fort de quarante ans d''expérience, dit humolatino.com.

La Tabacalera El Hoyito, à Tamboril, remonte au travail artisanal de Marcelo Gómez dès le milieu des années 1960 ; ses enfants y ont établi un projet familial en 1978, formalisé en société — Tabacalera El Hoyito S.R.L. — en 2011, dit Tributary Cigars.

En septembre 2026, le catalogue compte deux lignes régulières et une exclusivité. La Premium Series se roule sous cape San Andrés Maduro du Mexique, sur sous-cape dominicaine et tripe Criollo ''98, pour un corps plein, en Robusto ; une version numérotée « 67 » en est réservée au marché américain, dit klarocigars.com. La Black Series se décline en Nero Black (cape Connecticut ou Sun Grown d''Équateur, tripe dominicaine, en Toro et en Robusto) et en Yellow Black (tripe entièrement dominicaine, en 46 x 6), dit Cigar Coop. La maison a présenté en avril 2025 sa première exclusivité pour le salon professionnel PCA, un Robusto sous cape Connecticut.',
        '[{"name":"Premium Series","color":"#6B4226","force":"Full","wrapper":"San Andrés Maduro (Mexique)","vitolas":[],"story":"Sous-cape dominicaine et tripe Criollo ''98, en Robusto ; une version numérotée « 67 » réservée au marché américain, dit klarocigars.com."},{"name":"Black Series","color":"#6B4226","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"En Nero Black (cape Connecticut ou Sun Grown d''Équateur, tripe dominicaine, en Toro et en Robusto) et Yellow Black (tripe entièrement dominicaine, en 46 x 6), dit Cigar Coop."},{"name":"PCA Exclusive","color":"#C9A96E","force":null,"wrapper":"Connecticut","vitolas":[],"story":"Premier tirage réservé au salon professionnel PCA, un Robusto sous cape Connecticut, présenté en avril 2025, dit Cigar Coop."}]',
        'Valentino Siesto, an Italian entrepreneur born in 1967, arrived in the Dominican Republic in 1997 to open a jewellery shop and discovered cigars, says humolatino.com, which places a first partnership with a factory in Santiago de los Caballeros in 2005 and the commercial launch of his brand in 2018. The house, for its part, dates the start of its own factory in Tamboril to 2014 and production covering numerous vitolas to 2019, says valentinosiestocigars.com; Cigar Coop confirms production at the Tabacalera El Hoyito since 2014. Juan Gomez, involved in the venture, is the house''s master blender, with forty years of experience, says humolatino.com.

Tabacalera El Hoyito, in Tamboril, traces back to the artisanal work of Marcelo Gómez from the mid-1960s; his children set up a family venture there in 1978, formalised as a company — Tabacalera El Hoyito S.R.L. — in 2011, says Tributary Cigars.

As of September 2026, the catalogue holds two regular lines and one exclusive. The Premium Series is rolled under a Mexican San Andrés Maduro wrapper, over a Dominican binder and Criollo ''98 filler, for a full body, in Robusto; a version numbered 67 is reserved for the American market, says klarocigars.com. The Black Series comes in Nero Black (Connecticut or Ecuadorian Sun Grown wrapper, Dominican filler, in Toro and Robusto) and Yellow Black (entirely Dominican filler, in 46 x 6), says Cigar Coop. In April 2025 the house presented its first exclusive for the PCA trade show, a Robusto under a Connecticut wrapper.',
        '[{"name":"Premium Series","color":"#6B4226","force":"Full","wrapper":"San Andrés Maduro (Mexico)","vitolas":[],"story":"Dominican binder and Criollo ''98 filler, in Robusto; a version numbered 67 reserved for the American market, says klarocigars.com."},{"name":"Black Series","color":"#6B4226","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"In Nero Black (Connecticut or Ecuadorian Sun Grown wrapper, Dominican filler, in Toro and Robusto) and Yellow Black (entirely Dominican filler, in 46 x 6), says Cigar Coop."},{"name":"PCA Exclusive","color":"#C9A96E","force":null,"wrapper":"Connecticut","vitolas":[],"story":"First run reserved for the PCA trade show, a Robusto under a Connecticut wrapper, presented in April 2025, says Cigar Coop."}]',
        'Valentino Siesto, empresario italiano nacido en 1967, llega a República Dominicana en 1997 para abrir una joyería y descubre el cigarro, dice humolatino.com, que sitúa en 2005 una primera asociación con una fábrica de Santiago de los Caballeros y en 2018 el lanzamiento comercial de su marca. La casa, por su parte, fecha en 2014 el inicio de su propia fábrica en Tamboril y en 2019 una producción que abarca numerosas vitolas, dice valentinosiestocigars.com; Cigar Coop confirma una producción en la Tabacalera El Hoyito desde 2014. Juan Gomez, asociado a la aventura, es el maestro ligador de la casa, con cuarenta años de experiencia, dice humolatino.com.

La Tabacalera El Hoyito, en Tamboril, se remonta al trabajo artesanal de Marcelo Gómez desde mediados de los años sesenta; sus hijos establecieron allí un proyecto familiar en 1978, formalizado como sociedad — Tabacalera El Hoyito S.R.L. — en 2011, dice Tributary Cigars.

En septiembre de 2026, el catálogo cuenta con dos líneas regulares y una exclusiva. La Premium Series se elabora con capa San Andrés Maduro de México, sobre capote dominicana y tripa Criollo ''98, para un cuerpo pleno, en Robusto; una versión numerada 67 está reservada al mercado estadounidense, dice klarocigars.com. La Black Series se presenta en Nero Black (capa Connecticut o Sun Grown de Ecuador, tripa dominicana, en Toro y en Robusto) y en Yellow Black (tripa enteramente dominicana, en 46 x 6), dice Cigar Coop. La casa presentó en abril de 2025 su primera exclusiva para la feria profesional PCA, un Robusto con capa Connecticut.',
        '[{"name":"Premium Series","color":"#6B4226","force":"Full","wrapper":"San Andrés Maduro (México)","vitolas":[],"story":"Capote dominicana y tripa Criollo ''98, en Robusto; una versión numerada 67 reservada al mercado estadounidense, dice klarocigars.com."},{"name":"Black Series","color":"#6B4226","force":null,"wrapper":"No divulgada","vitolas":[],"story":"En Nero Black (capa Connecticut o Sun Grown de Ecuador, tripa dominicana, en Toro y en Robusto) y Yellow Black (tripa enteramente dominicana, en 46 x 6), dice Cigar Coop."},{"name":"PCA Exclusive","color":"#C9A96E","force":null,"wrapper":"Connecticut","vitolas":[],"story":"Primera tirada reservada a la feria profesional PCA, un Robusto con capa Connecticut, presentado en abril de 2025, dice Cigar Coop."}]',
        'Valentino Siesto, ein 1967 geborener italienischer Unternehmer, kommt 1997 in die Dominikanische Republik, um dort ein Schmuckgeschäft zu eröffnen, und entdeckt die Zigarre, so humolatino.com, das eine erste Partnerschaft mit einer Fabrik in Santiago de los Caballeros auf 2005 datiert und die kommerzielle Einführung seiner Marke auf 2018. Das Haus selbst datiert den Beginn seiner eigenen Fabrik in Tamboril auf 2014 und eine Produktion mit zahlreichen Vitolas auf 2019, so valentinosiestocigars.com; Cigar Coop bestätigt eine Produktion in der Tabacalera El Hoyito seit 2014. Juan Gomez, der an dem Unterfangen beteiligt war, ist der Ligador-Meister des Hauses, mit vierzig Jahren Erfahrung, so humolatino.com.

Die Tabacalera El Hoyito, in Tamboril, geht auf die handwerkliche Arbeit von Marcelo Gómez seit Mitte der 1960er-Jahre zurück; seine Kinder gründeten dort 1978 ein Familienunternehmen, das 2011 als Gesellschaft — Tabacalera El Hoyito S.R.L. — formalisiert wurde, so Tributary Cigars.

Im September 2026 umfasst das Sortiment zwei reguläre Linien und eine Exklusivedition. Die Premium Series wird unter einem mexikanischen San-Andrés-Maduro-Deckblatt gerollt, über dominikanischem Umblatt und Criollo-''98-Einlage, für einen vollen Körper, in Robusto; eine mit 67 nummerierte Version ist dem US-amerikanischen Markt vorbehalten, so klarocigars.com. Die Black Series gibt es als Nero Black (Deckblatt Connecticut oder Sun Grown aus Ecuador, dominikanische Einlage, in Toro und Robusto) und als Yellow Black (vollständig dominikanische Einlage, in 46 x 6), so Cigar Coop. Das Haus stellte im April 2025 seine erste Exklusivedition für die PCA-Fachmesse vor, eine Robusto unter Connecticut-Deckblatt.',
        '[{"name":"Premium Series","color":"#6B4226","force":"Full","wrapper":"San Andrés Maduro (Mexiko)","vitolas":[],"story":"Dominikanisches Umblatt und Criollo-''98-Einlage, in Robusto; eine mit 67 nummerierte Version dem US-amerikanischen Markt vorbehalten, so klarocigars.com."},{"name":"Black Series","color":"#6B4226","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Als Nero Black (Deckblatt Connecticut oder Sun Grown aus Ecuador, dominikanische Einlage, in Toro und Robusto) und als Yellow Black (vollständig dominikanische Einlage, in 46 x 6), so Cigar Coop."},{"name":"PCA Exclusive","color":"#C9A96E","force":null,"wrapper":"Connecticut","vitolas":[],"story":"Erste, der PCA-Fachmesse vorbehaltene Auflage, eine Robusto unter Connecticut-Deckblatt, vorgestellt im April 2025, so Cigar Coop."}]',
        '据humolatino.com介绍，1967年出生的意大利企业家Valentino Siesto于1997年抵达多米尼加共和国，本欲开设珠宝店，却由此发现了雪茄；该网站将2005年与圣地亚哥-德洛斯卡瓦列罗斯一家工厂的首次合作、以及2018年其品牌的正式商业推出作为时间节点。据valentinosiestocigars.com介绍，该厂则将2014年定为其在坦博里尔自有工厂起步之年，2019年定为涵盖多种规格生产之年；Cigar Coop证实Tabacalera El Hoyito自2014年起即已生产。据humolatino.com介绍，参与此事业的Juan Gomez是该厂的首席ligador，拥有四十年经验。

据Tributary Cigars介绍，坦博里尔的Tabacalera El Hoyito可追溯至1960年代中期Marcelo Gómez的手工制作；其子女于1978年在此创办家族事业，并于2011年正式注册为公司——Tabacalera El Hoyito S.R.L.。

截至2026年9月，产品目录共有两条常规系列与一款限定版。Premium Series采用墨西哥产San Andrés Maduro茄衣，茄套为多米尼加烟叶，茄芯为Criollo ''98，力度浓郁，规格为Robusto；据klarocigars.com介绍，编号为67的版本专供美国市场。据Cigar Coop介绍，Black Series分为Nero Black（茄衣为Connecticut或厄瓜多尔产Sun Grown，茄芯为多米尼加烟叶，规格有Toro和Robusto）与Yellow Black（茄芯全部为多米尼加烟叶，规格为46 x 6）两款。该厂于2025年4月推出首款专供PCA贸易展的限定版，为一款采用Connecticut茄衣的Robusto。',
        '[{"name":"Premium Series","color":"#6B4226","force":"Full","wrapper":"San Andrés Maduro（墨西哥）","vitolas":[],"story":"茄套为多米尼加烟叶，茄芯为Criollo ''98，规格为Robusto；编号为67的版本专供美国市场，据klarocigars.com介绍。"},{"name":"Black Series","color":"#6B4226","force":null,"wrapper":"未公开","vitolas":[],"story":"分为Nero Black（茄衣为Connecticut或厄瓜多尔产Sun Grown，茄芯为多米尼加烟叶，规格有Toro和Robusto）与Yellow Black（茄芯全部为多米尼加烟叶，规格为46 x 6），据Cigar Coop介绍。"},{"name":"PCA Exclusive","color":"#C9A96E","force":null,"wrapper":"Connecticut","vitolas":[],"story":"首批专供PCA贸易展，为采用Connecticut茄衣的Robusto，于2025年4月推出，据Cigar Coop介绍。"}]',
        'يقول humolatino.com إن Valentino Siesto، رجل أعمال إيطالي وُلد سنة 1967، وصل إلى الجمهورية الدومينيكية سنة 1997 لفتح متجر مجوهرات، فاكتشف هناك عالم السيجار؛ ويضع الموقع سنة 2005 لأول شراكة مع مصنع في سانتياغو دي لوس كاباييروس، وسنة 2018 للإطلاق التجاري لعلامته. أما الدار فتؤرّخ بداية مصنعها الخاص في تامبوريل بسنة 2014، وإنتاجًا يشمل مقاسات عديدة بسنة 2019، وفق valentinosiestocigars.com؛ وتؤكد Cigar Coop إنتاجًا في Tabacalera El Hoyito منذ 2014. ويقول humolatino.com إن Juan Gomez، الذي شارك في هذه المغامرة، هو ligador الدار الرئيسي، وله أربعون عامًا من الخبرة.

تقول Tributary Cigars إن Tabacalera El Hoyito، في تامبوريل، تعود جذورها إلى العمل اليدوي لـMarcelo Gómez منذ منتصف الستينيات؛ إذ أسس أبناؤه فيها مشروعًا عائليًا سنة 1978، جرى إضفاء الطابع الرسمي عليه كشركة — Tabacalera El Hoyito S.R.L. — سنة 2011.

حتى سبتمبر 2026، يضم الكتالوج خطين منتظمين وإصدارًا حصريًا واحدًا. تُلف Premium Series تحت غلاف San Andrés Maduro من المكسيك، فوق رباط دومينيكي وحشوة Criollo ''98، بقوة كاملة، بمقاس Robusto؛ ووفق klarocigars.com، فإن نسخة مرقّمة 67 مخصّصة للسوق الأمريكية. وتقول Cigar Coop إن Black Series تُقدَّم في نسختين: Nero Black (غلاف Connecticut أو Sun Grown من الإكوادور، حشوة دومينيكية، بمقاسي Toro وRobusto) وYellow Black (حشوة دومينيكية بالكامل، بمقاس 46 x 6). وقدّمت الدار في أبريل 2025 أول إصدار حصري لها لمعرض PCA التجاري، وهو سيجار Robusto بغلاف Connecticut.',
        '[{"name":"Premium Series","color":"#6B4226","force":"Full","wrapper":"San Andrés Maduro (المكسيك)","vitolas":[],"story":"رباط دومينيكي وحشوة Criollo ''98، بمقاس Robusto؛ نسخة مرقّمة 67 مخصّصة للسوق الأمريكية، وفق klarocigars.com."},{"name":"Black Series","color":"#6B4226","force":null,"wrapper":"غير معلن","vitolas":[],"story":"في نسختين: Nero Black (غلاف Connecticut أو Sun Grown من الإكوادور، حشوة دومينيكية، بمقاسي Toro وRobusto) وYellow Black (حشوة دومينيكية بالكامل، بمقاس 46 x 6)، وفق Cigar Coop."},{"name":"PCA Exclusive","color":"#C9A96E","force":null,"wrapper":"Connecticut","vitolas":[],"story":"أول إصدار حصري لمعرض PCA التجاري، سيجار Robusto بغلاف Connecticut، قُدِّم في أبريل 2025، وفق Cigar Coop."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Xhaxhi Bobi ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Xhaxhi Bobi',
        'dominican',
        'Non précisée — Bob de Goede, Rép. dominicaine',
        'Chez Kelner Boutique Factory (ligne principale) ; d''autres lignes ailleurs, dont la Tabacalera El Artista, République dominicaine',
        'cigarspartan.com « Xhaxhi Bobi » (page de marque, s. d. : établit que Bob de Goede est néerlandais, que son surnom « Xhaxhi » — oncle, en albanais — lui vient d''un travail dans une mine en Albanie, et qu''il a fabriqué des boîtes à cigares en République dominicaine pendant plus de vingt ans avant d''y lancer sa propre marque) ; racccigars.com « Xhaxhi Bobi » (page de marque, détaillant japonais, s. d. : établit le rôle de Hendrik Kelner Jr. et de la Kelner Boutique Factory, mentionne la Tabacalera El Artista, et liste les lignes El Licenciado, El Ingeniero et Mi Hermano) ; cigarworld.de « Xhaxhi Bobi Mi Hermano » (s. d. : établit pour Mi Hermano une cape, une sous-cape et une tripe entièrement dominicaines, un format Petit Corona et la Kelner Boutique Factory comme fabrique ; liste aussi Baba Jan, El Ingeniero et El Licenciado au catalogue) ; sirlouiscigars.com « Xhaxhi Bobi » (page de collection, s. d. : liste les lignes du catalogue, dont Baba Jan, Black, El Ingeniero, Grey, Mi Hermano, Red, Sunset et 7 Vikings) ; sirlouiscigars.com « Xhaxhi Bobi Sunset Robusto » (s. d. : établit pour la ligne Sunset une cape Connecticut d''Équateur, une sous-cape Habano dominicaine, une tripe Habano/Piloto/San Vicente dominicaine, un corps mild-medium, en Robusto 5 x 50) ; smallbatchcigar.com « Xhaxhi Bobi » (consulté le 24 septembre 2026 : Bobi de Goede, fabricant de boîtes néerlandais ; assemblages à la Kelner Boutique Factory et à la Tabacalera El Artista ; ligne Grey chez Torres & Garcia, à Santiago, par Junior Torres) ; halfwheel.com « Xhaxhi Bobi Announces New U.S. Distribution » (Bob de Goede a demandé à Hendrik Kelner Jr. de rouler son cigare ; assemblages à la Kelner Boutique Factory et à la Tabacalera El Artista)',
        NULL,
        'Bob de Goede, néerlandais, a fabriqué des boîtes à cigares en République dominicaine pendant plus de vingt ans avant d''y lancer sa propre marque ; son surnom, « Xhaxhi » (oncle, en albanais), lui vient d''un travail dans une mine en Albanie, dit cigarspartan.com. Aucune des fabriques qui roulent ses lignes ne lui appartient.

Les premiers assemblages, dont Mi Hermano, sont nés à la Kelner Boutique Factory, dirigée par Hendrik Kelner Jr., dit racccigars.com ; Mi Hermano s''y roule en cape, sous-cape et tripe entièrement dominicaines, en Petit Corona, pour un corps medium plus, dit cigarworld.de. D''autres lignes se roulent ailleurs, notamment à la Tabacalera El Artista, dit racccigars.com. La ligne Grey, elle, est roulée par Junior Torres à la fabrique Torres & Garcia, à Santiago, dit Small Batch Cigar. La ligne Sunset porte une cape Connecticut d''Équateur sur une sous-cape et une tripe Habano dominicaines, pour un corps mild-medium, en Robusto, dit Sir Louis Cigars.

En septembre 2026, le catalogue compte aussi Baba Jan, Black, El Ingeniero, El Licenciado, Red et 7 Vikings, disent Cigarworld.de et Sir Louis Cigars.',
        '[{"name":"Mi Hermano","color":"#A0522D","force":"Medium-Full","wrapper":"République dominicaine","vitolas":[],"story":"Cape, sous-cape et tripe entièrement dominicaines, en Petit Corona, roulée à la Kelner Boutique Factory, dit cigarworld.de."},{"name":"Grey","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Roulée par Junior Torres à la fabrique Torres & Garcia, à Santiago, dit Small Batch Cigar."},{"name":"Sunset","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Équateur)","vitolas":[],"story":"Sous-cape et tripe Habano dominicaines, en Robusto, dit sirlouiscigars.com."},{"name":"Baba Jan","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne du catalogue, dit Cigarworld.de."},{"name":"Black","color":"#4A3728","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne du catalogue, dit Sir Louis Cigars."},{"name":"El Ingeniero","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne du catalogue, dit Cigarworld.de."},{"name":"El Licenciado","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne du catalogue, dit Cigarworld.de."},{"name":"Red","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne du catalogue, dit Sir Louis Cigars."},{"name":"7 Vikings","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne du catalogue, dit Sir Louis Cigars."}]',
        'Bob de Goede, Dutch, made cigar boxes in the Dominican Republic for more than twenty years before launching his own brand there; his nickname, Xhaxhi (uncle, in Albanian), comes from a job in a mine in Albania, says cigarspartan.com. None of the factories that roll his lines belongs to him.

The first blends, including Mi Hermano, were born at the Kelner Boutique Factory, run by Hendrik Kelner Jr., says racccigars.com; Mi Hermano is rolled there with an entirely Dominican wrapper, binder and filler, in Petit Corona, for a medium-plus body, says cigarworld.de. Other lines are rolled elsewhere, notably at the Tabacalera El Artista, says racccigars.com. The Grey line, for its part, is rolled by Junior Torres at the Torres & Garcia factory, in Santiago, says Small Batch Cigar. The Sunset line carries an Ecuadorian Connecticut wrapper over a Dominican Habano binder and filler, for a mild-medium body, in Robusto, says Sir Louis Cigars.

As of September 2026, the catalogue also includes Baba Jan, Black, El Ingeniero, El Licenciado, Red and 7 Vikings, say Cigarworld.de and Sir Louis Cigars.',
        '[{"name":"Mi Hermano","color":"#A0522D","force":"Medium-Full","wrapper":"Dominican Republic","vitolas":[],"story":"Entirely Dominican wrapper, binder and filler, in Petit Corona, rolled at the Kelner Boutique Factory, says cigarworld.de."},{"name":"Grey","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Rolled by Junior Torres at the Torres & Garcia factory, in Santiago, says Small Batch Cigar."},{"name":"Sunset","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Dominican Habano binder and filler, in Robusto, says sirlouiscigars.com."},{"name":"Baba Jan","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"A line in the catalogue, says Cigarworld.de."},{"name":"Black","color":"#4A3728","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"A line in the catalogue, says Sir Louis Cigars."},{"name":"El Ingeniero","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"A line in the catalogue, says Cigarworld.de."},{"name":"El Licenciado","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"A line in the catalogue, says Cigarworld.de."},{"name":"Red","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"A line in the catalogue, says Sir Louis Cigars."},{"name":"7 Vikings","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"A line in the catalogue, says Sir Louis Cigars."}]',
        'Bob de Goede, neerlandés, fabricó cajas de puros en República Dominicana durante más de veinte años antes de lanzar allí su propia marca; su apodo, Xhaxhi (tío, en albanés), le viene de un trabajo en una mina en Albania, dice cigarspartan.com. Ninguna de las fábricas que ruedan sus líneas le pertenece.

Las primeras ligas, entre ellas Mi Hermano, nacieron en la Kelner Boutique Factory, dirigida por Hendrik Kelner Jr., dice racccigars.com; Mi Hermano se elabora allí con capa, capote y tripa enteramente dominicanas, en Petit Corona, para un cuerpo medio-pleno, dice cigarworld.de. Otras líneas se elaboran en otros lugares, en particular en la Tabacalera El Artista, dice racccigars.com. La línea Grey, por su parte, la elabora Junior Torres en la fábrica Torres & Garcia, en Santiago, dice Small Batch Cigar. La línea Sunset lleva una capa Connecticut de Ecuador sobre capote y tripa Habano dominicanas, para un cuerpo suave-medio, en Robusto, dice Sir Louis Cigars.

En septiembre de 2026, el catálogo también incluye Baba Jan, Black, El Ingeniero, El Licenciado, Red y 7 Vikings, dicen Cigarworld.de y Sir Louis Cigars.',
        '[{"name":"Mi Hermano","color":"#A0522D","force":"Medium-Full","wrapper":"República Dominicana","vitolas":[],"story":"Capa, capote y tripa enteramente dominicanas, en Petit Corona, elaborada en la Kelner Boutique Factory, dice cigarworld.de."},{"name":"Grey","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Elaborada por Junior Torres en la fábrica Torres & Garcia, en Santiago, dice Small Batch Cigar."},{"name":"Sunset","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Capote y tripa Habano dominicanas, en Robusto, dice sirlouiscigars.com."},{"name":"Baba Jan","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea del catálogo, dice Cigarworld.de."},{"name":"Black","color":"#4A3728","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea del catálogo, dice Sir Louis Cigars."},{"name":"El Ingeniero","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea del catálogo, dice Cigarworld.de."},{"name":"El Licenciado","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea del catálogo, dice Cigarworld.de."},{"name":"Red","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea del catálogo, dice Sir Louis Cigars."},{"name":"7 Vikings","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea del catálogo, dice Sir Louis Cigars."}]',
        'Bob de Goede, Niederländer, stellte mehr als zwanzig Jahre lang Zigarrenkisten in der Dominikanischen Republik her, bevor er dort seine eigene Marke lancierte; sein Spitzname Xhaxhi (Onkel, auf Albanisch) stammt aus einer Zeit als Bergarbeiter in Albanien, so cigarspartan.com. Keine der Fabriken, die seine Linien rollen, gehört ihm.

Die ersten Mischungen, darunter Mi Hermano, entstanden in der Kelner Boutique Factory unter der Leitung von Hendrik Kelner Jr., so racccigars.com; Mi Hermano wird dort mit vollständig dominikanischem Deckblatt, Umblatt und Einlage gerollt, in Petit Corona, für einen mittelstarken Körper, so cigarworld.de. Andere Linien werden andernorts gerollt, insbesondere in der Tabacalera El Artista, so racccigars.com. Die Linie Grey wiederum wird von Junior Torres in der Fabrik Torres & Garcia, in Santiago, gerollt, so Small Batch Cigar. Die Linie Sunset trägt ein ecuadorianisches Connecticut-Deckblatt über dominikanischem Habano-Umblatt und -Einlage, für einen mild-mittleren Körper, in Robusto, so Sir Louis Cigars.

Im September 2026 umfasst das Sortiment außerdem Baba Jan, Black, El Ingeniero, El Licenciado, Red und 7 Vikings, so Cigarworld.de und Sir Louis Cigars.',
        '[{"name":"Mi Hermano","color":"#A0522D","force":"Medium-Full","wrapper":"Dominikanische Republik","vitolas":[],"story":"Vollständig dominikanisches Deckblatt, Umblatt und Einlage, in Petit Corona, gerollt in der Kelner Boutique Factory, so cigarworld.de."},{"name":"Grey","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Gerollt von Junior Torres in der Fabrik Torres & Garcia, in Santiago, so Small Batch Cigar."},{"name":"Sunset","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Dominikanisches Habano-Umblatt und -Einlage, in Robusto, so sirlouiscigars.com."},{"name":"Baba Jan","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie im Sortiment, so Cigarworld.de."},{"name":"Black","color":"#4A3728","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie im Sortiment, so Sir Louis Cigars."},{"name":"El Ingeniero","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie im Sortiment, so Cigarworld.de."},{"name":"El Licenciado","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie im Sortiment, so Cigarworld.de."},{"name":"Red","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie im Sortiment, so Sir Louis Cigars."},{"name":"7 Vikings","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie im Sortiment, so Sir Louis Cigars."}]',
        '据cigarspartan.com介绍，荷兰人Bob de Goede在多米尼加共和国制作雪茄盒长达二十余年，之后才在当地创立了自己的品牌；他的绰号Xhaxhi（在阿尔巴尼亚语中意为叔叔）源自他曾在阿尔巴尼亚一处矿场工作的经历。为其生产系列产品的工厂没有一家属于他本人。

据racccigars.com介绍，包括Mi Hermano在内的最初几款配方诞生于由Hendrik Kelner Jr.执掌的Kelner Boutique Factory；据cigarworld.de介绍，Mi Hermano在此以全多米尼加茄衣、茄套与茄芯卷制，规格为Petit Corona，力度为中等偏浓。据racccigars.com介绍，其他系列则在别处卷制，尤其是在Tabacalera El Artista。据Small Batch Cigar介绍，Grey系列则由Junior Torres在圣地亚哥的Torres & Garcia工厂卷制。据Sir Louis Cigars介绍，Sunset系列采用厄瓜多尔产Connecticut茄衣，茄套与茄芯均为多米尼加Habano烟叶，力度为温和偏中等，规格为Robusto。

截至2026年9月，产品目录还包括Baba Jan、Black、El Ingeniero、El Licenciado、Red及7 Vikings，据Cigarworld.de与Sir Louis Cigars介绍。',
        '[{"name":"Mi Hermano","color":"#A0522D","force":"Medium-Full","wrapper":"多米尼加共和国","vitolas":[],"story":"茄衣、茄套与茄芯均为多米尼加烟叶，规格为Petit Corona，于Kelner Boutique Factory卷制，据cigarworld.de介绍。"},{"name":"Grey","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"由Junior Torres在圣地亚哥的Torres & Garcia工厂卷制，据Small Batch Cigar介绍。"},{"name":"Sunset","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut（厄瓜多尔）","vitolas":[],"story":"茄套与茄芯均为多米尼加Habano烟叶，规格为Robusto，据sirlouiscigars.com介绍。"},{"name":"Baba Jan","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"目录中的系列之一，据Cigarworld.de介绍。"},{"name":"Black","color":"#4A3728","force":null,"wrapper":"未公开","vitolas":[],"story":"目录中的系列之一，据Sir Louis Cigars介绍。"},{"name":"El Ingeniero","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"目录中的系列之一，据Cigarworld.de介绍。"},{"name":"El Licenciado","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"目录中的系列之一，据Cigarworld.de介绍。"},{"name":"Red","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"目录中的系列之一，据Sir Louis Cigars介绍。"},{"name":"7 Vikings","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"目录中的系列之一，据Sir Louis Cigars介绍。"}]',
        'يقول cigarspartan.com إن Bob de Goede، الهولندي، صنع علب سيجار في الجمهورية الدومينيكية لأكثر من عشرين عامًا قبل أن يطلق فيها علامته الخاصة؛ ولقبه Xhaxhi (وتعني العم بالألبانية) يعود إلى عمله في منجم في ألبانيا. ولا يملك أيًّا من المصانع التي تُلف خطوطه.

تقول racccigars.com إن أولى المزائج، ومنها Mi Hermano، وُلدت في Kelner Boutique Factory، التي يديرها Hendrik Kelner Jr.؛ ويقول cigarworld.de إن Mi Hermano يُلف هناك بغلاف ورباط وحشوة دومينيكية بالكامل، بمقاس Petit Corona، بقوة متوسطة إلى أشدّ قوةً. وتقول racccigars.com إن خطوطًا أخرى تُلف في أماكن أخرى، لا سيما في Tabacalera El Artista. أما خط Grey فيلفه Junior Torres في مصنع Torres & Garcia، في سانتياغو، وفق Small Batch Cigar. ويحمل خط Sunset غلاف Connecticut من الإكوادور فوق رباط وحشوة Habano دومينيكية، بقوة خفيفة إلى متوسطة، بمقاس Robusto، وفق Sir Louis Cigars.

وحتى سبتمبر 2026، يضم الكتالوج أيضًا Baba Jan وBlack وEl Ingeniero وEl Licenciado وRed و7 Vikings، وفق Cigarworld.de وSir Louis Cigars.',
        '[{"name":"Mi Hermano","color":"#A0522D","force":"Medium-Full","wrapper":"الجمهورية الدومينيكية","vitolas":[],"story":"غلاف ورباط وحشوة دومينيكية بالكامل، بمقاس Petit Corona، تُلف في Kelner Boutique Factory، وفق cigarworld.de."},{"name":"Grey","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"يلفها Junior Torres في مصنع Torres & Garcia، في سانتياغو، وفق Small Batch Cigar."},{"name":"Sunset","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (الإكوادور)","vitolas":[],"story":"رباط وحشوة Habano دومينيكية، بمقاس Robusto، وفق sirlouiscigars.com."},{"name":"Baba Jan","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط ضمن الكتالوج، وفق Cigarworld.de."},{"name":"Black","color":"#4A3728","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط ضمن الكتالوج، وفق Sir Louis Cigars."},{"name":"El Ingeniero","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط ضمن الكتالوج، وفق Cigarworld.de."},{"name":"El Licenciado","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط ضمن الكتالوج، وفق Cigarworld.de."},{"name":"Red","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط ضمن الكتالوج، وفق Sir Louis Cigars."},{"name":"7 Vikings","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"خط ضمن الكتالوج، وفق Sir Louis Cigars."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Cuba Aliados ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Cuba Aliados',
        'honduras',
        '1973 — Rolando Reyes Sr., Union City (NJ)',
        'Chez Fábrica de Puros Aladino (JRE Tobacco Co.), Danlí — édition limitée chez Tabacalera La Alianza (E.P. Carrillo), République dominicaine',
        'en.wikipedia.org « Rolando Reyes Sr. » (s. d. : établit sa naissance en 1924 à Zulueta, la confiscation de sa marque « Los Aliados » et de son usine par le gouvernement cubain en 1968, son émigration aux États-Unis en 1971, le renommage de sa production « Cuba Aliados » à Union City en 1973, l''achèvement de son installation à Danlí, au Honduras, en 1989, et sa mort le 18 mars 2012) ; cigar-coop.com « Cigar News: Oliva Cigar Company Acquires Cuba Aliados, Puros Indios and Roly Brands » (2021-08 : établit le rachat des marques Cuba Aliados, Puros Indios et Roly par Oliva Cigar Co. le 6 août 2021 auprès de Carlos Diez, petit-fils de Rolando Reyes Sr. et seul propriétaire de Reyes Family Cigars ; précise que la famille Reyes conserve sa fabrique, seules les marques changeant de mains) ; cigar-coop.com « Cigar Review: Cuba Aliados Original Blend Robusto » (2023-09 : établit pour la ligne Original Blend un puro hondurien — cape, sous-cape et tripe du Honduras —, un corps medium, cinq vitolas et la Fábrica de Puros Aladino S.A., dirigée par Julio R. Eiroa, comme fabrique) ; cigar-coop.com « Cigar Review: Cuba Aliados by Ernesto Perez-Carrillo Torpedo » (2023-08 : établit pour l''édition limitée une cape Sumatra d''Équateur, une sous-cape nicaraguayenne, une tripe nicaraguayenne et dominicaine, cinq vitolas en boîtes de 20, et la Tabacalera La Alianza, en République dominicaine, comme fabrique) ; humoytabaco.com « JRE Tobacco / Aladino » (en espagnol ; 2021-05-10 : établit l''histoire de la Fábrica de Puros Aladino, à Danlí, nommée d''après le cinéma du grand-père Eiroa dans les années 1970, et la formation de JRE Tobacco Company par Julio Eiroa et son fils Justo) ; halfwheel.com « Oliva Brings Back Cuba Aliados with Julio Eiroa, Ernesto Perez-Carrillo Jr. » (ligne régulière roulée par Julio Eiroa à la Fábrica de Puros Aladino, au Honduras ; édition limitée par Ernesto Perez-Carrillo Jr.) ; cigaraficionado.com « Cuba Aliados Original Blend Churchill » (2025-06 : la ligne Original Blend est au catalogue en juin 2025)',
        NULL,
        'Rolando Reyes Sr., né en 1924 à Zulueta, dans la province cubaine de Las Villas, voit sa marque Los Aliados et son usine confisquées par le gouvernement cubain en 1968 ; il émigre aux États-Unis en 1971, d''abord à Miami puis à Jersey City, et renomme sa production Cuba Aliados à Union City en 1973, selon Wikipédia. La famille achève son installation à Danlí, au Honduras, en 1989 ; Rolando Reyes Sr. meurt le 18 mars 2012.

Le 6 août 2021, Oliva Cigar Co. rachète les marques Cuba Aliados, Puros Indios et Roly à Carlos Diez, petit-fils de Rolando Reyes Sr. et seul propriétaire de Reyes Family Cigars ; la famille Reyes conserve sa propre fabrique, seuls les noms de marque changent de mains, dit Cigar Coop.

Depuis, la ligne régulière, Original Blend, se roule en puro hondurien — cape, sous-cape et tripe du Honduras —, pour un corps medium, en cinq vitolas, du Robusto au Churchill, à la Fábrica de Puros Aladino, dirigée par Julio R. Eiroa (JRE Tobacco Co.), à Danlí. Une édition limitée, assemblée par Ernesto Perez-Carrillo Jr., se roule à la Tabacalera La Alianza, en République dominicaine, sous cape Sumatra d''Équateur, sur sous-cape nicaraguayenne et tripe nicaraguayenne et dominicaine, également en cinq vitolas. En juin 2025, l''Original Blend est toujours au catalogue.',
        '[{"name":"Original Blend","color":"#A0522D","force":"Medium","wrapper":"Honduras (puro)","vitolas":[],"story":"Sous-cape et tripe honduriennes, en cinq vitolas, du Robusto au Churchill, roulée à la Fábrica de Puros Aladino, dit Cigar Coop."},{"name":"by Ernesto Perez-Carrillo","color":"#A0522D","force":"Medium","wrapper":"Sumatra (Équateur)","vitolas":[],"story":"Sous-cape nicaraguayenne, tripe nicaraguayenne et dominicaine, en cinq vitolas, assemblée à la Tabacalera La Alianza, dit Cigar Coop."}]',
        'Rolando Reyes Sr., born in 1924 in Zulueta, in the Cuban province of Las Villas, saw his brand Los Aliados and his factory confiscated by the Cuban government in 1968; he emigrated to the United States in 1971, first to Miami then to Jersey City, and renamed his production Cuba Aliados in Union City in 1973, according to Wikipedia. The family completed its move to Danlí, Honduras, in 1989; Rolando Reyes Sr. died on 18 March 2012.

On 6 August 2021, Oliva Cigar Co. bought the brands Cuba Aliados, Puros Indios and Roly from Carlos Diez, grandson of Rolando Reyes Sr. and sole owner of Reyes Family Cigars; the Reyes family keeps its own factory, only the brand names changing hands, says Cigar Coop.

Since then, the regular line, Original Blend, has been rolled as a Honduran puro — wrapper, binder and filler from Honduras — for a medium body, in five vitolas, from Robusto to Churchill, at the Fábrica de Puros Aladino, run by Julio R. Eiroa (JRE Tobacco Co.), in Danlí. A limited edition, blended by Ernesto Perez-Carrillo Jr., is rolled at the Tabacalera La Alianza, in the Dominican Republic, under an Ecuadorian Sumatra wrapper, over a Nicaraguan binder and a Nicaraguan and Dominican filler, likewise in five vitolas. As of June 2025, the Original Blend is still in the catalogue.',
        '[{"name":"Original Blend","color":"#A0522D","force":"Medium","wrapper":"Honduras (puro)","vitolas":[],"story":"Honduran binder and filler, in five vitolas, from Robusto to Churchill, rolled at the Fábrica de Puros Aladino, says Cigar Coop."},{"name":"by Ernesto Perez-Carrillo","color":"#A0522D","force":"Medium","wrapper":"Sumatra (Ecuador)","vitolas":[],"story":"Nicaraguan binder, Nicaraguan and Dominican filler, in five vitolas, blended at the Tabacalera La Alianza, says Cigar Coop."}]',
        'Rolando Reyes Sr., nacido en 1924 en Zulueta, en la provincia cubana de Las Villas, ve confiscadas su marca Los Aliados y su fábrica por el gobierno cubano en 1968; emigra a Estados Unidos en 1971, primero a Miami y luego a Jersey City, y rebautiza su producción como Cuba Aliados en Union City en 1973, según Wikipedia. La familia completa su instalación en Danlí, Honduras, en 1989; Rolando Reyes Sr. fallece el 18 de marzo de 2012.

El 6 de agosto de 2021, Oliva Cigar Co. compra las marcas Cuba Aliados, Puros Indios y Roly a Carlos Diez, nieto de Rolando Reyes Sr. y único propietario de Reyes Family Cigars; la familia Reyes conserva su propia fábrica, y solo los nombres de marca cambian de manos, dice Cigar Coop.

Desde entonces, la línea regular, Original Blend, se elabora como puro hondureño — capa, capote y tripa de Honduras —, para un cuerpo medio, en cinco vitolas, del Robusto al Churchill, en la Fábrica de Puros Aladino, dirigida por Julio R. Eiroa (JRE Tobacco Co.), en Danlí. Una edición limitada, ligada por Ernesto Perez-Carrillo Jr., se elabora en la Tabacalera La Alianza, en República Dominicana, con capa Sumatra de Ecuador, sobre capote nicaragüense y tripa nicaragüense y dominicana, también en cinco vitolas. En junio de 2025, el Original Blend sigue en el catálogo.',
        '[{"name":"Original Blend","color":"#A0522D","force":"Medium","wrapper":"Honduras (puro)","vitolas":[],"story":"Capote y tripa hondureñas, en cinco vitolas, del Robusto al Churchill, elaborada en la Fábrica de Puros Aladino, dice Cigar Coop."},{"name":"by Ernesto Perez-Carrillo","color":"#A0522D","force":"Medium","wrapper":"Sumatra (Ecuador)","vitolas":[],"story":"Capote nicaragüense, tripa nicaragüense y dominicana, en cinco vitolas, ligada en la Tabacalera La Alianza, dice Cigar Coop."}]',
        'Rolando Reyes Sr., geboren 1924 in Zulueta, in der kubanischen Provinz Las Villas, erlebt 1968 die Beschlagnahmung seiner Marke Los Aliados und seiner Fabrik durch die kubanische Regierung; 1971 wandert er in die Vereinigten Staaten aus, zunächst nach Miami, dann nach Jersey City, und benennt seine Produktion 1973 in Union City in Cuba Aliados um, laut Wikipedia. Die Familie schließt ihre Niederlassung in Danlí, Honduras, 1989 ab; Rolando Reyes Sr. stirbt am 18. März 2012.

Am 6. August 2021 kauft Oliva Cigar Co. die Marken Cuba Aliados, Puros Indios und Roly von Carlos Diez, dem Enkel von Rolando Reyes Sr. und alleinigen Eigentümer von Reyes Family Cigars; die Familie Reyes behält ihre eigene Fabrik, nur die Markennamen wechseln den Besitzer, so Cigar Coop.

Seither wird die reguläre Linie, Original Blend, als honduranischer Puro gerollt — Deckblatt, Umblatt und Einlage aus Honduras —, für einen mittleren Körper, in fünf Vitolas, vom Robusto bis zum Churchill, in der Fábrica de Puros Aladino, geleitet von Julio R. Eiroa (JRE Tobacco Co.), in Danlí. Eine limitierte Auflage, gemischt von Ernesto Perez-Carrillo Jr., wird in der Tabacalera La Alianza, in der Dominikanischen Republik, gerollt, unter einem ecuadorianischen Sumatra-Deckblatt, über nicaraguanischem Umblatt und nicaraguanischer und dominikanischer Einlage, ebenfalls in fünf Vitolas. Im Juni 2025 ist der Original Blend weiterhin im Sortiment.',
        '[{"name":"Original Blend","color":"#A0522D","force":"Medium","wrapper":"Honduras (puro)","vitolas":[],"story":"Honduranisches Umblatt und Einlage, in fünf Vitolas, vom Robusto bis zum Churchill, gerollt in der Fábrica de Puros Aladino, so Cigar Coop."},{"name":"by Ernesto Perez-Carrillo","color":"#A0522D","force":"Medium","wrapper":"Sumatra (Ecuador)","vitolas":[],"story":"Nicaraguanisches Umblatt, nicaraguanische und dominikanische Einlage, in fünf Vitolas, gemischt in der Tabacalera La Alianza, so Cigar Coop."}]',
        '据维基百科介绍，1924年出生于古巴拉斯维拉斯省苏卢埃塔的Rolando Reyes Sr.，其品牌Los Aliados及工厂于1968年被古巴政府没收；1971年他移民美国，先到迈阿密，后迁往泽西城，并于1973年在联合城将其产品更名为Cuba Aliados。其家族于1989年在洪都拉斯丹利完成新厂建设；Rolando Reyes Sr.于2012年3月18日去世。

据Cigar Coop介绍，2021年8月6日，Oliva Cigar Co.从Carlos Diez手中收购了Cuba Aliados、Puros Indios及Roly品牌；Carlos Diez是Rolando Reyes Sr.之孙，也是Reyes Family Cigars的唯一所有者；Reyes家族保留了自有工厂，易手的只是品牌名称。

此后，常规系列Original Blend一直作为洪都拉斯puro卷制——茄衣、茄套与茄芯均产自洪都拉斯——力度适中，共五种规格，从Robusto到Churchill，产自由Julio R. Eiroa（JRE Tobacco Co.）执掌的、位于丹利的Fábrica de Puros Aladino。另有一款限量版，由Ernesto Perez-Carrillo Jr.调配，产自多米尼加共和国的Tabacalera La Alianza，茄衣为厄瓜多尔产Sumatra，茄套为尼加拉瓜烟叶，茄芯为尼加拉瓜与多米尼加烟叶，同样有五种规格。截至2025年6月，Original Blend仍在产品目录中。',
        '[{"name":"Original Blend","color":"#A0522D","force":"Medium","wrapper":"洪都拉斯（puro）","vitolas":[],"story":"茄套与茄芯均产自洪都拉斯，共五种规格，从Robusto到Churchill，于Fábrica de Puros Aladino卷制，据Cigar Coop介绍。"},{"name":"by Ernesto Perez-Carrillo","color":"#A0522D","force":"Medium","wrapper":"Sumatra（厄瓜多尔）","vitolas":[],"story":"茄套为尼加拉瓜烟叶，茄芯为尼加拉瓜与多米尼加烟叶，共五种规格，于Tabacalera La Alianza调配卷制，据Cigar Coop介绍。"}]',
        'وفق ويكيبيديا، وُلد Rolando Reyes Sr. سنة 1924 في سولويتا، بمقاطعة لاس فياس الكوبية، وصادرت الحكومة الكوبية علامته Los Aliados ومصنعه سنة 1968؛ وهاجر إلى الولايات المتحدة سنة 1971، أولًا إلى ميامي ثم إلى جيرسي سيتي، وأعاد تسمية إنتاجه Cuba Aliados في يونيون سيتي سنة 1973. وأتمّت العائلة إقامة مصنعها في دانلي بهندوراس سنة 1989؛ وتوفي Rolando Reyes Sr. في 18 مارس 2012.

وفق Cigar Coop، في 6 أغسطس 2021، اشترت Oliva Cigar Co. علامات Cuba Aliados وPuros Indios وRoly من Carlos Diez، حفيد Rolando Reyes Sr. والمالك الوحيد لـReyes Family Cigars؛ واحتفظت عائلة Reyes بمصنعها الخاص، إذ لم يتغيّر سوى أسماء العلامات.

منذ ذلك الحين، يُلف الخط المنتظم Original Blend بوصفه puro هندوراسيًا — غلاف ورباط وحشوة من هندوراس — بقوة متوسطة، بخمسة مقاسات، من Robusto إلى Churchill، في Fábrica de Puros Aladino، التي يديرها Julio R. Eiroa (JRE Tobacco Co.)، في دانلي. وتُلف نسخة محدودة، مزجها Ernesto Perez-Carrillo Jr.، في Tabacalera La Alianza، في الجمهورية الدومينيكية، تحت غلاف Sumatra من الإكوادور، فوق رباط نيكاراغوي وحشوة نيكاراغوية ودومينيكية، وأيضًا بخمسة مقاسات. وحتى يونيو 2025، لا يزال Original Blend ضمن الكتالوج.',
        '[{"name":"Original Blend","color":"#A0522D","force":"Medium","wrapper":"هندوراس (puro)","vitolas":[],"story":"رباط وحشوة هندوراسية، بخمسة مقاسات، من Robusto إلى Churchill، تُلف في Fábrica de Puros Aladino، وفق Cigar Coop."},{"name":"by Ernesto Perez-Carrillo","color":"#A0522D","force":"Medium","wrapper":"Sumatra (الإكوادور)","vitolas":[],"story":"رباط نيكاراغوي، وحشوة نيكاراغوية ودومينيكية، بخمسة مقاسات، مزجها فريق Tabacalera La Alianza، وفق Cigar Coop."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Antonius ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Antonius',
        'dominican',
        'Non précisée — Maurice Koks, Tamboril',
        'Usine propre — Intercigar S.A., Parque Industrial Llanos de Canca, Tamboril (Santiago)',
        'intercigar.com « Antonius » (2026-09-25 : adresse de la fabrique, Parque Industrial Llanos de Canca, Tamboril, Santiago ; Maurice « Antonius » Koks présenté comme fondateur, avec un menu de trois lignes, Antonius, Private Label, Vallejuelo) ; intercigar.com « Our Cigars » (2026-09-25 : Intercigar produit Antonius et Vallejuelo comme marques propres, et des cigares de marque privée pour des tiers) ; cigarworld.de « Antonius » (2026-09-25 : au catalogue depuis le 11 janvier 2011 ; trois vitolas, Belicoso, Robusto, Toro) ; atlanticcigar.com « Antonius Connecticut Cigars Robusto » (2026-09-25 : cape Connecticut Shade équatorienne couleur colorado claro, liant dominicain, force medium) ; atlanticcigar.com « Antonius Habano Cigars Robusto » (2026-09-25 : cape Habano équatorienne de graine cubaine couleur colorado, force medium) ; atlanticcigar.com « Antonius Maduro Cigars Robusto » (2026-09-25 : cape San Andrés mexicaine, force medium) ; cigar-coop.com « Cigar News: Tabacalera William Ventura Destroyed in Massive Fire » (2022-09-26 : incendie du 26 septembre 2022 détruisant Tabacalera William Ventura et touchant aussi Intercigar S.A., propriété de Maurice Koks) ; tobaccoreporter.com « Fire Destroys Dominican Cigar Factories » (2022-09-27 : incendie à Tamboril dans le complexe Zona Franca La Palma, bâtiment partagé par Tabacalera William Ventura et Intercigar ; Intercigar y fabriquait Vallejuelo et la ligne RVGN Rauchvergnügen pour German Engineered Cigars) ; cigar-coop.com « Cigar News: German Engineered Cigars Addresses InterCigar S.A. Fire » (2022-09 : la ligne RVGN Rauchvergnügen, de German Engineered Cigars, est roulée chez Intercigar ; la ligne Raumzeit de la même société vient du Nicaragua)',
        NULL,
        'Antonius porte le nom de Maurice « Antonius » Koks, d''origine néerlandaise, qui préside et a fondé Intercigar S.A., une manufacture installée à Tamboril, dans la province de Santiago, en République dominicaine, dit la maison. La marque honore le grand-père et l''arrière-grand-père de Maurice Koks, tous deux surnommés Antonius, ou Toontje, et rouleurs de cigares en Hollande, dit Atlantic Cigar. Intercigar roule Antonius comme marque propre, avec Vallejuelo ; elle roule aussi, pour la maison hambourgeoise German Engineered Cigars, la ligne RVGN Rauchvergnügen, et d''autres cigares de marque privée pour des clients tiers, disent la maison et Cigar Coop. Le 26 septembre 2022, un incendie a détruit le bâtiment que Tabacalera William Ventura et Intercigar partageaient dans la zone franche La Palma, à Tamboril, dit Tobacco Reporter. En septembre 2026, la maison situe Intercigar au Parque Industrial Llanos de Canca, à Tamboril, une autre adresse que celle d''avant l''incendie.

En septembre 2026, le catalogue se partage en trois capes : Connecticut (Connecticut Shade équatorienne), Habano (cape équatorienne de graine cubaine) et Maduro (cape San Andrés, au Mexique), chacune un cigare de force moyenne roulé sur une tripe dominicaine vieillie, dit Atlantic Cigar. Cigarworld.de, qui tient la marque à son catalogue depuis le 11 janvier 2011, y ajoute une vitola Belicoso, en plus du Robusto et du Toro communs aux trois capes.',
        '[{"name":"Antonius Connecticut","color":"#C9A96E","force":"Medium","wrapper":"Connecticut Shade (Équateur)","vitolas":[],"story":"Cape Connecticut Shade équatorienne sur tripe dominicaine vieillie, en Robusto et Toro, dit Atlantic Cigar."},{"name":"Antonius Habano","color":"#A0522D","force":"Medium","wrapper":"Habano (Équateur)","vitolas":[],"story":"Cape Habano équatorienne de graine cubaine, en Robusto, Toro et Belicoso, dit Atlantic Cigar et Cigarworld.de."},{"name":"Antonius Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Cape San Andrés mexicaine, aux notes de chocolat, de cuir et de terre, en Robusto et Toro, dit Atlantic Cigar."}]',
        'Antonius takes its name from Maurice « Antonius » Koks, of Dutch origin, who chairs and founded Intercigar S.A., a factory based in Tamboril, in the province of Santiago, in the Dominican Republic, the house says. The brand honours Maurice Koks''s grandfather and great-grandfather, both nicknamed Antonius, or Toontje, and cigar rollers in the Netherlands, says Atlantic Cigar. Intercigar rolls Antonius as its own brand, alongside Vallejuelo; it also rolls, for the Hamburg-based house German Engineered Cigars, the RVGN Rauchvergnügen line, and other private-label cigars for third-party clients, say the house and Cigar Coop. On 26 September 2022, a fire destroyed the building that Tabacalera William Ventura and Intercigar shared in the La Palma free zone, in Tamboril, says Tobacco Reporter. In September 2026, the house places Intercigar at Parque Industrial Llanos de Canca, in Tamboril, a different address from the one before the fire.

In September 2026, the range is divided into three wrappers: Connecticut (Ecuadorian Connecticut Shade), Habano (Ecuadorian wrapper of Cuban seed) and Maduro (San Andrés wrapper, from Mexico), each a medium-strength cigar rolled on an aged Dominican filler, says Atlantic Cigar. Cigarworld.de, which has carried the brand since 11 January 2011, adds a Belicoso vitola, alongside the Robusto and Toro common to all three wrappers.',
        '[{"name":"Antonius Connecticut","color":"#C9A96E","force":"Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Ecuadorian Connecticut Shade wrapper on aged Dominican filler, in Robusto and Toro, says Atlantic Cigar."},{"name":"Antonius Habano","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Ecuadorian Habano wrapper of Cuban seed, in Robusto, Toro and Belicoso, say Atlantic Cigar and Cigarworld.de."},{"name":"Antonius Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Mexican San Andrés wrapper, with notes of chocolate, leather and earth, in Robusto and Toro, says Atlantic Cigar."}]',
        'Antonius debe su nombre a Maurice « Antonius » Koks, de origen neerlandés, que preside y fundó Intercigar S.A., una fábrica instalada en Tamboril, en la provincia de Santiago, en República Dominicana, según la casa. La marca rinde homenaje al abuelo y al bisabuelo de Maurice Koks, ambos apodados Antonius, o Toontje, y torcedores de puros en los Países Bajos, según Atlantic Cigar. Intercigar elabora Antonius como marca propia, junto con Vallejuelo; también elabora, para la casa hamburguesa German Engineered Cigars, la línea RVGN Rauchvergnügen, y otros puros de marca privada para clientes terceros, según la casa y Cigar Coop. El 26 de septiembre de 2022, un incendio destruyó el edificio que Tabacalera William Ventura e Intercigar compartían en la zona franca La Palma, en Tamboril, según Tobacco Reporter. En septiembre de 2026, la casa sitúa Intercigar en el Parque Industrial Llanos de Canca, en Tamboril, una dirección distinta a la anterior al incendio.

En septiembre de 2026, el catálogo se reparte en tres capas: Connecticut (Connecticut Shade ecuatoriana), Habano (capa ecuatoriana de semilla cubana) y Maduro (capa San Andrés, en México), cada una un puro de fuerza media liado sobre una tripa dominicana envejecida, según Atlantic Cigar. Cigarworld.de, que tiene la marca en catálogo desde el 11 de enero de 2011, añade una vitola Belicoso, además del Robusto y el Toro comunes a las tres capas.',
        '[{"name":"Antonius Connecticut","color":"#C9A96E","force":"Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Capa Connecticut Shade ecuatoriana sobre tripa dominicana envejecida, en Robusto y Toro, según Atlantic Cigar."},{"name":"Antonius Habano","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Capa Habano ecuatoriana de semilla cubana, en Robusto, Toro y Belicoso, según Atlantic Cigar y Cigarworld.de."},{"name":"Antonius Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (México)","vitolas":[],"story":"Capa San Andrés mexicana, con notas de chocolate, cuero y tierra, en Robusto y Toro, según Atlantic Cigar."}]',
        'Antonius trägt den Namen von Maurice « Antonius » Koks, niederländischer Herkunft, der Intercigar S.A. leitet und gegründet hat, eine Fabrik mit Sitz in Tamboril, in der Provinz Santiago, in der Dominikanischen Republik, so das Haus. Die Marke ehrt den Großvater und den Urgroßvater von Maurice Koks, beide mit dem Spitznamen Antonius, oder Toontje, und Zigarrenroller in den Niederlanden, so Atlantic Cigar. Intercigar rollt Antonius als eigene Marke, zusammen mit Vallejuelo; für das Hamburger Haus German Engineered Cigars rollt sie zudem die Linie RVGN Rauchvergnügen sowie weitere Zigarren als Privatmarke für Drittkunden, so das Haus und Cigar Coop. Am 26. September 2022 zerstörte ein Brand das Gebäude, das sich Tabacalera William Ventura und Intercigar in der Freihandelszone La Palma, in Tamboril, teilten, so Tobacco Reporter. Im September 2026 verortet das Haus Intercigar im Parque Industrial Llanos de Canca, in Tamboril, eine andere Adresse als vor dem Brand.

Im September 2026 gliedert sich das Sortiment in drei Deckblätter: Connecticut (Connecticut Shade aus Ecuador), Habano (Deckblatt aus Ecuador, von kubanischem Saatgut) und Maduro (Deckblatt San Andrés, aus Mexiko), jede eine Zigarre mittlerer Stärke auf gereiftem dominikanischem Einlagetabak, so Atlantic Cigar. Cigarworld.de, das die Marke seit dem 11. Januar 2011 im Sortiment führt, ergänzt eine Vitola Belicoso, neben Robusto und Toro, die allen drei Deckblättern gemeinsam sind.',
        '[{"name":"Antonius Connecticut","color":"#C9A96E","force":"Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Deckblatt Connecticut Shade aus Ecuador auf gereiftem dominikanischem Einlagetabak, als Robusto und Toro, so Atlantic Cigar."},{"name":"Antonius Habano","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Deckblatt Habano aus Ecuador, von kubanischem Saatgut, als Robusto, Toro und Belicoso, so Atlantic Cigar und Cigarworld.de."},{"name":"Antonius Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Deckblatt San Andrés aus Mexiko, mit Aromen von Schokolade, Leder und Erde, als Robusto und Toro, so Atlantic Cigar."}]',
        'Antonius之名，源自荷兰裔的Maurice « Antonius » Koks——据厂方介绍，他创立并执掌位于多米尼加共和国圣地亚哥省坦博里尔的Intercigar S.A.。据Atlantic Cigar介绍，品牌以此纪念Maurice Koks的祖父与曾祖父，二人都被称为Antonius，或Toontje，且都曾在荷兰从事雪茄卷制。据厂方与Cigar Coop介绍，Intercigar既卷制自有品牌Antonius与Vallejuelo，也为汉堡的German Engineered Cigars卷制RVGN Rauchvergnügen系列，并为其他第三方客户代工雪茄。据Tobacco Reporter报道，2022年9月26日的一场火灾，烧毁了Tabacalera William Ventura与Intercigar在坦博里尔La Palma自由区共用的厂房。截至2026年9月，厂方将Intercigar的地址列为坦博里尔的Parque Industrial Llanos de Canca，与火灾前的地址不同。

据Atlantic Cigar介绍，截至2026年9月，产品线分为三种茄衣：Connecticut（厄瓜多尔Connecticut Shade）、Habano（古巴种子的厄瓜多尔茄衣）与Maduro（墨西哥San Andrés茄衣），每款都是力度适中的雪茄，茄芯采用陈化多米尼加烟叶。自2011年1月11日起将该品牌收入目录的Cigarworld.de，还加入了一款Belicoso型号，在三种茄衣共有的Robusto与Toro之外。',
        '[{"name":"Antonius Connecticut","color":"#C9A96E","force":"Medium","wrapper":"Connecticut Shade（厄瓜多尔）","vitolas":[],"story":"厄瓜多尔Connecticut Shade茄衣，配陈化多米尼加茄芯，型号为Robusto与Toro，据Atlantic Cigar介绍。"},{"name":"Antonius Habano","color":"#A0522D","force":"Medium","wrapper":"Habano（厄瓜多尔）","vitolas":[],"story":"厄瓜多尔Habano茄衣，采用古巴种子，型号为Robusto、Toro与Belicoso，据Atlantic Cigar与Cigarworld.de介绍。"},{"name":"Antonius Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"墨西哥San Andrés茄衣，带有可可、皮革与泥土的香气，型号为Robusto与Toro，据Atlantic Cigar介绍。"}]',
        'يحمل Antonius اسم Maurice « Antonius » Koks، الهولندي الأصل، الذي يرأس شركة Intercigar S.A. وأسّسها، وهي مصنع يقع في تامبوريل، في مقاطعة سانتياغو، في جمهورية الدومينيكان، بحسب ما تقوله الدار. وتكرّم العلامة جدّ Maurice Koks وجدّه الأكبر، وكلاهما كان يُلقَّب بـAntonius، أو Toontje، وعمل كلاهما لفّافًا للسيجار في هولندا، بحسب Atlantic Cigar. وتقوم Intercigar بلف Antonius بصفتها علامتها الخاصة، إلى جانب Vallejuelo؛ كما تلف، لصالح دار German Engineered Cigars ومقرّها هامبورغ، خط RVGN Rauchvergnügen، وسيجارًا آخر بعلامة خاصة لعملاء آخرين، بحسب الدار وCigar Coop. وفي 26 سبتمبر 2022، دمّر حريق المبنى الذي كانت تتشاركه Tabacalera William Ventura وIntercigar في المنطقة الحرة La Palma، في تامبوريل، بحسب Tobacco Reporter. وفي سبتمبر 2026، تحدّد الدار عنوان Intercigar في Parque Industrial Llanos de Canca، في تامبوريل، وهو عنوان مختلف عن العنوان الذي كان قائمًا قبل الحريق.

وفي سبتمبر 2026، تنقسم التشكيلة إلى ثلاثة أغلفة: Connecticut (غلاف Connecticut Shade إكوادوري)، وHabano (غلاف إكوادوري من بذور كوبية)، وMaduro (غلاف San Andrés، من المكسيك)، وكل منها سيجار متوسط القوة يُلف على حشوة دومينيكية معتَّقة، بحسب Atlantic Cigar. وتضيف Cigarworld.de، التي تُدرج العلامة في كتالوجها منذ 11 يناير 2011، مقاسًا من طراز Belicoso، إلى جانب Robusto وToro المشتركَين بين الأغلفة الثلاثة.',
        '[{"name":"Antonius Connecticut","color":"#C9A96E","force":"Medium","wrapper":"Connecticut Shade (الإكوادور)","vitolas":[],"story":"غلاف Connecticut Shade إكوادوري على حشوة دومينيكية معتَّقة، بمقاسَي Robusto وToro، بحسب Atlantic Cigar."},{"name":"Antonius Habano","color":"#A0522D","force":"Medium","wrapper":"Habano (الإكوادور)","vitolas":[],"story":"غلاف Habano إكوادوري من بذور كوبية، بمقاسات Robusto وToro وBelicoso، بحسب Atlantic Cigar وCigarworld.de."},{"name":"Antonius Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"غلاف San Andrés مكسيكي، بنكهات الشوكولاتة والجلد والتراب، بمقاسَي Robusto وToro، بحسب Atlantic Cigar."}]')
