-- ── Butera ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Butera',
        'dominican',
        '1993 — Michael Butera (pipier, Texas)',
        'Tabacalera de García, La Romana — la fabrique dominicaine d''Altadis U.S.A., selon Cigar Coop',
        'cigarcentury.com « Butera » (2026-09-25 : Altadis USA produit aujourd''hui Butera, fondée par Michael Butera, pipier du Texas ; deux lignes en vente, Royal Vintage et Vintage Select, cape Connecticut Shade, de 8,20 à 12,80 dollars) ; cigarplace.biz « Butera Royal Vintage » (2026-09-25 : marque introduite en 1993 par Mike Butera ; roulée en République dominicaine à partir de six tabacs de trois pays, liant indonésien épicé, cape Connecticut ; lignes Bravo Corto, Poca Bella, Dorado) ; cigar-coop.com « A Visit to Tabacalera de Garcia: Feature Story » (2025-09 : Tabacalera de Garcia, à La Romana, gérée par Tabacalera USA et Altadis U.S.A., y roule quinze familles de marques dont Romeo y Julieta, Montecristo, H. Upmann et VegaFina, sans y citer Butera)',
        NULL,
        'Butera doit son nom à Michael Butera, pipier du Texas, qui lance la marque en 1993, dit CigarPlace. Elle appartient à Altadis U.S.A. et se roule en République dominicaine. Altadis U.S.A. roule ses cigares dominicains faits à la main à la Tabacalera de García, à La Romana — quinze familles de marques, dont Romeo y Julieta Dominicain, Montecristo Dominicain, H. Upmann Dominicain et VegaFina —, dit Cigar Coop en 2025 ; la maison ne nomme pas la fabrique de Butera.

La marque assemble six tabacs de trois pays, avec une sous-cape indonésienne épicée et une cape Connecticut, dit CigarPlace. En septembre 2026, Century Premium Cigars la vend en deux lignes, Royal Vintage et Vintage Select, sous cape Connecticut Shade ; la Royal Vintage se décline notamment en Bravo Corto, Poca Bella et Dorado, dit CigarPlace.',
        '[{"name":"Butera Royal Vintage","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Sous-cape indonésienne épicée et tripe de trois pays, en plusieurs vitolas dont Bravo Corto, Poca Bella et Dorado, dit CigarPlace."},{"name":"Butera Vintage Select","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Même cape Connecticut Shade que Royal Vintage, vendue en septembre 2026 chez Century Premium Cigars."}]',
        'Butera takes its name from Michael Butera, a Texas pipe maker, who launched the brand in 1993, says CigarPlace. It belongs to Altadis U.S.A. and is rolled in the Dominican Republic. Altadis U.S.A. rolls its handmade Dominican cigars at Tabacalera de García, in La Romana — fifteen brand families, including Romeo y Julieta Dominicain, Montecristo Dominicain, H. Upmann Dominicain and VegaFina —, says Cigar Coop in 2025; the house does not name Butera''s factory.

The brand blends six tobaccos from three countries, with a spicy Indonesian binder and a Connecticut wrapper, says CigarPlace. In September 2026, Century Premium Cigars sells it in two lines, Royal Vintage and Vintage Select, under Connecticut Shade wrapper; the Royal Vintage comes notably in Bravo Corto, Poca Bella and Dorado, says CigarPlace.',
        '[{"name":"Butera Royal Vintage","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Spicy Indonesian binder and filler from three countries, in several vitolas including Bravo Corto, Poca Bella and Dorado, says CigarPlace."},{"name":"Butera Vintage Select","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Same Connecticut Shade wrapper as Royal Vintage, sold in September 2026 at Century Premium Cigars."}]',
        'Butera debe su nombre a Michael Butera, fabricante de pipas de Texas, que lanza la marca en 1993, según CigarPlace. Pertenece a Altadis U.S.A. y se elabora en República Dominicana. Altadis U.S.A. elabora sus puros dominicanos hechos a mano en la Tabacalera de García, en La Romana —quince familias de marcas, entre ellas Romeo y Julieta Dominicain, Montecristo Dominicain, H. Upmann Dominicain y VegaFina—, según Cigar Coop en 2025; la casa no nombra la fábrica de Butera.

La marca combina seis tabacos de tres países, con un capote indonesio especiado y una capa Connecticut, según CigarPlace. En septiembre de 2026, Century Premium Cigars la vende en dos líneas, Royal Vintage y Vintage Select, bajo capa Connecticut Shade; la Royal Vintage se presenta especialmente en Bravo Corto, Poca Bella y Dorado, según CigarPlace.',
        '[{"name":"Butera Royal Vintage","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Capote indonesio especiado y tripa de tres países, en varias vitolas entre ellas Bravo Corto, Poca Bella y Dorado, según CigarPlace."},{"name":"Butera Vintage Select","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Misma capa Connecticut Shade que Royal Vintage, a la venta en septiembre de 2026 en Century Premium Cigars."}]',
        'Butera verdankt seinen Namen Michael Butera, einem Pfeifenmacher aus Texas, der die Marke 1993 lanciert, so CigarPlace. Sie gehört Altadis U.S.A. und wird in der Dominikanischen Republik gerollt. Altadis U.S.A. rollt seine handgefertigten dominikanischen Zigarren in der Tabacalera de García, in La Romana — fünfzehn Markenfamilien, darunter Romeo y Julieta Dominicain, Montecristo Dominicain, H. Upmann Dominicain und VegaFina —, so Cigar Coop im Jahr 2025; das Haus nennt die Fabrik von Butera nicht.

Die Marke vereint sechs Tabake aus drei Ländern, mit einem würzigen indonesischen Umblatt und einem Connecticut-Deckblatt, so CigarPlace. Im September 2026 verkauft Century Premium Cigars sie in zwei Linien, Royal Vintage und Vintage Select, unter Deckblatt Connecticut Shade; die Royal Vintage gibt es unter anderem als Bravo Corto, Poca Bella und Dorado, so CigarPlace.',
        '[{"name":"Butera Royal Vintage","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Würziges indonesisches Umblatt und Einlagetabak aus drei Ländern, in mehreren Vitolas, darunter Bravo Corto, Poca Bella und Dorado, so CigarPlace."},{"name":"Butera Vintage Select","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Gleiches Deckblatt Connecticut Shade wie Royal Vintage, im September 2026 bei Century Premium Cigars erhältlich."}]',
        '据CigarPlace介绍，Butera之名来自Michael Butera——一位得克萨斯州的烟斗制作人，他于1993年创立了这一品牌。品牌归Altadis U.S.A.所有，在多米尼加共和国卷制。据Cigar Coop在2025年介绍，Altadis U.S.A.的多米尼加手工雪茄均在拉罗马纳的Tabacalera de García卷制——旗下共十五个品牌家族，包括Romeo y Julieta Dominicain、Montecristo Dominicain、H. Upmann Dominicain与VegaFina；厂方并未指明Butera自身的工厂。

据CigarPlace介绍，该品牌调配来自三个国家的六种烟叶，配以带辛香的印尼茄套与Connecticut茄衣。截至2026年9月，Century Premium Cigars将其分两条线出售，Royal Vintage与Vintage Select，均用Connecticut Shade茄衣；其中Royal Vintage尤以Bravo Corto、Poca Bella与Dorado等型号推出，据CigarPlace介绍。',
        '[{"name":"Butera Royal Vintage","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"带辛香的印尼茄套，茄芯取自三个国家，型号多样，包括Bravo Corto、Poca Bella与Dorado，据CigarPlace介绍。"},{"name":"Butera Vintage Select","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"与Royal Vintage同为Connecticut Shade茄衣，截至2026年9月在Century Premium Cigars有售。"}]',
        'يستمدّ Butera اسمه من Michael Butera، صانع غلايين من تكساس، الذي أطلق العلامة في 1993، بحسب CigarPlace. وتملكها Altadis U.S.A. وتُلَفّ في جمهورية الدومينيكان. وتلفّ Altadis U.S.A. سيجارها الدومينيكي المصنوع يدويًا في Tabacalera de García، في لا رومانا — خمس عشرة عائلة من العلامات، منها Romeo y Julieta Dominicain وMontecristo Dominicain وH. Upmann Dominicain وVegaFina، بحسب Cigar Coop في 2025؛ ولا تسمّي الدار مصنع Butera.

وتمزج العلامة ستة أنواع من التبغ من ثلاث دول، بغلاف داخلي إندونيسي حِرّيف وغلاف Connecticut، بحسب CigarPlace. وفي سبتمبر 2026، تبيعها Century Premium Cigars في خطَّين، Royal Vintage وVintage Select، بغلاف Connecticut Shade؛ وتُطرح Royal Vintage خصوصًا بمقاسات منها Bravo Corto وPoca Bella وDorado، بحسب CigarPlace.',
        '[{"name":"Butera Royal Vintage","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"غلاف داخلي إندونيسي حِرّيف وحشوة من ثلاث دول، بعدة مقاسات منها Bravo Corto وPoca Bella وDorado، بحسب CigarPlace."},{"name":"Butera Vintage Select","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"الغلاف نفسه Connecticut Shade الذي في Royal Vintage، وهو معروض في سبتمبر 2026 لدى Century Premium Cigars."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Bahia ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Bahia',
        'nicaragua',
        'Milieu des années 1990 — Tony Borhani',
        'Estelí, Nicaragua — la maison ne nomme pas sa fabrique',
        'thecigarstore.com « Bahia Cigars » (2026-09-25 : marque créée par Tony Borhani au milieu des années 1990 ; ligne Blu à cape Habano nicaraguayenne, ligne Maduro à cape maduro foncée, tabacs nicaraguayens vieillis pour les deux) ; en.wikipedia.org « Scandinavian Tobacco Group » (2026-09-25 : Cigars International, filiale basée aux États-Unis, rejoint le groupe lors de la fusion du 26 avril 2010 entre Scandinavian Tobacco Group AB et les activités cigares et tabac à pipe de Swedish Match AB) ; gothamcigars.com « Bahia Blu and Maduro » (consulté le 24 septembre 2026 : Tony Borhani et Don Douglas Pueringer ne possèdent plus la marque, rachetée par Cigars International ; la page situe la ligne Blu à la fabrique Tambor S.A., à Estelí) ; holts.com « Shop Bahia Blu Cigars » (2026-09-25 : Bahia Blu handmade in Estelí, Nicaragua, cape Corojo huileuse, force mild-medium, rupture de stock chez ce détaillant) ; cigarplace.biz « Bahia Blu U700 Churchills » (2026-09-25 : Bahia Blu en vente, cape Habano nicaraguayenne sun grown type Corojo, tripe d''Estelí, Jalapa et Condega vieillie cinq à six ans) ; cigarmonthclub.com « Bahia Maduro » (2026-09-25 : tabac cultivé au Nicaragua, en République dominicaine et en Équateur ; cape Connecticut Shade broadleaf, liant Olor et tripe Piloto Cubano dominicains ; la page classe elle-même le cigare Country: Nicaragua)',
        NULL,
        'Bahia naît au milieu des années 1990, fondée par Tony Borhani, dit thecigarstore.com. La marque et ses noms de commerce ont depuis été rachetés par Cigars International, dit Gotham Cigars — filiale de vente en ligne du groupe Scandinavian Tobacco Group depuis la fusion du 26 avril 2010 entre Scandinavian Tobacco Group AB et les activités cigares et tabac à pipe de Swedish Match AB. La maison ne nomme pas sa fabrique.

La ligne Blu, en vente en septembre 2026 chez CigarPlace, reste roulée à la main à Estelí, au Nicaragua, dit Holt''s Cigar : cape Habano nicaraguayenne sun grown de type Corojo, huileuse, sur une tripe d''Estelí, de Jalapa et de Condega vieillie cinq à six ans, pour un profil moyen, de cèdre, de toast et de cuir. La ligne Maduro s''habille d''une cape Connecticut Shade broadleaf sur liant Olor et tripe Piloto Cubano, tous deux dominicains, avec des tabacs venus aussi du Nicaragua et de l''Équateur ; un détaillant la classe au Nicaragua, un autre en République dominicaine, dit Premium Cigar of the Month Club et thecigarstore.com.',
        '[{"name":"Bahia Blu","color":"#A0522D","force":"Medium","wrapper":"Habano (Nicaragua)","vitolas":[],"story":"Roulée à Estelí, Nicaragua, cape Corojo huileuse sur tripe d''Estelí, de Jalapa et de Condega vieillie cinq à six ans, dit Holt''s Cigar et CigarPlace."},{"name":"Bahia Maduro","color":"#4A3728","force":null,"wrapper":"Connecticut Shade broadleaf","vitolas":[],"story":"Liant Olor et tripe Piloto Cubano dominicains, tabacs aussi nicaraguayens et équatoriens ; pays de roulage donné tantôt pour la République dominicaine, tantôt pour le Nicaragua, selon le détaillant."}]',
        'Bahia was born in the mid-1990s, founded by Tony Borhani, says thecigarstore.com. The brand and its trade names have since been bought by Cigars International, says Gotham Cigars — the online retail arm of the Scandinavian Tobacco Group since the merger of 26 April 2010 between Scandinavian Tobacco Group AB and the cigar and pipe tobacco operations of Swedish Match AB. The house does not name its factory.

The Blu line, on sale in September 2026 at CigarPlace, remains hand-rolled in Estelí, Nicaragua, says Holt''s Cigar: an oily Nicaraguan Habano sun grown wrapper of the Corojo type, on a filler of Estelí, Jalapa and Condega tobacco aged five to six years, for a medium profile of cedar, toast and leather. The Maduro line wears a Connecticut Shade broadleaf wrapper on Olor binder and Piloto Cubano filler, both Dominican, with tobacco also coming from Nicaragua and Ecuador; one retailer places it in Nicaragua, another in the Dominican Republic, say Premium Cigar of the Month Club and thecigarstore.com.',
        '[{"name":"Bahia Blu","color":"#A0522D","force":"Medium","wrapper":"Habano (Nicaragua)","vitolas":[],"story":"Rolled in Estelí, Nicaragua, oily Corojo wrapper on a filler of Estelí, Jalapa and Condega tobacco aged five to six years, say Holt''s Cigar and CigarPlace."},{"name":"Bahia Maduro","color":"#4A3728","force":null,"wrapper":"Connecticut Shade broadleaf","vitolas":[],"story":"Dominican Olor binder and Piloto Cubano filler, tobacco also from Nicaragua and Ecuador; the country where it is rolled is given as the Dominican Republic by some retailers and Nicaragua by others."}]',
        'Bahia nace a mediados de los años noventa, fundada por Tony Borhani, según thecigarstore.com. La marca y sus nombres comerciales han sido desde entonces adquiridos por Cigars International, según Gotham Cigars —filial de venta en línea del grupo Scandinavian Tobacco Group desde la fusión del 26 de abril de 2010 entre Scandinavian Tobacco Group AB y las actividades de puros y tabaco de pipa de Swedish Match AB. La casa no nombra su fábrica.

La línea Blu, a la venta en septiembre de 2026 en CigarPlace, sigue liándose a mano en Estelí, Nicaragua, según Holt''s Cigar: capa Habano nicaragüense sun grown de tipo Corojo, aceitosa, sobre una tripa de Estelí, Jalapa y Condega envejecida de cinco a seis años, para un perfil medio, de cedro, tostado y cuero. La línea Maduro luce una capa Connecticut Shade broadleaf sobre capote Olor y tripa Piloto Cubano, ambos dominicanos, con tabacos también procedentes de Nicaragua y Ecuador; un comerciante la clasifica en Nicaragua, otro en República Dominicana, según Premium Cigar of the Month Club y thecigarstore.com.',
        '[{"name":"Bahia Blu","color":"#A0522D","force":"Medium","wrapper":"Habano (Nicaragua)","vitolas":[],"story":"Liada en Estelí, Nicaragua, capa Corojo aceitosa sobre tripa de Estelí, Jalapa y Condega envejecida de cinco a seis años, según Holt''s Cigar y CigarPlace."},{"name":"Bahia Maduro","color":"#4A3728","force":null,"wrapper":"Connecticut Shade broadleaf","vitolas":[],"story":"Capote Olor y tripa Piloto Cubano dominicanos, tabacos también nicaragüenses y ecuatorianos; el país de liado se da unas veces como República Dominicana, otras como Nicaragua, según el comerciante."}]',
        'Bahia entsteht Mitte der 1990er-Jahre, gegründet von Tony Borhani, so thecigarstore.com. Die Marke und ihre Handelsnamen wurden seitdem von Cigars International übernommen, so Gotham Cigars — die Online-Vertriebstochter der Scandinavian Tobacco Group seit der Fusion vom 26. April 2010 zwischen der Scandinavian Tobacco Group AB und den Zigarren- und Pfeifentabak-Aktivitäten der Swedish Match AB. Das Haus nennt seine Fabrik nicht.

Die Linie Blu, im September 2026 bei CigarPlace erhältlich, wird weiterhin von Hand in Estelí, Nicaragua, gerollt, so Holt''s Cigar: ein öliges nicaraguanisches Habano-Deckblatt sun grown vom Typ Corojo, auf einem fünf bis sechs Jahre gereiften Einlagetabak aus Estelí, Jalapa und Condega, für ein mittleres Profil von Zeder, Röstaromen und Leder. Die Linie Maduro trägt ein Deckblatt Connecticut Shade broadleaf auf Olor-Umblatt und Piloto-Cubano-Einlagetabak, beide dominikanisch, mit Tabaken, die auch aus Nicaragua und Ecuador stammen; ein Händler ordnet sie Nicaragua zu, ein anderer der Dominikanischen Republik, so Premium Cigar of the Month Club und thecigarstore.com.',
        '[{"name":"Bahia Blu","color":"#A0522D","force":"Medium","wrapper":"Habano (Nicaragua)","vitolas":[],"story":"Gerollt in Estelí, Nicaragua, öliges Corojo-Deckblatt auf einem fünf bis sechs Jahre gereiften Einlagetabak aus Estelí, Jalapa und Condega, so Holt''s Cigar und CigarPlace."},{"name":"Bahia Maduro","color":"#4A3728","force":null,"wrapper":"Connecticut Shade broadleaf","vitolas":[],"story":"Dominikanisches Olor-Umblatt und Piloto-Cubano-Einlagetabak, auch Tabak aus Nicaragua und Ecuador; das Land, in dem gerollt wird, wird je nach Händler mit der Dominikanischen Republik oder mit Nicaragua angegeben."}]',
        '据thecigarstore.com介绍，Bahia创立于1990年代中期，由Tony Borhani创立。据Gotham Cigars介绍，该品牌及其商号此后被Cigars International收购——后者是Scandinavian Tobacco Group集团旗下的线上零售子公司，该集团由Scandinavian Tobacco Group AB与Swedish Match AB的雪茄及烟斗丝业务于2010年4月26日合并而成。厂方并未说明其工厂所在。

据Holt''s Cigar介绍，截至2026年9月在CigarPlace有售的Blu系列，仍在尼加拉瓜埃斯特利手工卷制：采用油润的尼加拉瓜Habano sun grown茄衣，属Corojo类型，茄芯取自埃斯特利、哈拉帕与孔德加、陈化五至六年，风味适中，带雪松、烘烤与皮革香气。Maduro系列则采用Connecticut Shade broadleaf茄衣，配多米尼加产的Olor茄套与Piloto Cubano茄芯，部分烟叶也产自尼加拉瓜与厄瓜多尔；据Premium Cigar of the Month Club与thecigarstore.com介绍，有零售商将其归为尼加拉瓜产，也有零售商归为多米尼加共和国产。',
        '[{"name":"Bahia Blu","color":"#A0522D","force":"Medium","wrapper":"Habano（尼加拉瓜）","vitolas":[],"story":"在尼加拉瓜埃斯特利卷制，油润的Corojo茄衣，茄芯取自埃斯特利、哈拉帕与孔德加，陈化五至六年，据Holt''s Cigar与CigarPlace介绍。"},{"name":"Bahia Maduro","color":"#4A3728","force":null,"wrapper":"Connecticut Shade broadleaf","vitolas":[],"story":"多米尼加产Olor茄套与Piloto Cubano茄芯，部分烟叶也来自尼加拉瓜与厄瓜多尔；不同零售商给出的卷制产地不同，有的记为多米尼加共和国，有的记为尼加拉瓜。"}]',
        'وُلدت Bahia في منتصف تسعينيات القرن الماضي، على يد Tony Borhani، بحسب thecigarstore.com. واستحوذت Cigars International منذ ذلك الحين على العلامة وأسمائها التجارية، بحسب Gotham Cigars — وهي الذراع البيعي عبر الإنترنت لمجموعة Scandinavian Tobacco Group منذ اندماج 26 أبريل 2010 بين Scandinavian Tobacco Group AB وأنشطة السيجار وتبغ الغليون التابعة لـSwedish Match AB. ولا تسمّي الدار مصنعها.

وبحسب Holt''s Cigar، لا يزال خط Blu، المعروض في سبتمبر 2026 لدى CigarPlace، يُلَفّ يدويًا في إستيلي بنيكاراغوا: غلاف Habano نيكاراغوي sun grown من نوع Corojo، زيتي الملمس، على حشوة من إستيلي وخالابا وكونديغا معتَّقة خمس إلى ست سنوات، بملمح متوسط من خشب الأرز والتحميص والجلد. أما خط Maduro فيرتدي غلاف Connecticut Shade broadleaf على غلاف داخلي من Olor وحشوة Piloto Cubano، وكلاهما دومينيكي، مع تبغ يأتي أيضًا من نيكاراغوا والإكوادور؛ ويصنّفه أحد الباعة على أنه نيكاراغوي، وآخر على أنه دومينيكي، بحسب Premium Cigar of the Month Club وthecigarstore.com.',
        '[{"name":"Bahia Blu","color":"#A0522D","force":"Medium","wrapper":"Habano (نيكاراغوا)","vitolas":[],"story":"يُلَفّ في إستيلي بنيكاراغوا، غلاف Corojo زيتي على حشوة من إستيلي وخالابا وكونديغا معتَّقة خمس إلى ست سنوات، بحسب Holt''s Cigar وCigarPlace."},{"name":"Bahia Maduro","color":"#4A3728","force":null,"wrapper":"Connecticut Shade broadleaf","vitolas":[],"story":"غلاف داخلي من Olor وحشوة Piloto Cubano دومينيكيَّان، مع تبغ يأتي أيضًا من نيكاراغوا والإكوادور؛ ويذكر بعض الباعة بلد اللف على أنه جمهورية الدومينيكان، ويذكره آخرون على أنه نيكاراغوا."}]')
