-- ── Marca Fina ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Marca Fina',
        'nicaragua',
        'Non précisée — FTAC (Amérique centrale)',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'cigarworld.de « Marca Fina: Buy Cigars » (2026-09-25 : cigares 100% puros faits main, chaque ligne composée de tabacs d''un seul pays ; FTAC, fédération de producteurs qui aide les agriculteurs à obtenir de meilleurs prix et fixe des règles communes ; lignes Panama, République dominicaine, Honduras, Nicaragua, Équateur, Brésil ; tabacs fermentés au moins deux ans) ; starkezigarren.de « Marca Fina Zigarren in aller Vielfalt » (en allemand, 2026-09-25 : Darier & Cleef, de Hambourg, importateur de la marque en Allemagne jusqu''à l''Intertabac 2024, remplacé depuis par Kopp Tobacco ; Heute werden Marca Fina Zigarren in Nicaragua gerollt : la page situe le roulage au Nicaragua ; FTAC, union de petits producteurs qui transforment une partie de leur récolte en cigares) ; noblego.de « Marca Fina Panama Corona Maduro » (en allemand, 2026-09-25 : cape, sous-cape et tripe panaméennes, cape maduro, profil moyen aux notes herbacées et épicées ; la FTAC y est décrite comme une union de petits producteurs indépendants) ; noblego.de « Marca Fina Honduras Zigarren » (en allemand, 2026-09-25 : cape, sous-cape et tripe honduriennes, force medium, notes relevées, épicées et terreuses, cèdre) ; cigarworld.de « Marca Fina Dominicana » (2026-09-25 : puro dominicain, profil plutôt doux et légèrement aromatique, arôme fruité) ; cigarworld.de « Marca Fina Nicaragua » (2026-09-25 : totalement fait main, TAF, force autour de la moyenne) ; cigarworld.de « Marca Fina Ecuador » (2026-09-25 : totalement fait main, TAF, six variantes) ; zigarrenversand.ch « Marca Fina Brasil » (2026-09-25 : cape brésilienne de couleur maduro, notes de chocolat, de café, de crème, de terre, de cuir, sucrées et boisées) ; cigarworld.de « Marca Fina Zigarillos » (2026-09-25 : cigarillos faits à la machine, 100% tabac panaméen, série lancée le 15 septembre 2009, fabricant FTAC)',
        NULL,
        'Marca Fina est la marque de cigares de la FTAC (Federación de Tabaqueros America Central), qui réunit de petits producteurs de tabac d''Amérique centrale pour qu''ils transforment eux-mêmes une partie de leur récolte en cigares et la vendent, disent Cigarworld.de et StarkeZigarren.de ; la maison ne nomme ni fondateur ni année de création. Chaque ligne est un puro : cape, sous-cape et tripe viennent du même pays, après une fermentation d''au moins deux ans. La ligne Panama est la ligne d''origine ; s''y sont ajoutées des lignes de République dominicaine, du Honduras, du Nicaragua, d''Équateur et du Brésil. En septembre 2026, StarkeZigarren.de dit les cigares roulés au Nicaragua ; la maison ne nomme pas sa fabrique. En Allemagne, la marque a longtemps été importée par Darier & Cleef, de Hambourg, remplacé depuis l''Intertabac 2024 par Kopp Tobacco. Un Zigarillo Marca Fina, fait à la machine à partir de tabac panaméen, est en vente depuis le 15 septembre 2009, dit Cigarworld.de.

Les lignes se distinguent par leurs tabacs : cape maduro au profil moyen, herbacé et épicé, pour le Panama ; profil moyen, plus relevé et terreux, pour le Honduras ; profil plutôt doux et fruité pour la République dominicaine ; cape maduro aux notes de chocolat et de cuir pour le Brésil ; les lignes Nicaragua et Équateur sont entièrement faites main (TAF), la maison n''en publie pas la cape. Toutes restent en vente en septembre 2026 chez Cigarworld.de et Noblego.',
        '[{"name":"Marca Fina Panama","color":"#4A3728","force":"Medium","wrapper":"Maduro (Panama)","vitolas":[],"story":"Puro panaméen (cape, sous-cape et tripe du pays), aux notes herbacées et épicées, dit Noblego."},{"name":"Marca Fina Nicaragua","color":"#A0522D","force":"Medium","wrapper":"Nicaraguayenne","vitolas":[],"story":"Puro nicaraguayen totalement fait main (TAF), dit Cigarworld.de."},{"name":"Marca Fina Dominicana","color":"#C9A96E","force":"Mild","wrapper":"Dominicaine","vitolas":[],"story":"Puro dominicain, plutôt doux, à l''arôme fruité, dit Cigarworld.de."},{"name":"Marca Fina Honduras","color":"#8B5A2B","force":"Medium","wrapper":"Hondurienne","vitolas":[],"story":"Puro hondurien, aux notes terreuses et épicées, avec une fraîcheur de cèdre, dit Noblego."},{"name":"Marca Fina Ecuador","color":"#A0522D","force":null,"wrapper":"Équatorienne","vitolas":[],"story":"Puro équatorien totalement fait main (TAF), dit Cigarworld.de."},{"name":"Marca Fina Brasil","color":"#4A3728","force":null,"wrapper":"Brésilienne, maduro","vitolas":[],"story":"Puro brésilien à cape maduro, aux notes de chocolat, de café et de cuir, dit zigarrenversand.ch."}]',
        'Marca Fina is the cigar brand of the FTAC (Federación de Tabaqueros America Central), which brings together small tobacco growers from Central America so that they can themselves turn part of their harvest into cigars and sell it, say Cigarworld.de and StarkeZigarren.de; the house names neither a founder nor a year of creation. Each line is a puro: wrapper, binder and filler come from the same country, after a fermentation of at least two years. The Panama line is the original one; lines from the Dominican Republic, Honduras, Nicaragua, Ecuador and Brazil were added later. In September 2026, StarkeZigarren.de says the cigars are rolled in Nicaragua; the house does not name its factory. In Germany, the brand was for a long time imported by Darier & Cleef, of Hamburg, replaced since Intertabac 2024 by Kopp Tobacco. A Marca Fina Zigarillo, machine-made from Panamanian tobacco, has been on sale since 15 September 2009, says Cigarworld.de.

The lines differ by their tobaccos: a maduro wrapper with a medium, herbal and spicy profile for Panama; a medium profile, spicier and earthier, for Honduras; a rather mild and fruity profile for the Dominican Republic; a maduro wrapper with notes of chocolate and leather for Brazil; the Nicaragua and Ecuador lines are entirely handmade (TAF), and the house does not publish their wrapper. All remain on sale in September 2026 at Cigarworld.de and Noblego.',
        '[{"name":"Marca Fina Panama","color":"#4A3728","force":"Medium","wrapper":"Maduro (Panama)","vitolas":[],"story":"Panamanian puro (wrapper, binder and filler all from the country), with herbal and spicy notes, says Noblego."},{"name":"Marca Fina Nicaragua","color":"#A0522D","force":"Medium","wrapper":"Nicaraguan","vitolas":[],"story":"Nicaraguan puro, entirely handmade (TAF), says Cigarworld.de."},{"name":"Marca Fina Dominicana","color":"#C9A96E","force":"Mild","wrapper":"Dominican","vitolas":[],"story":"Dominican puro, rather mild, with a fruity aroma, says Cigarworld.de."},{"name":"Marca Fina Honduras","color":"#8B5A2B","force":"Medium","wrapper":"Honduran","vitolas":[],"story":"Honduran puro, with earthy and spicy notes, with a cedar freshness, says Noblego."},{"name":"Marca Fina Ecuador","color":"#A0522D","force":null,"wrapper":"Ecuadorian","vitolas":[],"story":"Ecuadorian puro, entirely handmade (TAF), says Cigarworld.de."},{"name":"Marca Fina Brasil","color":"#4A3728","force":null,"wrapper":"Brazilian, maduro","vitolas":[],"story":"Brazilian puro with a maduro wrapper, with notes of chocolate, coffee and leather, says zigarrenversand.ch."}]',
        'Marca Fina es la marca de puros de la FTAC (Federación de Tabaqueros America Central), que reúne a pequeños productores de tabaco de Centroamérica para que ellos mismos transformen parte de su cosecha en puros y los vendan, según Cigarworld.de y StarkeZigarren.de; la casa no nombra fundador ni año de creación. Cada línea es un puro: capa, capote y tripa proceden del mismo país, tras una fermentación de al menos dos años. La línea de Panamá es la línea original; a ella se han sumado líneas de República Dominicana, Honduras, Nicaragua, Ecuador y Brasil. En septiembre de 2026, StarkeZigarren.de dice que los puros se lían en Nicaragua; la casa no nombra su fábrica. En Alemania, la marca fue durante mucho tiempo importada por Darier & Cleef, de Hamburgo, sustituido desde Intertabac 2024 por Kopp Tobacco. Un Zigarillo Marca Fina, hecho a máquina con tabaco panameño, está a la venta desde el 15 de septiembre de 2009, según Cigarworld.de.

Las líneas se distinguen por sus tabacos: capa maduro de perfil medio, herbáceo y especiado, para Panamá; perfil medio, más picante y terroso, para Honduras; perfil más bien suave y afrutado para República Dominicana; capa maduro con notas de chocolate y cuero para Brasil; las líneas Nicaragua y Ecuador están totalmente hechas a mano (TAF), la casa no publica su capa. Todas siguen a la venta en septiembre de 2026 en Cigarworld.de y Noblego.',
        '[{"name":"Marca Fina Panama","color":"#4A3728","force":"Medium","wrapper":"Maduro (Panamá)","vitolas":[],"story":"Puro panameño (capa, capote y tripa del país), con notas herbáceas y especiadas, según Noblego."},{"name":"Marca Fina Nicaragua","color":"#A0522D","force":"Medium","wrapper":"Nicaragüense","vitolas":[],"story":"Puro nicaragüense totalmente hecho a mano (TAF), según Cigarworld.de."},{"name":"Marca Fina Dominicana","color":"#C9A96E","force":"Mild","wrapper":"Dominicana","vitolas":[],"story":"Puro dominicano, más bien suave, de aroma afrutado, según Cigarworld.de."},{"name":"Marca Fina Honduras","color":"#8B5A2B","force":"Medium","wrapper":"Hondureña","vitolas":[],"story":"Puro hondureño, con notas terrosas y especiadas, con un frescor de cedro, según Noblego."},{"name":"Marca Fina Ecuador","color":"#A0522D","force":null,"wrapper":"Ecuatoriana","vitolas":[],"story":"Puro ecuatoriano totalmente hecho a mano (TAF), según Cigarworld.de."},{"name":"Marca Fina Brasil","color":"#4A3728","force":null,"wrapper":"Brasileña, maduro","vitolas":[],"story":"Puro brasileño de capa maduro, con notas de chocolate, café y cuero, según zigarrenversand.ch."}]',
        'Marca Fina ist die Zigarrenmarke der FTAC (Federación de Tabaqueros America Central), die kleine Tabakerzeuger Mittelamerikas zusammenbringt, damit sie selbst einen Teil ihrer Ernte zu Zigarren verarbeiten und verkaufen, so Cigarworld.de und StarkeZigarren.de; das Haus nennt weder Gründer noch Gründungsjahr. Jede Linie ist ein Puro: Deckblatt, Umblatt und Einlagetabak stammen aus demselben Land, nach einer Fermentation von mindestens zwei Jahren. Die Linie Panama ist die ursprüngliche Linie; hinzu kamen Linien aus der Dominikanischen Republik, Honduras, Nicaragua, Ecuador und Brasilien. Im September 2026 gibt StarkeZigarren.de an, die Zigarren würden in Nicaragua gerollt; das Haus nennt seine Fabrik nicht. In Deutschland wurde die Marke lange von Darier & Cleef aus Hamburg importiert, seit der Intertabac 2024 abgelöst von Kopp Tobacco. Ein Zigarillo Marca Fina, maschinell aus panamaischem Tabak gefertigt, ist seit dem 15. September 2009 im Verkauf, so Cigarworld.de.

Die Linien unterscheiden sich durch ihre Tabake: ein Maduro-Deckblatt mit mittlerem, krautigem und würzigem Profil für Panama; ein mittleres, würzigeres und erdigeres Profil für Honduras; ein eher mildes und fruchtiges Profil für die Dominikanische Republik; ein Maduro-Deckblatt mit Noten von Schokolade und Leder für Brasilien; die Linien Nicaragua und Ecuador sind vollständig handgefertigt (TAF), das Haus gibt ihr Deckblatt nicht bekannt. Alle sind im September 2026 weiterhin bei Cigarworld.de und Noblego erhältlich.',
        '[{"name":"Marca Fina Panama","color":"#4A3728","force":"Medium","wrapper":"Maduro (Panama)","vitolas":[],"story":"Panamaischer Puro (Deckblatt, Umblatt und Einlagetabak aus dem Land), mit krautigen und würzigen Noten, so Noblego."},{"name":"Marca Fina Nicaragua","color":"#A0522D","force":"Medium","wrapper":"Nicaraguanisch","vitolas":[],"story":"Nicaraguanischer Puro, vollständig handgefertigt (TAF), so Cigarworld.de."},{"name":"Marca Fina Dominicana","color":"#C9A96E","force":"Mild","wrapper":"Dominikanisch","vitolas":[],"story":"Dominikanischer Puro, eher mild, mit fruchtigem Aroma, so Cigarworld.de."},{"name":"Marca Fina Honduras","color":"#8B5A2B","force":"Medium","wrapper":"Honduranisch","vitolas":[],"story":"Honduranischer Puro, mit erdigen und würzigen Noten, mit einer Frische von Zeder, so Noblego."},{"name":"Marca Fina Ecuador","color":"#A0522D","force":null,"wrapper":"Ecuadorianisch","vitolas":[],"story":"Ecuadorianischer Puro, vollständig handgefertigt (TAF), so Cigarworld.de."},{"name":"Marca Fina Brasil","color":"#4A3728","force":null,"wrapper":"Brasilianisch, Maduro","vitolas":[],"story":"Brasilianischer Puro mit Maduro-Deckblatt, mit Noten von Schokolade, Kaffee und Leder, so zigarrenversand.ch."}]',
        '据Cigarworld.de与StarkeZigarren.de介绍，Marca Fina是FTAC（Federación de Tabaqueros America Central）旗下的雪茄品牌，该联合会集合了中美洲的小烟农，让他们自行将部分收成加工成雪茄并销售；厂方未透露创始人或创立年份。每条产品线都是puro：茄衣、茄套与茄芯均产自同一国家，经至少两年的发酵。巴拿马系列是其最初的产品线；此后又陆续加入了多米尼加共和国、洪都拉斯、尼加拉瓜、厄瓜多尔与巴西的产品线。截至2026年9月，据StarkeZigarren.de介绍，雪茄在尼加拉瓜卷制；厂方并未说明其工厂所在。在德国，该品牌长期由汉堡的Darier & Cleef代理进口，自2024年Intertabac展会后改由Kopp Tobacco接手。据Cigarworld.de介绍，一款以巴拿马烟叶机制而成的Marca Fina Zigarillo，自2009年9月15日起开始销售。

各产品线以所用烟叶区分：巴拿马为maduro茄衣，风味适中，带草本与辛香；洪都拉斯风味适中，更为浓烈并带泥土气息；多米尼加共和国风味偏柔和，带果香；巴西为maduro茄衣，带可可与皮革香气；尼加拉瓜与厄瓜多尔两条产品线为全手工制作（TAF），厂方未公布其茄衣。截至2026年9月，以上产品均在Cigarworld.de与Noblego有售。',
        '[{"name":"Marca Fina Panama","color":"#4A3728","force":"Medium","wrapper":"Maduro（巴拿马）","vitolas":[],"story":"巴拿马puro（茄衣、茄套与茄芯均产自本国），带草本与辛香气息，据Noblego介绍。"},{"name":"Marca Fina Nicaragua","color":"#A0522D","force":"Medium","wrapper":"尼加拉瓜产","vitolas":[],"story":"尼加拉瓜puro，全手工制作（TAF），据Cigarworld.de介绍。"},{"name":"Marca Fina Dominicana","color":"#C9A96E","force":"Mild","wrapper":"多米尼加产","vitolas":[],"story":"多米尼加puro，风味偏柔和，带果香，据Cigarworld.de介绍。"},{"name":"Marca Fina Honduras","color":"#8B5A2B","force":"Medium","wrapper":"洪都拉斯产","vitolas":[],"story":"洪都拉斯puro，带泥土与辛香气息，并有雪松般的清新感，据Noblego介绍。"},{"name":"Marca Fina Ecuador","color":"#A0522D","force":null,"wrapper":"厄瓜多尔产","vitolas":[],"story":"厄瓜多尔puro，全手工制作（TAF），据Cigarworld.de介绍。"},{"name":"Marca Fina Brasil","color":"#4A3728","force":null,"wrapper":"巴西产，maduro","vitolas":[],"story":"巴西puro，maduro茄衣，带可可、咖啡与皮革香气，据zigarrenversand.ch介绍。"}]',
        'بحسب Cigarworld.de وStarkeZigarren.de، فإن Marca Fina هي علامة السيجار التابعة لـFTAC (Federación de Tabaqueros America Central)، التي تجمع صغار مزارعي التبغ في أمريكا الوسطى ليحوّلوا بأنفسهم جزءًا من محصولهم إلى سيجار ويبيعوه؛ ولا تسمّي الدار مؤسِّسًا ولا سنة تأسيس. وكل خط هو puro: يأتي الغلاف والغلاف الداخلي والحشوة من البلد نفسه، بعد تخمير لا يقلّ عن سنتين. وخط بنما هو الخط الأصلي للعلامة؛ ثم أُضيفت إليه خطوط من جمهورية الدومينيكان وهندوراس ونيكاراغوا والإكوادور والبرازيل. وفي سبتمبر 2026، تقول StarkeZigarren.de إن السيجار يُلَفّ في نيكاراغوا؛ ولا تسمّي الدار مصنعها. وفي ألمانيا، استوردت العلامةَ لفترة طويلة دارُ Darier & Cleef من هامبورغ، قبل أن تحلّ محلّها منذ Intertabac 2024 دارُ Kopp Tobacco. وبحسب Cigarworld.de، يُباع منذ 15 سبتمبر 2009 نوع Zigarillo من Marca Fina، مصنوع آليًا من تبغ بنمي.

وتتمايز الخطوط بأنواع تبغها: غلاف maduro بملمح متوسط، عشبي وحِرّيف، لخط بنما؛ وملمح متوسط، أشدّ حدّةً وترابةً، لخط هندوراس؛ وملمح أميل إلى الخفّة مع نكهة فاكهية لخط جمهورية الدومينيكان؛ وغلاف maduro بنكهتَي الشوكولاتة والجلد لخط البرازيل؛ وخطّا نيكاراغوا والإكوادور مصنوعان بالكامل يدويًا (TAF)، ولا تنشر الدار غلافهما. وتبقى جميعها معروضة في سبتمبر 2026 لدى Cigarworld.de وNoblego.',
        '[{"name":"Marca Fina Panama","color":"#4A3728","force":"Medium","wrapper":"Maduro (بنما)","vitolas":[],"story":"puro بنمي (الغلاف والغلاف الداخلي والحشوة كلها من البلد نفسه)، بنكهات عشبية وحِرّيفة، بحسب Noblego."},{"name":"Marca Fina Nicaragua","color":"#A0522D","force":"Medium","wrapper":"نيكاراغوي","vitolas":[],"story":"puro نيكاراغوي مصنوع بالكامل يدويًا (TAF)، بحسب Cigarworld.de."},{"name":"Marca Fina Dominicana","color":"#C9A96E","force":"Mild","wrapper":"دومينيكي","vitolas":[],"story":"puro دومينيكي، أميل إلى الخفّة، بنكهة فاكهية، بحسب Cigarworld.de."},{"name":"Marca Fina Honduras","color":"#8B5A2B","force":"Medium","wrapper":"هندوراسي","vitolas":[],"story":"puro هندوراسي، بنكهات ترابية وحِرّيفة، مع نفحة انتعاش من خشب الأرز، بحسب Noblego."},{"name":"Marca Fina Ecuador","color":"#A0522D","force":null,"wrapper":"إكوادوري","vitolas":[],"story":"puro إكوادوري مصنوع بالكامل يدويًا (TAF)، بحسب Cigarworld.de."},{"name":"Marca Fina Brasil","color":"#4A3728","force":null,"wrapper":"برازيلي، maduro","vitolas":[],"story":"puro برازيلي بغلاف maduro، بنكهات الشوكولاتة والقهوة والجلد، بحسب zigarrenversand.ch."}]')
