-- ── Horacio ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Horacio',
        'nicaragua',
        '2008 ou 2006 — trois amis, Genève (Suisse)',
        'Estelí, Nicaragua — la maison ne nomme pas sa fabrique',
        'casagranda-cigars.de « Horacio » (consulté le 25/09/2026 : fondation en 2008 au Costa Rica par trois amis, production déplacée à Estelí, Nicaragua, liste des lignes du catalogue, fabrique non nommée) ; cigarworld.de « Horacio: Buy Cigars » (consulté le 25/09/2026 : fondation en Suisse en 2008 par Christophe Leroy, Fabien Gil et Sylvain Toaldo, production à Estelí, liste des lignes) ; houseofgrauer.com « Horacio Classic Series » (consulté le 25/09/2026 : fondation datée 2006, rôles des trois fondateurs, cape équatorienne colorado, sous-cape costaricaine et tripe nicaraguayenne de la Classic Series) ; houseofgrauer.com « Horacio Heritage » (consulté le 25/09/2026 : cape équatorienne maduro, sous-cape costaricaine, tripe Nicaragua et Costa Rica, force medium) ; en.horacio-distribution.com « La minute Horacio — épisode 1 » (consulté le 25/09/2026 : site officiel de la maison, fondation 2008, trois fondateurs nommés, fabrique non nommée) ; zigarrenversand.ch « Horacio OX cigars » (consulté le 25/09/2026 : cape équatorienne maduro, sous-cape et tripe nicaraguayennes, quatre modules lancés en 2017) ; zigarrenversand.ch « Horacio Maduro cigars » (consulté le 25/09/2026 : cape équatorienne maduro sombre et huileuse, force medium, cinq formats) ; zigarrenversand.ch « Horacio Edicion Especial cigars » (consulté le 25/09/2026 : cape colorado maduro, origine variant entre Mexique et Nicaragua selon les formats, tripe longue du Nicaragua)',
        NULL,
        'Christophe Leroy, Fabien Gil et Sylvain Toaldo, trois amis, fondent Horacio en 2008 selon la maison, Cigarworld.de et Casagranda (2006 selon House of Grauer) : le projet naît d''un voyage au Costa Rica, où les premiers cigares sont roulés, avant que la production ne s''installe à Estelí, au Nicaragua. La société Horacio Distribution SA a son siège à Genève, en Suisse ; Christophe Leroy et Fabien Gil suivent la production au Nicaragua, Sylvain Toaldo la distribution, dit House of Grauer. En Allemagne, c''est Casagranda qui distribue la marque. La maison ne nomme pas la fabrique d''Estelí qui roule ses cigares.

En septembre 2026, le catalogue compte une dizaine de séries en longfiller, roulées à la main à Estelí. La Classic, en neuf vitoles numérotées de 0 à VIII, porte une cape équatorienne colorado sur une sous-cape costaricaine et une tripe nicaraguayenne, dit House of Grauer ; la Heritage associe une cape équatorienne maduro à une tripe mêlant Nicaragua et Costa Rica. La Maduro Series et l''Edición Especial déclinent une cape équatorienne ou colorado maduro selon les formats — l''origine de cette dernière variant, dit Zigarrenversand.ch, entre Mexique et Nicaragua selon la vitole. L''OX, lancée en 2017, réunit quatre modules — Black Angel, Blue Velvet, Purple Rain, Red Rock — en cape équatorienne maduro, sous-cape et tripe nicaraguayennes. Une série Esteli Club, en mixed-filler, complète l''offre.',
        '[{"name":"Classic","color":"#A0522D","force":"Medium-Full","wrapper":"Équateur, Colorado","vitolas":[],"story":"Cape Équateur Colorado, sous-cape du Costa Rica et tripe du Nicaragua, en neuf vitoles numérotées de 0 à VIII, dit House of Grauer."},{"name":"Heritage","color":"#6B4226","force":"Medium","wrapper":"Équateur, Maduro","vitolas":[],"story":"Cape Équateur Maduro sombre et huileuse, sous-cape du Costa Rica et tripe mêlant Nicaragua et Costa Rica, dit House of Grauer."},{"name":"Maduro Series","color":"#4A3728","force":"Medium","wrapper":"Équateur, Maduro","vitolas":[],"story":"Cape Équateur Maduro sombre et huileuse, tripe du Nicaragua, en cinq formats du H8 au H0, dit Zigarrenversand.ch."},{"name":"Edición Especial","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Cape colorado maduro dont l''origine varie, dit Zigarrenversand.ch, entre Mexique et Nicaragua selon les formats ; tripe longue du Nicaragua, en cinq formats du Gordito au Super Gordo, en force medium à corsée selon la vitole."},{"name":"OX","color":"#6B4226","force":"Medium-Full","wrapper":"Équateur, Maduro","vitolas":[],"story":"Cape Équateur Maduro, sous-cape et tripe du Nicaragua, en quatre modules — Black Angel, Blue Velvet, Purple Rain, Red Rock —, lancés en 2017, dit Zigarrenversand.ch."}]',
        'Christophe Leroy, Fabien Gil and Sylvain Toaldo, three friends, founded Horacio in 2008 according to the house, Cigarworld.de and Casagranda (2006 according to House of Grauer): the project grew out of a trip to Costa Rica, where the first cigars were rolled, before production moved to Estelí, in Nicaragua. Horacio Distribution SA is headquartered in Geneva, Switzerland; Christophe Leroy and Fabien Gil oversee production in Nicaragua, and Sylvain Toaldo the distribution, says House of Grauer. In Germany, it is Casagranda that distributes the brand. The house does not name the Estelí factory that rolls its cigars.

As of September 2026, the catalogue counts around ten longfiller series, hand-rolled in Estelí. The Classic, in nine vitolas numbered 0 to VIII, carries an Ecuadorian colorado wrapper over a Costa Rican binder and a Nicaraguan filler, says House of Grauer; the Heritage pairs an Ecuadorian maduro wrapper with a filler blending Nicaragua and Costa Rica. The Maduro Series and the Edición Especial come in either an Ecuadorian or a colorado maduro wrapper depending on the size — the origin of the latter varying, says Zigarrenversand.ch, between Mexico and Nicaragua depending on the vitola. The OX, launched in 2017, brings together four modules — Black Angel, Blue Velvet, Purple Rain, Red Rock — in an Ecuadorian maduro wrapper, with Nicaraguan binder and filler. An Esteli Club series, in mixed-filler, rounds out the range.',
        '[{"name":"Classic","color":"#A0522D","force":"Medium-Full","wrapper":"Ecuador, Colorado","vitolas":[],"story":"Ecuadorian Colorado wrapper, Costa Rican binder and Nicaraguan filler, in nine vitolas numbered 0 to VIII, says House of Grauer."},{"name":"Heritage","color":"#6B4226","force":"Medium","wrapper":"Ecuador, Maduro","vitolas":[],"story":"Dark, oily Ecuadorian Maduro wrapper, Costa Rican binder and a filler blending Nicaragua and Costa Rica, says House of Grauer."},{"name":"Maduro Series","color":"#4A3728","force":"Medium","wrapper":"Ecuador, Maduro","vitolas":[],"story":"Dark, oily Ecuadorian Maduro wrapper, Nicaraguan filler, in five sizes from H8 to H0, says Zigarrenversand.ch."},{"name":"Edición Especial","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Colorado maduro wrapper whose origin varies, says Zigarrenversand.ch, between Mexico and Nicaragua depending on the size; long Nicaraguan filler, in five sizes from Gordito to Super Gordo, in medium to full-bodied strength depending on the vitola."},{"name":"OX","color":"#6B4226","force":"Medium-Full","wrapper":"Ecuador, Maduro","vitolas":[],"story":"Ecuadorian Maduro wrapper, Nicaraguan binder and filler, in four modules — Black Angel, Blue Velvet, Purple Rain, Red Rock —, launched in 2017, says Zigarrenversand.ch."}]',
        'Christophe Leroy, Fabien Gil y Sylvain Toaldo, tres amigos, fundan Horacio en 2008 según la casa, Cigarworld.de y Casagranda (2006 según House of Grauer): el proyecto nace de un viaje a Costa Rica, donde se lían los primeros puros, antes de que la producción se traslade a Estelí, en Nicaragua. La sociedad Horacio Distribution SA tiene su sede en Ginebra, Suiza; Christophe Leroy y Fabien Gil supervisan la producción en Nicaragua, y Sylvain Toaldo la distribución, según House of Grauer. En Alemania, es Casagranda quien distribuye la marca. La casa no nombra la fábrica de Estelí que elabora sus puros.

En septiembre de 2026, el catálogo reúne una decena de series longfiller, torcidas a mano en Estelí. La Classic, en nueve vitolas numeradas del 0 al VIII, luce una capa ecuatoriana colorado sobre una capote costarricense y una tripa nicaragüense, según House of Grauer; la Heritage combina una capa ecuatoriana maduro con una tripa que mezcla Nicaragua y Costa Rica. La Maduro Series y la Edición Especial presentan una capa ecuatoriana o colorado maduro según los formatos — el origen de esta última varía, según Zigarrenversand.ch, entre México y Nicaragua según la vitola. La OX, lanzada en 2017, reúne cuatro módulos — Black Angel, Blue Velvet, Purple Rain, Red Rock — con capa ecuatoriana maduro, capote y tripa nicaragüenses. Una serie Esteli Club, en mixed-filler, completa la oferta.',
        '[{"name":"Classic","color":"#A0522D","force":"Medium-Full","wrapper":"Ecuador, Colorado","vitolas":[],"story":"Capa Ecuador Colorado, capote de Costa Rica y tripa de Nicaragua, en nueve vitolas numeradas del 0 al VIII, según House of Grauer."},{"name":"Heritage","color":"#6B4226","force":"Medium","wrapper":"Ecuador, Maduro","vitolas":[],"story":"Capa Ecuador Maduro oscura y aceitosa, capote de Costa Rica y tripa que mezcla Nicaragua y Costa Rica, según House of Grauer."},{"name":"Maduro Series","color":"#4A3728","force":"Medium","wrapper":"Ecuador, Maduro","vitolas":[],"story":"Capa Ecuador Maduro oscura y aceitosa, tripa de Nicaragua, en cinco formatos del H8 al H0, según Zigarrenversand.ch."},{"name":"Edición Especial","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Capa colorado maduro cuyo origen varía, según Zigarrenversand.ch, entre México y Nicaragua según los formatos; tripa larga de Nicaragua, en cinco formatos del Gordito al Super Gordo, en fuerza medium a fuerte según la vitola."},{"name":"OX","color":"#6B4226","force":"Medium-Full","wrapper":"Ecuador, Maduro","vitolas":[],"story":"Capa Ecuador Maduro, capote y tripa de Nicaragua, en cuatro módulos — Black Angel, Blue Velvet, Purple Rain, Red Rock —, lanzados en 2017, según Zigarrenversand.ch."}]',
        'Christophe Leroy, Fabien Gil und Sylvain Toaldo, drei Freunde, gründen Horacio 2008 laut dem Haus, Cigarworld.de und Casagranda (2006 laut House of Grauer): Das Projekt entsteht aus einer Reise nach Costa Rica, wo die ersten Zigarren gerollt werden, bevor die Produktion nach Estelí, Nicaragua, verlagert wird. Die Horacio Distribution SA hat ihren Sitz in Genf, Schweiz; Christophe Leroy und Fabien Gil betreuen die Produktion in Nicaragua, Sylvain Toaldo den Vertrieb, so House of Grauer. In Deutschland vertreibt Casagranda die Marke. Das Haus nennt die Fabrik in Estelí, die seine Zigarren rollt, nicht namentlich.

Im September 2026 umfasst das Sortiment rund zehn Longfiller-Serien, die in Estelí von Hand gerollt werden. Die Classic, in neun Vitolen von 0 bis VIII nummeriert, trägt ein ecuadorianisches Colorado-Deckblatt über einem costa-ricanischen Umblatt und einer nicaraguanischen Einlage, so House of Grauer; die Heritage verbindet ein ecuadorianisches Maduro-Deckblatt mit einer Einlage aus Nicaragua und Costa Rica. Die Maduro Series und die Edición Especial variieren je nach Format zwischen einem ecuadorianischen und einem Colorado-Maduro-Deckblatt — dessen Herkunft laut Zigarrenversand.ch je nach Vitole zwischen Mexiko und Nicaragua wechselt. Die OX, 2017 lanciert, vereint vier Module — Black Angel, Blue Velvet, Purple Rain, Red Rock — mit ecuadorianischem Maduro-Deckblatt sowie nicaraguanischem Umblatt und nicaraguanischer Einlage. Eine Serie Esteli Club, im Mixed-Filler-Verfahren, ergänzt das Angebot.',
        '[{"name":"Classic","color":"#A0522D","force":"Medium-Full","wrapper":"Ecuador, Colorado","vitolas":[],"story":"Ecuador-Colorado-Deckblatt, Umblatt aus Costa Rica und Einlage aus Nicaragua, in neun Vitolen von 0 bis VIII, so House of Grauer."},{"name":"Heritage","color":"#6B4226","force":"Medium","wrapper":"Ecuador, Maduro","vitolas":[],"story":"Dunkles, öliges Ecuador-Maduro-Deckblatt, Umblatt aus Costa Rica und eine Einlage aus Nicaragua und Costa Rica, so House of Grauer."},{"name":"Maduro Series","color":"#4A3728","force":"Medium","wrapper":"Ecuador, Maduro","vitolas":[],"story":"Dunkles, öliges Ecuador-Maduro-Deckblatt, Einlage aus Nicaragua, in fünf Formaten von H8 bis H0, so Zigarrenversand.ch."},{"name":"Edición Especial","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Colorado-Maduro-Deckblatt, dessen Herkunft laut Zigarrenversand.ch je nach Format zwischen Mexiko und Nicaragua wechselt; lange Nicaragua-Einlage, in fünf Formaten vom Gordito bis zum Super Gordo, in der Stärke medium bis kräftig je nach Vitole."},{"name":"OX","color":"#6B4226","force":"Medium-Full","wrapper":"Ecuador, Maduro","vitolas":[],"story":"Ecuador-Maduro-Deckblatt, Umblatt und Einlage aus Nicaragua, in vier Modulen — Black Angel, Blue Velvet, Purple Rain, Red Rock —, 2017 lanciert, so Zigarrenversand.ch."}]',
        'Christophe Leroy、Fabien Gil和Sylvain Toaldo三位好友于2008年创立了Horacio——这是该品牌、Cigarworld.de与Casagranda的说法（House of Grauer则称为2006年）：项目缘起于一次前往哥斯达黎加的旅行，最初的雪茄即在当地手工卷制，其后生产迁至尼加拉瓜的埃斯特利。Horacio Distribution SA总部设于瑞士日内瓦；据House of Grauer介绍，Christophe Leroy与Fabien Gil负责尼加拉瓜的生产，Sylvain Toaldo负责分销。在德国，品牌由Casagranda经销。该品牌未透露在埃斯特利为其卷制雪茄的工厂名称。

截至2026年9月，该品牌产品线约有十个longfiller系列，均在埃斯特利手工卷制。Classic系列共九款规格，编号从0到VIII，采用厄瓜多尔colorado茄衣，配哥斯达黎加茄套与尼加拉瓜茄芯，据House of Grauer介绍；Heritage系列则将厄瓜多尔maduro茄衣与融合尼加拉瓜和哥斯达黎加烟叶的茄芯搭配。Maduro Series与Edición Especial因规格不同分别采用厄瓜多尔茄衣或colorado maduro茄衣——据Zigarrenversand.ch介绍，后者的产地按规格在墨西哥与尼加拉瓜之间变化。2017年推出的OX系列集合四款产品——Black Angel、Blue Velvet、Purple Rain、Red Rock——均为厄瓜多尔maduro茄衣，配尼加拉瓜茄套与茄芯。另有采用mixed-filler工艺的Esteli Club系列，完善产品线。',
        '[{"name":"Classic","color":"#A0522D","force":"Medium-Full","wrapper":"厄瓜多尔，Colorado","vitolas":[],"story":"厄瓜多尔colorado茄衣，哥斯达黎加茄套，尼加拉瓜茄芯，共九款规格，编号0至VIII，据House of Grauer介绍。"},{"name":"Heritage","color":"#6B4226","force":"Medium","wrapper":"厄瓜多尔，Maduro","vitolas":[],"story":"厄瓜多尔maduro茄衣，色泽深沉、油润，哥斯达黎加茄套，茄芯融合尼加拉瓜与哥斯达黎加烟叶，据House of Grauer介绍。"},{"name":"Maduro Series","color":"#4A3728","force":"Medium","wrapper":"厄瓜多尔，Maduro","vitolas":[],"story":"厄瓜多尔maduro茄衣，色泽深沉、油润，尼加拉瓜茄芯，共五款规格，从H8到H0，据Zigarrenversand.ch介绍。"},{"name":"Edición Especial","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"colorado maduro茄衣，据Zigarrenversand.ch介绍，其产地依规格在墨西哥与尼加拉瓜之间变化；尼加拉瓜长茄芯，共五款规格，从Gordito到Super Gordo，力度介于medium至浓郁之间，视规格而定。"},{"name":"OX","color":"#6B4226","force":"Medium-Full","wrapper":"厄瓜多尔，Maduro","vitolas":[],"story":"厄瓜多尔maduro茄衣，尼加拉瓜茄套与茄芯，共四个系列——Black Angel、Blue Velvet、Purple Rain、Red Rock——于2017年推出，据Zigarrenversand.ch介绍。"}]',
        'أسّس Christophe Leroy وFabien Gil وSylvain Toaldo، وهم ثلاثة أصدقاء، علامة Horacio عام 2008 بحسب الدار وCigarworld.de وCasagranda (وعام 2006 بحسب House of Grauer): وُلد المشروع من رحلة إلى كوستاريكا، حيث لُفّت أولى السيجارات هناك، قبل أن ينتقل الإنتاج إلى إستيلي في نيكاراغوا. يقع مقر شركة Horacio Distribution SA في جنيف بسويسرا؛ ويتولى Christophe Leroy وFabien Gil متابعة الإنتاج في نيكاراغوا، بينما يتولى Sylvain Toaldo التوزيع، بحسب House of Grauer. وفي ألمانيا، تتولى Casagranda توزيع العلامة. ولا تكشف الدار عن اسم مصنع إستيلي الذي يلفّ سيجارها.

حتى سبتمبر 2026، تضم التشكيلة نحو عشر سلسلات بنظام longfiller، تُلفّ يدويًا في إستيلي. تحمل سلسلة Classic، بتسعة مقاسات مرقّمة من 0 إلى VIII، غلافًا إكوادوريًا من نوع colorado فوق غلاف داخلي من كوستاريكا وحشوة نيكاراغوية، بحسب House of Grauer؛ أما Heritage فتجمع بين غلاف إكوادوري من نوع maduro وحشوة تمزج بين نيكاراغوا وكوستاريكا. وتتنوع سلسلتا Maduro Series وEdición Especial بين غلاف إكوادوري أو colorado maduro بحسب المقاس — إذ يتراوح منشأ هذا الأخير، بحسب Zigarrenversand.ch، بين المكسيك ونيكاراغوا تبعًا للمقاس. وتجمع سلسلة OX، التي أُطلقت عام 2017، أربع وحدات — Black Angel وBlue Velvet وPurple Rain وRed Rock — بغلاف إكوادوري من نوع maduro وغلاف داخلي وحشوة من نيكاراغوا. وتكمل سلسلة Esteli Club، بنظام mixed-filler، هذه التشكيلة.',
        '[{"name":"Classic","color":"#A0522D","force":"Medium-Full","wrapper":"الإكوادور، Colorado","vitolas":[],"story":"غلاف إكوادوري من نوع colorado، وغلاف داخلي من كوستاريكا، وحشوة من نيكاراغوا، بتسعة مقاسات مرقّمة من 0 إلى VIII، بحسب House of Grauer."},{"name":"Heritage","color":"#6B4226","force":"Medium","wrapper":"الإكوادور، Maduro","vitolas":[],"story":"غلاف إكوادوري من نوع maduro، داكن اللون وزيتي الملمس، وغلاف داخلي من كوستاريكا، وحشوة تمزج بين نيكاراغوا وكوستاريكا، بحسب House of Grauer."},{"name":"Maduro Series","color":"#4A3728","force":"Medium","wrapper":"الإكوادور، Maduro","vitolas":[],"story":"غلاف إكوادوري من نوع maduro، داكن اللون وزيتي الملمس، وحشوة من نيكاراغوا، بخمسة مقاسات من H8 إلى H0، بحسب Zigarrenversand.ch."},{"name":"Edición Especial","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"غلاف من نوع colorado maduro يتراوح منشؤه، بحسب Zigarrenversand.ch، بين المكسيك ونيكاراغوا تبعًا للمقاس؛ وحشوة طويلة من نيكاراغوا، بخمسة مقاسات من Gordito إلى Super Gordo، بقوة تتراوح بين medium وقوي بحسب المقاس."},{"name":"OX","color":"#6B4226","force":"Medium-Full","wrapper":"الإكوادور، Maduro","vitolas":[],"story":"غلاف إكوادوري من نوع maduro، وغلاف داخلي وحشوة من نيكاراغوا، بأربع وحدات — Black Angel وBlue Velvet وPurple Rain وRed Rock — أُطلقت عام 2017، بحسب Zigarrenversand.ch."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Ibis ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Ibis',
        'nicaragua',
        'Non précisée — August Schuster, Bünde (Allemagne)',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'cigarworld.de « Ibis: Buy Cigars » (consulté le 25/09/2026 : propriétaire August Schuster, lignes Dominicana, Nicaragua et Honduras avec force et cape, aucune fabrique nommée) ; noblego.de « Ibis Zigarren » (consulté le 25/09/2026 : détail des trois séries — cape, sous-cape, tripe, force, formats —, un variant Ibis Antiguo au Honduras à cape brésilienne, aucun cigarillo de machine) ; schustercigars.de « Über uns » (consulté le 25/09/2026 : site officiel de la maison, fondation 1897 par Hermann Schuster puis enregistrement le 27 septembre 1909 par August Schuster, direction Manfred et Philipp Schuster, quatrième génération associée) ; smokersplanet.de « Generationswechsel bei August Schuster in Bünde » (consulté le 25/09/2026, en allemand : succession de direction fin 2023, Martin Schuster prend la direction, Annemarie et Oliver Schuster mandataires) ; fahr-im-kreis.de « Zigarrenfabrik August Schuster » (consulté le 25/09/2026, en allemand : confirme l''enregistrement de la firme en septembre 1909 par August Schuster) ; starkezigarren.de « Wer ist August Schuster » (consulté le 25/09/2026, en allemand : confirme la fondation en 1909, entreprise aujourd''hui dirigée par la famille Schuster)',
        NULL,
        'Ibis est une marque de la manufacture August Schuster GmbH & Co. KG, à Bünde, en Rhénanie-du-Nord-Westphalie — la même maison qu''Ann-Eks et Canned Heat. La firme qui porte ce nom est établie le 27 septembre 1909 par August Schuster, dit la maison, dans la continuité d''une fabrique ouverte en 1897 par Hermann Schuster. Dirigée par les frères Manfred et Philipp Schuster, elle passe fin 2023 à Martin Schuster, épaulé par Annemarie et Oliver Schuster, selon Smokersplanet.de. La maison ne nomme aucune des fabriques qui roulent Ibis.

En septembre 2026, la marque se décline en trois origines. Ibis Nicaragua réunit tripe et sous-cape nicaraguayennes sous une cape équatorienne Connecticut Shade ; Cigarworld.de la dit corsée, aux arômes terreux et boisés, quand Noblego.de la situe en force medium. Ibis Honduras, à bande verte, assemble tripe, sous-cape et cape du Honduras — des versions Maduro existent, ainsi qu''un Ibis Antiguo à cape brésilienne — pour un profil medium à corsé. Ibis Dominicana, en force mild, mêle tripe Piloto et sous-cape Olor dominicaines à une cape Connecticut d''Équateur.',
        '[{"name":"Ibis Nicaragua","color":"#C9A96E","force":null,"wrapper":"Équateur (Connecticut Shade)","vitolas":[],"story":"Roulée au Nicaragua, tripe et sous-cape nicaraguayennes sous cape équatorienne Connecticut Shade ; Cigarworld.de la dit corsée et terreuse, Noblego.de la situe en force medium."},{"name":"Ibis Honduras","color":"#A0522D","force":"Medium-Full","wrapper":"Honduras","vitolas":[],"story":"Roulée au Honduras, tripe, sous-cape et cape du Honduras, à bande verte, en force medium à corsée ; des déclinaisons Maduro existent, ainsi qu''un Ibis Antiguo à cape brésilienne."},{"name":"Ibis Dominicana","color":"#C9A96E","force":"Mild","wrapper":"Équateur (Connecticut Shade)","vitolas":[],"story":"Roulée en République dominicaine, tripe Piloto et sous-cape Olor dominicaines sous cape équatorienne Connecticut Shade, positionnée en entrée de gamme, dit Cigarworld.de."}]',
        'Ibis is a brand of the August Schuster GmbH & Co. KG factory, in Bünde, North Rhine-Westphalia — the same house as Ann-Eks and Canned Heat. The firm bearing this name was established on 27 September 1909 by August Schuster, says the house, carrying on from a factory opened in 1897 by Hermann Schuster. Led by brothers Manfred and Philipp Schuster, it passed, in late 2023, to Martin Schuster, supported by Annemarie and Oliver Schuster, according to Smokersplanet.de. The house does not name any of the factories that roll Ibis.

As of September 2026, the brand comes in three origins. Ibis Nicaragua brings together Nicaraguan filler and binder under an Ecuadorian Connecticut Shade wrapper; Cigarworld.de calls it full-bodied, with earthy and woody flavours, while Noblego.de places it at medium strength. Ibis Honduras, with a green band, combines Honduran filler, binder and wrapper — Maduro versions exist, as does an Ibis Antiguo with a Brazilian wrapper — for a medium to full-bodied profile. Ibis Dominicana, at mild strength, blends Dominican Piloto filler and Olor binder with an Ecuadorian Connecticut wrapper.',
        '[{"name":"Ibis Nicaragua","color":"#C9A96E","force":null,"wrapper":"Ecuador (Connecticut Shade)","vitolas":[],"story":"Rolled in Nicaragua, Nicaraguan filler and binder under an Ecuadorian Connecticut Shade wrapper; Cigarworld.de calls it full-bodied and earthy, Noblego.de places it at medium strength."},{"name":"Ibis Honduras","color":"#A0522D","force":"Medium-Full","wrapper":"Honduras","vitolas":[],"story":"Rolled in Honduras, Honduran filler, binder and wrapper, with a green band, at medium to full-bodied strength; Maduro variants exist, as does an Ibis Antiguo with a Brazilian wrapper."},{"name":"Ibis Dominicana","color":"#C9A96E","force":"Mild","wrapper":"Ecuador (Connecticut Shade)","vitolas":[],"story":"Rolled in the Dominican Republic, Dominican Piloto filler and Olor binder under an Ecuadorian Connecticut Shade wrapper, positioned as an entry-level smoke, says Cigarworld.de."}]',
        'Ibis es una marca de la fábrica August Schuster GmbH & Co. KG, en Bünde, Renania del Norte-Westfalia — la misma casa que Ann-Eks y Canned Heat. La firma que lleva este nombre se establece el 27 de septiembre de 1909 por August Schuster, según la casa, dando continuidad a una fábrica abierta en 1897 por Hermann Schuster. Dirigida por los hermanos Manfred y Philipp Schuster, pasa a finales de 2023 a manos de Martin Schuster, respaldado por Annemarie y Oliver Schuster, según Smokersplanet.de. La casa no nombra ninguna de las fábricas que elaboran Ibis.

En septiembre de 2026, la marca se presenta en tres orígenes. Ibis Nicaragua reúne tripa y capote nicaragüenses bajo una capa ecuatoriana Connecticut Shade; Cigarworld.de la califica de fuerte, con aromas terrosos y amaderados, mientras que Noblego.de la sitúa en fuerza medium. Ibis Honduras, con anilla verde, combina tripa, capote y capa de Honduras — existen versiones Maduro, así como un Ibis Antiguo con capa brasileña — para un perfil medium a fuerte. Ibis Dominicana, de fuerza mild, mezcla tripa Piloto y capote Olor dominicanos con una capa Connecticut de Ecuador.',
        '[{"name":"Ibis Nicaragua","color":"#C9A96E","force":null,"wrapper":"Ecuador (Connecticut Shade)","vitolas":[],"story":"Elaborada en Nicaragua, tripa y capote nicaragüenses bajo capa ecuatoriana Connecticut Shade; Cigarworld.de la califica de fuerte y terrosa, Noblego.de la sitúa en fuerza medium."},{"name":"Ibis Honduras","color":"#A0522D","force":"Medium-Full","wrapper":"Honduras","vitolas":[],"story":"Elaborada en Honduras, tripa, capote y capa de Honduras, con anilla verde, en fuerza medium a fuerte; existen variantes Maduro, así como un Ibis Antiguo con capa brasileña."},{"name":"Ibis Dominicana","color":"#C9A96E","force":"Mild","wrapper":"Ecuador (Connecticut Shade)","vitolas":[],"story":"Elaborada en República Dominicana, tripa Piloto y capote Olor dominicanos bajo capa ecuatoriana Connecticut Shade, posicionada como puro de entrada, según Cigarworld.de."}]',
        'Ibis ist eine Marke der Fabrik August Schuster GmbH & Co. KG in Bünde, Nordrhein-Westfalen — dasselbe Haus wie Ann-Eks und Canned Heat. Die Firma, die diesen Namen trägt, wird am 27. September 1909 von August Schuster gegründet, so das Haus, in der Fortführung einer 1897 von Hermann Schuster eröffneten Fabrik. Geführt von den Brüdern Manfred und Philipp Schuster, geht sie Ende 2023 an Martin Schuster über, unterstützt von Annemarie und Oliver Schuster, laut Smokersplanet.de. Das Haus nennt keine der Fabriken, die Ibis rollen, namentlich.

Im September 2026 gibt es die Marke in drei Herkünften. Ibis Nicaragua vereint nicaraguanische Einlage und Umblatt unter einem ecuadorianischen Connecticut-Shade-Deckblatt; Cigarworld.de nennt sie kräftig, mit erdigen und holzigen Aromen, während Noblego.de sie bei der Stärke medium ansiedelt. Ibis Honduras, mit grüner Bauchbinde, vereint Einlage, Umblatt und Deckblatt aus Honduras — es gibt Maduro-Versionen sowie eine Ibis Antiguo mit brasilianischem Deckblatt — für ein Profil von medium bis kräftig. Ibis Dominicana, in der Stärke mild, mischt dominikanische Piloto-Einlage und Olor-Umblatt mit einem ecuadorianischen Connecticut-Deckblatt.',
        '[{"name":"Ibis Nicaragua","color":"#C9A96E","force":null,"wrapper":"Ecuador (Connecticut Shade)","vitolas":[],"story":"In Nicaragua gerollt, nicaraguanische Einlage und Umblatt unter ecuadorianischem Connecticut-Shade-Deckblatt; Cigarworld.de nennt sie kräftig und erdig, Noblego.de siedelt sie bei der Stärke medium an."},{"name":"Ibis Honduras","color":"#A0522D","force":"Medium-Full","wrapper":"Honduras","vitolas":[],"story":"In Honduras gerollt, Einlage, Umblatt und Deckblatt aus Honduras, mit grüner Bauchbinde, in der Stärke medium bis kräftig; es gibt Maduro-Varianten sowie eine Ibis Antiguo mit brasilianischem Deckblatt."},{"name":"Ibis Dominicana","color":"#C9A96E","force":"Mild","wrapper":"Ecuador (Connecticut Shade)","vitolas":[],"story":"In der Dominikanischen Republik gerollt, dominikanische Piloto-Einlage und Olor-Umblatt unter ecuadorianischem Connecticut-Shade-Deckblatt, als Einstiegszigarre positioniert, so Cigarworld.de."}]',
        'Ibis是August Schuster GmbH & Co. KG工厂旗下的品牌，位于北莱茵-威斯特法伦的宾德——与Ann-Eks和Canned Heat同属一家。据该品牌介绍，这个名称的公司由August Schuster于1909年9月27日创立，前身是Hermann Schuster于1897年开设的一家工厂。该公司先由Manfred与Philipp Schuster兄弟执掌，据Smokersplanet.de介绍，2023年底交由Martin Schuster接手，并由Annemarie与Oliver Schuster协助。该品牌未透露任何一家卷制Ibis雪茄的工厂名称。

截至2026年9月，该品牌共有三个产地系列。Ibis Nicaragua在厄瓜多尔Connecticut Shade茄衣之下，汇聚尼加拉瓜茄芯与茄套；Cigarworld.de称其浓郁，带有泥土与木质香气，而Noblego.de则将其力度定为medium。Ibis Honduras采用绿色雪茄标，集合洪都拉斯茄芯、茄套与茄衣——另有Maduro版本，以及采用巴西茄衣的Ibis Antiguo——整体风格为medium至浓郁。Ibis Dominicana力度为mild，将多米尼加Piloto茄芯与Olor茄套，配以厄瓜多尔Connecticut茄衣。',
        '[{"name":"Ibis Nicaragua","color":"#C9A96E","force":null,"wrapper":"厄瓜多尔（Connecticut Shade）","vitolas":[],"story":"于尼加拉瓜卷制，尼加拉瓜茄芯与茄套，配厄瓜多尔Connecticut Shade茄衣；Cigarworld.de称其浓郁、带泥土气息，Noblego.de则将其力度定为medium。"},{"name":"Ibis Honduras","color":"#A0522D","force":"Medium-Full","wrapper":"洪都拉斯","vitolas":[],"story":"于洪都拉斯卷制，茄芯、茄套与茄衣均产自洪都拉斯，配绿色雪茄标，力度介于medium至浓郁之间；另有Maduro款式，以及采用巴西茄衣的Ibis Antiguo。"},{"name":"Ibis Dominicana","color":"#C9A96E","force":"Mild","wrapper":"厄瓜多尔（Connecticut Shade）","vitolas":[],"story":"于多米尼加共和国卷制，多米尼加Piloto茄芯与Olor茄套，配厄瓜多尔Connecticut Shade茄衣，定位为入门级雪茄，据Cigarworld.de介绍。"}]',
        'Ibis علامة تابعة لمصنع August Schuster GmbH & Co. KG في بوندِه بإقليم شمال الراين - وستفاليا — وهي الدار نفسها التي تضم Ann-Eks وCanned Heat. أسّس August Schuster الشركة التي تحمل هذا الاسم في 27 سبتمبر 1909، بحسب الدار، استمرارًا لمصنع افتتحه Hermann Schuster عام 1897. وتولى إدارتها الأخوان Manfred وPhilipp Schuster، قبل أن تنتقل في أواخر 2023 إلى Martin Schuster، يعاونه Annemarie وOliver Schuster، وفق Smokersplanet.de. ولا تكشف الدار عن اسم أيٍّ من المصانع التي تلفّ سيجار Ibis.

حتى سبتمبر 2026، تُقدَّم العلامة بثلاثة مناشئ. تجمع Ibis Nicaragua بين حشوة وغلاف داخلي من نيكاراغوا تحت غلاف إكوادوري من نوع Connecticut Shade؛ وتصفها Cigarworld.de بأنها قوية، بنكهات ترابية وخشبية، بينما تضعها Noblego.de عند قوة medium. أما Ibis Honduras، ذات الشريط الأخضر، فتجمع حشوة وغلافًا داخليًا وغلافًا من هندوراس — وتوجد نسخ Maduro، وكذلك طراز Ibis Antiguo بغلاف برازيلي — بقوام يتراوح بين medium وقوي. وتمزج Ibis Dominicana، بقوة mild، بين حشوة Piloto وغلاف داخلي Olor من جمهورية الدومينيكان وغلاف Connecticut من الإكوادور.',
        '[{"name":"Ibis Nicaragua","color":"#C9A96E","force":null,"wrapper":"الإكوادور (Connecticut Shade)","vitolas":[],"story":"تُلفّ في نيكاراغوا، بحشوة وغلاف داخلي من نيكاراغوا تحت غلاف إكوادوري من نوع Connecticut Shade؛ تصفها Cigarworld.de بأنها قوية وترابية النكهة، وتضعها Noblego.de عند قوة medium."},{"name":"Ibis Honduras","color":"#A0522D","force":"Medium-Full","wrapper":"هندوراس","vitolas":[],"story":"تُلفّ في هندوراس، بحشوة وغلاف داخلي وغلاف من هندوراس، بشريط أخضر، بقوة تتراوح بين medium وقوي؛ وتوجد نسخ Maduro، وكذلك طراز Ibis Antiguo بغلاف برازيلي."},{"name":"Ibis Dominicana","color":"#C9A96E","force":"Mild","wrapper":"الإكوادور (Connecticut Shade)","vitolas":[],"story":"تُلفّ في جمهورية الدومينيكان، بحشوة Piloto وغلاف داخلي Olor من جمهورية الدومينيكان تحت غلاف إكوادوري من نوع Connecticut Shade، وتُصنَّف في الفئة التمهيدية، بحسب Cigarworld.de."}]')
