INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Mara',
        'nicaragua',
        'Non précisée — Ricardo Vasquez (Mara Cigars)',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'cigarworld.de « Mara Marabunta » (consulté le 25/09/2026 : Ricardo Vasquez né à Cuba, fabrique Oveja Negra à Estelí citée, cape, sous-cape et tripe du Nicaragua, autres lignes El Sicario, El Corrupto, El Hurón) ; ovejanegracigars.com « Factory » (consulté le 25/09/2026 : la fabrique Oveja Negra, dirigée par James et Angela Brown, liste Black Label Trading Co., Black Works Studio et Emilio Cigars parmi ses marques, sans mentionner Mara) ; cigarworld.de « Mara El Sicario » (consulté le 25/09/2026 : cape Nicaragua Maduro, sous-cape et tripe du Nicaragua, boxpressé, force medium) ; cigarworld.de « Mara El Corrupto » (consulté le 25/09/2026 : cape Connecticut cultivée au Nicaragua, sous-cape et tripe du Nicaragua, force medium) ; cigarworld.de « Mara El Hurón » (consulté le 25/09/2026 : cape Équateur Sungrown, sous-cape et tripe du Nicaragua, arrivée en Allemagne le 28 mai 2024)',
        NULL,
        'Ricardo Vasquez, né à Cuba, grandit dans les champs de tabac et apprend le métier auprès des producteurs du pays avant de fonder Mara Cigars, dit Cigarworld.de ; la maison ne date pas cette fondation. La marque roule ses cigares au Nicaragua. Cigarworld.de attribue sa ligne Marabunta à la fabrique Oveja Negra, à Estelí, que dirigent James et Angela Brown ; Oveja Negra ne cite pas Mara parmi les marques qu''elle roule, et la maison ne nomme pas sa fabrique.

En septembre 2026, le catalogue compte quatre lignes : la Marabunta, cape, sous-cape et tripe du Nicaragua ; l''El Sicario, cape nicaraguayenne maduro, fumée boxpressée ; l''El Corrupto, cape Connecticut cultivée au Nicaragua sur une tripe nicaraguayenne ; et l''El Hurón, arrivée en Allemagne le 28 mai 2024, à la cape équatorienne sungrown. Les noms de la gamme reprennent un vocabulaire de bande organisée, dit Cigarworld.de.',
        '[{"name":"Marabunta","color":"#6B4226","force":"Full","wrapper":"Nicaragua","vitolas":[],"story":"Cape, sous-cape et tripe du Nicaragua ; robuste et corsée dès le premier tiers, dit Cigarworld.de."},{"name":"El Sicario","color":"#4A3728","force":"Medium","wrapper":"Nicaragua, Maduro","vitolas":[],"story":"Cape nicaraguayenne maduro, sous-cape et tripe du Nicaragua, fumée boxpressée, à la force medium, dit Cigarworld.de."},{"name":"El Corrupto","color":"#C9A96E","force":"Medium","wrapper":"Nicaragua, Connecticut","vitolas":[],"story":"Cape Connecticut cultivée au Nicaragua, sous-cape et tripe nicaraguayennes, à la force medium, dit Cigarworld.de."},{"name":"El Hurón","color":"#A0522D","force":null,"wrapper":"Équateur, Sungrown","vitolas":[],"story":"Cape Équateur Sungrown, sous-cape et tripe du Nicaragua, arrivée en Allemagne le 28 mai 2024, dit Cigarworld.de."}]',
        'Ricardo Vasquez, born in Cuba, grew up in the tobacco fields and learnt the trade from the country''s growers before founding Mara Cigars, says Cigarworld.de; the house does not date this founding. The brand rolls its cigars in Nicaragua. Cigarworld.de attributes its Marabunta line to the Oveja Negra factory, in Estelí, run by James and Angela Brown; Oveja Negra does not list Mara among the brands it rolls, and the house does not name its factory.

As of September 2026, the catalogue counts four lines: the Marabunta, Nicaraguan wrapper, binder and filler; the El Sicario, Nicaraguan maduro wrapper, a box-pressed smoke; the El Corrupto, Connecticut wrapper grown in Nicaragua over a Nicaraguan filler; and the El Hurón, which arrived in Germany on 28 May 2024, with an Ecuadorian sungrown wrapper. The names in the range draw on the vocabulary of organised crime, says Cigarworld.de.',
        '[{"name":"Marabunta","color":"#6B4226","force":"Full","wrapper":"Nicaragua","vitolas":[],"story":"Nicaraguan wrapper, binder and filler; robust and full-bodied from the first third, says Cigarworld.de."},{"name":"El Sicario","color":"#4A3728","force":"Medium","wrapper":"Nicaragua, Maduro","vitolas":[],"story":"Nicaraguan maduro wrapper, Nicaraguan binder and filler, a box-pressed smoke, at medium strength, says Cigarworld.de."},{"name":"El Corrupto","color":"#C9A96E","force":"Medium","wrapper":"Nicaragua, Connecticut","vitolas":[],"story":"Connecticut wrapper grown in Nicaragua, Nicaraguan binder and filler, at medium strength, says Cigarworld.de."},{"name":"El Hurón","color":"#A0522D","force":null,"wrapper":"Ecuador, Sungrown","vitolas":[],"story":"Ecuadorian Sungrown wrapper, Nicaraguan binder and filler, arrived in Germany on 28 May 2024, says Cigarworld.de."}]',
        'Ricardo Vasquez, nacido en Cuba, crece en los campos de tabaco y aprende el oficio junto a los productores del país antes de fundar Mara Cigars, según Cigarworld.de; la casa no data esta fundación. La marca elabora sus puros en Nicaragua. Cigarworld.de atribuye su línea Marabunta a la fábrica Oveja Negra, en Estelí, dirigida por James y Angela Brown; Oveja Negra no menciona a Mara entre las marcas que elabora, y la casa no nombra su fábrica.

En septiembre de 2026, el catálogo cuenta con cuatro líneas: la Marabunta, capa, capote y tripa de Nicaragua; la El Sicario, capa nicaragüense maduro, puro box-pressed; la El Corrupto, capa Connecticut cultivada en Nicaragua sobre una tripa nicaragüense; y la El Hurón, llegada a Alemania el 28 de mayo de 2024, con capa ecuatoriana sungrown. Los nombres de la gama retoman un vocabulario de bandas organizadas, según Cigarworld.de.',
        '[{"name":"Marabunta","color":"#6B4226","force":"Full","wrapper":"Nicaragua","vitolas":[],"story":"Capa, capote y tripa de Nicaragua; robusto y fuerte desde el primer tercio, según Cigarworld.de."},{"name":"El Sicario","color":"#4A3728","force":"Medium","wrapper":"Nicaragua, Maduro","vitolas":[],"story":"Capa nicaragüense maduro, capote y tripa de Nicaragua, puro box-pressed, en fuerza medium, según Cigarworld.de."},{"name":"El Corrupto","color":"#C9A96E","force":"Medium","wrapper":"Nicaragua, Connecticut","vitolas":[],"story":"Capa Connecticut cultivada en Nicaragua, capote y tripa nicaragüenses, en fuerza medium, según Cigarworld.de."},{"name":"El Hurón","color":"#A0522D","force":null,"wrapper":"Ecuador, Sungrown","vitolas":[],"story":"Capa Ecuador Sungrown, capote y tripa de Nicaragua, llegada a Alemania el 28 de mayo de 2024, según Cigarworld.de."}]',
        'Ricardo Vasquez, geboren in Kuba, wächst in den Tabakfeldern auf und erlernt das Handwerk bei den Erzeugern des Landes, bevor er Mara Cigars gründet, so Cigarworld.de; das Haus datiert diese Gründung nicht. Die Marke lässt ihre Zigarren in Nicaragua rollen. Cigarworld.de schreibt die Linie Marabunta der Fabrik Oveja Negra in Estelí zu, die von James und Angela Brown geleitet wird; Oveja Negra führt Mara nicht unter den Marken auf, die sie rollt, und das Haus nennt seine Fabrik nicht.

Im September 2026 umfasst das Sortiment vier Linien: die Marabunta mit Deckblatt, Umblatt und Einlage aus Nicaragua; die El Sicario mit nicaraguanischem Maduro-Deckblatt, eine box-pressed Zigarre; die El Corrupto mit einem in Nicaragua angebauten Connecticut-Deckblatt über nicaraguanischer Einlage; und die El Hurón, die am 28. Mai 2024 in Deutschland ankam, mit ecuadorianischem Sungrown-Deckblatt. Die Namen der Reihe greifen ein Vokabular organisierter Banden auf, so Cigarworld.de.',
        '[{"name":"Marabunta","color":"#6B4226","force":"Full","wrapper":"Nicaragua","vitolas":[],"story":"Deckblatt, Umblatt und Einlage aus Nicaragua; kräftig und robust schon im ersten Drittel, so Cigarworld.de."},{"name":"El Sicario","color":"#4A3728","force":"Medium","wrapper":"Nicaragua, Maduro","vitolas":[],"story":"Nicaraguanisches Maduro-Deckblatt, Umblatt und Einlage aus Nicaragua, eine box-pressed Zigarre, in der Stärke medium, so Cigarworld.de."},{"name":"El Corrupto","color":"#C9A96E","force":"Medium","wrapper":"Nicaragua, Connecticut","vitolas":[],"story":"In Nicaragua angebautes Connecticut-Deckblatt, nicaraguanisches Umblatt und Einlage, in der Stärke medium, so Cigarworld.de."},{"name":"El Hurón","color":"#A0522D","force":null,"wrapper":"Ecuador, Sungrown","vitolas":[],"story":"Ecuador-Sungrown-Deckblatt, Umblatt und Einlage aus Nicaragua, am 28. Mai 2024 in Deutschland angekommen, so Cigarworld.de."}]',
        'Ricardo Vasquez生于古巴，自幼在烟草田间长大，师从当地烟农习得手艺，其后创立Mara Cigars，据Cigarworld.de介绍；该品牌并未说明创立的具体年份。该品牌的雪茄在尼加拉瓜卷制。Cigarworld.de将其Marabunta系列归于位于埃斯特利、由James与Angela Brown执掌的Oveja Negra工厂；但Oveja Negra所列的卷制品牌中并未提及Mara，该品牌本身也未透露其工厂名称。

截至2026年9月，产品线共有四个系列：Marabunta，茄衣、茄套与茄芯均产自尼加拉瓜；El Sicario，尼加拉瓜maduro茄衣，为box-pressed雪茄；El Corrupto，尼加拉瓜种植的Connecticut茄衣，配尼加拉瓜茄芯；以及2024年5月28日抵达德国的El Hurón，采用厄瓜多尔sungrown茄衣。据Cigarworld.de介绍，该系列的命名借用了有组织犯罪团伙的词汇。',
        '[{"name":"Marabunta","color":"#6B4226","force":"Full","wrapper":"尼加拉瓜","vitolas":[],"story":"茄衣、茄套与茄芯均产自尼加拉瓜；从前三分之一段起便浓郁强劲，据Cigarworld.de介绍。"},{"name":"El Sicario","color":"#4A3728","force":"Medium","wrapper":"尼加拉瓜，Maduro","vitolas":[],"story":"尼加拉瓜maduro茄衣，尼加拉瓜茄套与茄芯，box-pressed雪茄，力度为medium，据Cigarworld.de介绍。"},{"name":"El Corrupto","color":"#C9A96E","force":"Medium","wrapper":"尼加拉瓜，Connecticut","vitolas":[],"story":"尼加拉瓜种植的Connecticut茄衣，尼加拉瓜茄套与茄芯，力度为medium，据Cigarworld.de介绍。"},{"name":"El Hurón","color":"#A0522D","force":null,"wrapper":"厄瓜多尔，Sungrown","vitolas":[],"story":"厄瓜多尔sungrown茄衣，尼加拉瓜茄套与茄芯，于2024年5月28日抵达德国，据Cigarworld.de介绍。"}]',
        'وُلد Ricardo Vasquez في كوبا، ونشأ بين حقول التبغ، وتعلّم المهنة على يد مزارعي البلاد قبل أن يؤسّس Mara Cigars، بحسب Cigarworld.de؛ ولا تحدّد الدار تاريخ هذا التأسيس. تُلفّ العلامة سيجارها في نيكاراغوا. وتنسب Cigarworld.de سلسلة Marabunta إلى مصنع Oveja Negra في إستيلي، الذي يديره James وAngela Brown؛ غير أن Oveja Negra لا تذكر Mara ضمن العلامات التي تلفّها، كما أن الدار لا تكشف عن اسم مصنعها.

حتى سبتمبر 2026، تضم التشكيلة أربع سلسلات: Marabunta، بغلاف وغلاف داخلي وحشوة من نيكاراغوا؛ وEl Sicario، بغلاف نيكاراغوي من نوع maduro، وهي سيجارة box-pressed؛ وEl Corrupto، بغلاف Connecticut مزروع في نيكاراغوا فوق حشوة نيكاراغوية؛ وEl Hurón، التي وصلت إلى ألمانيا في 28 مايو 2024، بغلاف إكوادوري من نوع sungrown. وتستعير أسماء هذه التشكيلة مفردات من عالم العصابات المنظمة، بحسب Cigarworld.de.',
        '[{"name":"Marabunta","color":"#6B4226","force":"Full","wrapper":"نيكاراغوا","vitolas":[],"story":"غلاف وغلاف داخلي وحشوة من نيكاراغوا؛ قوي ومتين منذ الثلث الأول، بحسب Cigarworld.de."},{"name":"El Sicario","color":"#4A3728","force":"Medium","wrapper":"نيكاراغوا، Maduro","vitolas":[],"story":"غلاف نيكاراغوي من نوع maduro، وغلاف داخلي وحشوة من نيكاراغوا، سيجارة box-pressed، بقوة medium، بحسب Cigarworld.de."},{"name":"El Corrupto","color":"#C9A96E","force":"Medium","wrapper":"نيكاراغوا، Connecticut","vitolas":[],"story":"غلاف Connecticut مزروع في نيكاراغوا، وغلاف داخلي وحشوة نيكاراغويان، بقوة medium، بحسب Cigarworld.de."},{"name":"El Hurón","color":"#A0522D","force":null,"wrapper":"الإكوادور، Sungrown","vitolas":[],"story":"غلاف إكوادوري من نوع Sungrown، وغلاف داخلي وحشوة من نيكاراغوا، وصلت إلى ألمانيا في 28 مايو 2024، بحسب Cigarworld.de."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── May's Cigars ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('May''s Cigars',
        'nicaragua',
        '2018 — Maykelis Ketnath, Stuttgart',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'lacasadetabaco.de « May''s Cigars » (consulté le 25/09/2026 : Maykelis Ketnath, rouleuse cubaine formée à Partagás, passage chez Villiger, cigares roulés au Nicaragua, deux références Short Corona et Liga 1 avec cape, sous-cape, tripe et force) ; noblego.de « May''s Cigars Zigarren » (consulté le 25/09/2026 : plus de vingt ans d''expérience, formation à la manufacture Partagás à La Havane, deux formats Robusto et Short Corona en force medium, fabrique non nommée) ; berichteaktuell.de « Maykelis Ketnath » (consulté le 25/09/2026 : née à Cuba, formation de torcedora à Partagás dans les années 1990, installation en Europe au début des années 2000, collaboration avec la maison Villiger, diplôme d''orfèvre à Pforzheim, fondation de May''s Cigars en 2018 à Stuttgart, ligne de joaillerie MANDORO)',
        NULL,
        'Maykelis Ketnath naît à Cuba et s''y forme, dans les années 1990, comme rouleuse à la manufacture Partagás, à La Havane, dit Berichteaktuell.de ; Noblego.de compte pour elle plus de vingt ans d''expérience dans le cigare. Installée en Europe au début des années 2000, elle collabore avec la maison Villiger, présentant son savoir-faire lors d''événements, avant de fonder May''s Cigars, en 2018, à Stuttgart ; elle obtient en parallèle un diplôme d''orfèvre à l''école de Pforzheim et lance une ligne de joaillerie, MANDORO. Les cigares May''s sont roulés au Nicaragua ; la maison ne nomme pas sa fabrique.

En septembre 2026, le catalogue compte deux références. La Short Corona, en 114 mm pour un cepo 44, porte une cape équatorienne de variété Habano 2000 sur une sous-cape et une tripe du Nicaragua. La Liga 1, en vitole Robusto (127 mm, cepo 50), reprend la même cape équatorienne sur une sous-cape du Pérou et une tripe nicaraguayenne. Les deux sont données en force mild-medium, dit La Casa del Tabaco.',
        '[{"name":"Short Corona","color":"#A0522D","force":"Mild-Medium","wrapper":"Équateur (Habano 2000)","vitolas":[],"story":"Cape Équateur Habano 2000, sous-cape et tripe du Nicaragua, en 114 mm pour un cepo 44, dit La Casa del Tabaco."},{"name":"Liga 1","color":"#A0522D","force":"Mild-Medium","wrapper":"Équateur (Habano 2000)","vitolas":[],"story":"Cape Équateur Habano 2000, sous-cape du Pérou et tripe du Nicaragua, en vitole Robusto (127 mm, cepo 50), dit La Casa del Tabaco."}]',
        'Maykelis Ketnath was born in Cuba and trained there, in the 1990s, as a torcedora at the Partagás factory, in Havana, says Berichteaktuell.de; Noblego.de credits her with more than twenty years of experience in cigars. Settled in Europe in the early 2000s, she worked with the house of Villiger, showcasing her craft at events, before founding May''s Cigars, in 2018, in Stuttgart; she also earned a goldsmithing diploma from the Pforzheim school and launched a jewellery line, MANDORO. May''s cigars are rolled in Nicaragua; the house does not name its factory.

As of September 2026, the catalogue counts two references. The Short Corona, at 114 mm for a cepo 44, carries an Ecuadorian wrapper of the Habano 2000 variety over a Nicaraguan binder and filler. The Liga 1, in a Robusto vitola (127 mm, cepo 50), takes the same Ecuadorian wrapper over a Peruvian binder and a Nicaraguan filler. Both are rated at mild-medium strength, says La Casa del Tabaco.',
        '[{"name":"Short Corona","color":"#A0522D","force":"Mild-Medium","wrapper":"Ecuador (Habano 2000)","vitolas":[],"story":"Ecuadorian Habano 2000 wrapper, Nicaraguan binder and filler, at 114 mm for a cepo 44, says La Casa del Tabaco."},{"name":"Liga 1","color":"#A0522D","force":"Mild-Medium","wrapper":"Ecuador (Habano 2000)","vitolas":[],"story":"Ecuadorian Habano 2000 wrapper, Peruvian binder and Nicaraguan filler, in a Robusto vitola (127 mm, cepo 50), says La Casa del Tabaco."}]',
        'Maykelis Ketnath nace en Cuba y allí se forma, en la década de 1990, como torcedora en la fábrica Partagás, en La Habana, según Berichteaktuell.de; Noblego.de le atribuye más de veinte años de experiencia en el mundo del puro. Instalada en Europa a comienzos de la década de 2000, colabora con la casa Villiger, mostrando su oficio en distintos eventos, antes de fundar May''s Cigars, en 2018, en Stuttgart; obtiene además un título de orfebre en la escuela de Pforzheim y lanza una línea de joyería, MANDORO. Los puros May''s se elaboran en Nicaragua; la casa no nombra su fábrica.

En septiembre de 2026, el catálogo cuenta con dos referencias. La Short Corona, de 114 mm para un cepo 44, luce una capa ecuatoriana de la variedad Habano 2000 sobre un capote y una tripa de Nicaragua. La Liga 1, en vitola Robusto (127 mm, cepo 50), retoma la misma capa ecuatoriana sobre un capote de Perú y una tripa nicaragüense. Ambas se dan en fuerza mild-medium, según La Casa del Tabaco.',
        '[{"name":"Short Corona","color":"#A0522D","force":"Mild-Medium","wrapper":"Ecuador (Habano 2000)","vitolas":[],"story":"Capa Ecuador Habano 2000, capote y tripa de Nicaragua, en 114 mm para un cepo 44, según La Casa del Tabaco."},{"name":"Liga 1","color":"#A0522D","force":"Mild-Medium","wrapper":"Ecuador (Habano 2000)","vitolas":[],"story":"Capa Ecuador Habano 2000, capote de Perú y tripa de Nicaragua, en vitola Robusto (127 mm, cepo 50), según La Casa del Tabaco."}]',
        'Maykelis Ketnath wird auf Kuba geboren und lernt dort in den 1990er Jahren das Handwerk als Torcedora in der Fabrik Partagás in Havanna, so Berichteaktuell.de; Noblego.de rechnet ihr mehr als zwanzig Jahre Erfahrung in der Zigarrenwelt an. Anfang der 2000er Jahre lässt sie sich in Europa nieder, arbeitet mit dem Haus Villiger zusammen und zeigt ihr Können bei Veranstaltungen, bevor sie 2018 in Stuttgart May''s Cigars gründet; parallel erwirbt sie ein Goldschmiede-Diplom an der Schule in Pforzheim und lanciert eine Schmucklinie, MANDORO. Die May''s-Zigarren werden in Nicaragua gerollt; das Haus nennt seine Fabrik nicht.

Im September 2026 umfasst das Sortiment zwei Referenzen. Die Short Corona, 114 mm bei einem cepo 44, trägt ein ecuadorianisches Deckblatt der Sorte Habano 2000 über einem Umblatt und einer Einlage aus Nicaragua. Die Liga 1, in der Vitole Robusto (127 mm, cepo 50), verwendet dasselbe ecuadorianische Deckblatt über einem Umblatt aus Peru und einer nicaraguanischen Einlage. Beide werden mit der Stärke mild-medium angegeben, so La Casa del Tabaco.',
        '[{"name":"Short Corona","color":"#A0522D","force":"Mild-Medium","wrapper":"Ecuador (Habano 2000)","vitolas":[],"story":"Ecuador-Habano-2000-Deckblatt, Umblatt und Einlage aus Nicaragua, 114 mm bei einem cepo 44, so La Casa del Tabaco."},{"name":"Liga 1","color":"#A0522D","force":"Mild-Medium","wrapper":"Ecuador (Habano 2000)","vitolas":[],"story":"Ecuador-Habano-2000-Deckblatt, Umblatt aus Peru und Einlage aus Nicaragua, in der Vitole Robusto (127 mm, cepo 50), so La Casa del Tabaco."}]',
        'Maykelis Ketnath生于古巴，20世纪90年代在哈瓦那的Partagás工厂接受培训，成为一名torcedora，据Berichteaktuell.de介绍；Noblego.de则认为她在雪茄行业拥有二十余年经验。2000年代初移居欧洲后，她与Villiger公司合作，在多场活动中展示技艺，其后于2018年在斯图加特创立May''s Cigars；与此同时，她还在普福尔茨海姆的学校取得金饰工艺文凭，并推出珠宝系列MANDORO。May''s的雪茄在尼加拉瓜卷制；该品牌未透露其工厂名称。

截至2026年9月，产品目录共有两款产品。Short Corona规格为114 mm，cepo 44，采用Habano 2000品种的厄瓜多尔茄衣，配尼加拉瓜茄套与茄芯。Liga 1为Robusto规格（127 mm，cepo 50），沿用相同的厄瓜多尔茄衣，配秘鲁茄套与尼加拉瓜茄芯。两者力度均为mild-medium，据La Casa del Tabaco介绍。',
        '[{"name":"Short Corona","color":"#A0522D","force":"Mild-Medium","wrapper":"厄瓜多尔（Habano 2000）","vitolas":[],"story":"厄瓜多尔Habano 2000茄衣，尼加拉瓜茄套与茄芯，114 mm，cepo 44，据La Casa del Tabaco介绍。"},{"name":"Liga 1","color":"#A0522D","force":"Mild-Medium","wrapper":"厄瓜多尔（Habano 2000）","vitolas":[],"story":"厄瓜多尔Habano 2000茄衣，秘鲁茄套，尼加拉瓜茄芯，为Robusto规格（127 mm，cepo 50），据La Casa del Tabaco介绍。"}]',
        'وُلدت Maykelis Ketnath في كوبا، وتدرّبت هناك في تسعينيات القرن العشرين لتصبح torcedora في مصنع Partagás بهافانا، بحسب Berichteaktuell.de؛ وتحسب لها Noblego.de ما يزيد على عشرين عامًا من الخبرة في عالم السيجار. استقرت في أوروبا في مطلع الألفينيات، وتعاونت مع دار Villiger، حيث قدّمت خبرتها في عدد من الفعاليات، قبل أن تؤسّس May''s Cigars عام 2018 في شتوتغارت؛ وفي الوقت نفسه، نالت شهادة في صياغة الذهب من مدرسة بفورتسهايم، وأطلقت خط مجوهرات باسم MANDORO. تُلفّ سيجارات May''s في نيكاراغوا؛ ولا تكشف الدار عن اسم مصنعها.

حتى سبتمبر 2026، يضم الكتالوج طرازين. تبلغ Short Corona طول 114 mm بمقاس cepo 44، وتحمل غلافًا إكوادوريًا من صنف Habano 2000 فوق غلاف داخلي وحشوة من نيكاراغوا. أما Liga 1، بمقاس Robusto (127 mm، cepo 50)، فتستخدم الغلاف الإكوادوري نفسه فوق غلاف داخلي من بيرو وحشوة نيكاراغوية. وتُقدَّم كلتاهما بقوة mild-medium، بحسب La Casa del Tabaco.',
        '[{"name":"Short Corona","color":"#A0522D","force":"Mild-Medium","wrapper":"الإكوادور (Habano 2000)","vitolas":[],"story":"غلاف إكوادوري من صنف Habano 2000، وغلاف داخلي وحشوة من نيكاراغوا، بطول 114 mm ومقاس cepo 44، بحسب La Casa del Tabaco."},{"name":"Liga 1","color":"#A0522D","force":"Mild-Medium","wrapper":"الإكوادور (Habano 2000)","vitolas":[],"story":"غلاف إكوادوري من صنف Habano 2000، وغلاف داخلي من بيرو وحشوة من نيكاراغوا، بمقاس Robusto (127 mm، cepo 50)، بحسب La Casa del Tabaco."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Nordlicht ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Nordlicht',
        'nicaragua',
        '2017 ou 2018 — Sascha Prieser, Allemagne du Nord',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'osterholz24.de « Nordlicht Zigarren Nordlicht Prieser GbR » (consulté le 25/09/2026 : associés Sascha Prieser, Holger Prieser et Denis Stute, adresse Kirchenstr. 11, Osterholz-Scharmbeck) ; starkezigarren.de « Nordlicht Zigarren kaufen » (consulté le 25/09/2026 : bar de plage de Sascha Prieser à Sandhausen près de Brême, premiers cigares en 2017 selon cette page, production relancée en 2025 avec un nouveau mélange, liste des lignes) ; zigarren.zone « Nordlicht Zigarren — Sascha Prieser » (consulté le 25/09/2026, en allemand : enquête Facebook de Sascha Prieser, collaboration avec Kurt Brandt pour développer le mélange) ; noblego.de « Nordlicht Toro Limitada 2018 » (consulté le 25/09/2026 : premier mélange 2018, tabacs d''Estelí, Condega et Jalapa, cape et sous-cape de Jalapa, tripe des trois régions vieillie quatre ans, force forte) ; brinkmannfinest.de « Nordlicht Perfecto Maduro » (consulté le 25/09/2026 : cape maduro sombre du Nicaragua, tripe d''Estelí et de Condega, force medium) ; noblego.de « Nordlicht Exclusivo Alemania Maduro Perfecto » (consulté le 25/09/2026 : cape, sous-cape et tripe du Nicaragua, force medium, édition pour le marché allemand) ; noblego.de « Isthmus Zigarren » (consulté le 25/09/2026 : biographie de Kurt Brandt, Allemand établi au Costa Rica, fondateur d''Isthmus Cigars roulée au Nicaragua)',
        NULL,
        'Nordlicht Prieser GbR, associés Sascha Prieser, Holger Prieser et Denis Stute, à Osterholz-Scharmbeck, en Allemagne du Nord, développe la marque Nordlicht autour du bar de plage que Sascha Prieser tient à Sandhausen, près de Brême. Les premiers cigares naissent en 2017 pour un petit groupe d''amateurs, dit Starke Zigarren ; le mélange se formalise en 2018 (Nordlicht Toro Limitada 2018), que Sascha Prieser met au point avec Kurt Brandt, Allemand établi au Costa Rica et créateur de la marque Isthmus, dit Zigarren.zone. La production s''arrête, puis reprend en 2025 avec un nouveau mélange, dit Starke Zigarren. La maison ne nomme pas la fabrique qui roule ses cigares.

Le puro nicaraguayen de la ligne Nordlicht associe une cape colorado de Jalapa à une sous-cape de Jalapa posée en double épaisseur et une tripe mêlant Jalapa, Estelí et Condega, vieillie quatre ans avant roulage, dit Noblego.de ; le profil part presque doux pour forcir tiers après tiers, en vitoles Robusto, Gordo, Magnum et Short Torpedo. La Nordlicht Perfecto Maduro, conçue pour le marché allemand, porte une cape maduro sombre sur une tripe d''Estelí et de Condega, en force medium.',
        '[{"name":"Nordlicht","color":"#A0522D","force":"Full","wrapper":"Nicaragua, Jalapa (Colorado)","vitolas":[],"story":"Cape colorado de Jalapa, sous-cape de Jalapa en double épaisseur, tripe mêlant Jalapa, Estelí et Condega vieillie quatre ans, en Robusto, Gordo, Magnum et Short Torpedo, dit Noblego.de."},{"name":"Nordlicht Perfecto Maduro","color":"#4A3728","force":"Medium","wrapper":"Nicaragua (Maduro)","vitolas":[],"story":"Cape maduro sombre du Nicaragua sur une tripe d''Estelí et de Condega, en forme Perfecto, pour le marché allemand, disent Brinkmannfinest.de et Noblego.de."}]',
        'Nordlicht Prieser GbR, partners Sascha Prieser, Holger Prieser and Denis Stute, in Osterholz-Scharmbeck, in northern Germany, developed the Nordlicht brand around the beach bar that Sascha Prieser runs in Sandhausen, near Bremen. The first cigars appeared in 2017 for a small group of enthusiasts, says Starke Zigarren; the blend was formalised in 2018 (Nordlicht Toro Limitada 2018), which Sascha Prieser worked out with Kurt Brandt, a German settled in Costa Rica and creator of the Isthmus brand, says Zigarren.zone. Production stopped, then resumed in 2025 with a new blend, says Starke Zigarren. The house does not name the factory that rolls its cigars.

The Nicaraguan puro of the Nordlicht line pairs a Jalapa colorado wrapper with a double-thickness Jalapa binder and a filler blending Jalapa, Estelí and Condega, aged four years before rolling, says Noblego.de; the profile starts out almost mild, building in strength third by third, in Robusto, Gordo, Magnum and Short Torpedo vitolas. The Nordlicht Perfecto Maduro, designed for the German market, carries a dark maduro wrapper over an Estelí and Condega filler, at medium strength.',
        '[{"name":"Nordlicht","color":"#A0522D","force":"Full","wrapper":"Nicaragua, Jalapa (Colorado)","vitolas":[],"story":"Jalapa colorado wrapper, double-thickness Jalapa binder, filler blending Jalapa, Estelí and Condega aged four years, in Robusto, Gordo, Magnum and Short Torpedo, says Noblego.de."},{"name":"Nordlicht Perfecto Maduro","color":"#4A3728","force":"Medium","wrapper":"Nicaragua (Maduro)","vitolas":[],"story":"Dark Nicaraguan maduro wrapper over an Estelí and Condega filler, in a Perfecto shape, for the German market, say Brinkmannfinest.de and Noblego.de."}]',
        'Nordlicht Prieser GbR, cuyos socios son Sascha Prieser, Holger Prieser y Denis Stute, en Osterholz-Scharmbeck, en el norte de Alemania, desarrolla la marca Nordlicht en torno al bar de playa que Sascha Prieser regenta en Sandhausen, cerca de Bremen. Los primeros puros nacen en 2017 para un pequeño grupo de aficionados, según Starke Zigarren; la mezcla se formaliza en 2018 (Nordlicht Toro Limitada 2018), que Sascha Prieser pone a punto junto con Kurt Brandt, alemán afincado en Costa Rica y creador de la marca Isthmus, según Zigarren.zone. La producción se detiene y vuelve a arrancar en 2025 con una nueva mezcla, según Starke Zigarren. La casa no nombra la fábrica que elabora sus puros.

El puro nicaragüense de la línea Nordlicht combina una capa colorado de Jalapa con un capote de Jalapa colocado a doble espesor y una tripa que mezcla Jalapa, Estelí y Condega, añejada cuatro años antes de liarse, según Noblego.de; el perfil parte casi suave para ir ganando fuerza tercio a tercio, en vitolas Robusto, Gordo, Magnum y Short Torpedo. La Nordlicht Perfecto Maduro, pensada para el mercado alemán, luce una capa maduro oscura sobre una tripa de Estelí y Condega, en fuerza medium.',
        '[{"name":"Nordlicht","color":"#A0522D","force":"Full","wrapper":"Nicaragua, Jalapa (Colorado)","vitolas":[],"story":"Capa colorado de Jalapa, capote de Jalapa a doble espesor, tripa que mezcla Jalapa, Estelí y Condega añejada cuatro años, en Robusto, Gordo, Magnum y Short Torpedo, según Noblego.de."},{"name":"Nordlicht Perfecto Maduro","color":"#4A3728","force":"Medium","wrapper":"Nicaragua (Maduro)","vitolas":[],"story":"Capa maduro oscura de Nicaragua sobre una tripa de Estelí y Condega, en forma Perfecto, para el mercado alemán, según Brinkmannfinest.de y Noblego.de."}]',
        'Die Nordlicht Prieser GbR, mit den Gesellschaftern Sascha Prieser, Holger Prieser und Denis Stute, in Osterholz-Scharmbeck in Norddeutschland, entwickelt die Marke Nordlicht rund um die Strandbar, die Sascha Prieser in Sandhausen bei Bremen betreibt. Die ersten Zigarren entstehen 2017 für eine kleine Gruppe von Liebhabern, so Starke Zigarren; die Mischung wird 2018 festgelegt (Nordlicht Toro Limitada 2018), die Sascha Prieser gemeinsam mit Kurt Brandt entwickelt, einem in Costa Rica ansässigen Deutschen und Gründer der Marke Isthmus, so Zigarren.zone. Die Produktion wird eingestellt und 2025 mit einer neuen Mischung wieder aufgenommen, so Starke Zigarren. Das Haus nennt die Fabrik, die seine Zigarren rollt, nicht namentlich.

Der nicaraguanische Puro der Linie Nordlicht verbindet ein Colorado-Deckblatt aus Jalapa mit einem in doppelter Stärke aufgelegten Umblatt aus Jalapa und einer Einlage, die Jalapa, Estelí und Condega mischt und vor dem Rollen vier Jahre reift, so Noblego.de; das Profil beginnt fast mild und gewinnt Drittel für Drittel an Kraft, in den Vitolen Robusto, Gordo, Magnum und Short Torpedo. Die Nordlicht Perfecto Maduro, für den deutschen Markt konzipiert, trägt ein dunkles Maduro-Deckblatt über einer Einlage aus Estelí und Condega, in der Stärke medium.',
        '[{"name":"Nordlicht","color":"#A0522D","force":"Full","wrapper":"Nicaragua, Jalapa (Colorado)","vitolas":[],"story":"Colorado-Deckblatt aus Jalapa, Umblatt aus Jalapa in doppelter Stärke, Einlage aus Jalapa, Estelí und Condega, vier Jahre gereift, in Robusto, Gordo, Magnum und Short Torpedo, so Noblego.de."},{"name":"Nordlicht Perfecto Maduro","color":"#4A3728","force":"Medium","wrapper":"Nicaragua (Maduro)","vitolas":[],"story":"Dunkles nicaraguanisches Maduro-Deckblatt über einer Einlage aus Estelí und Condega, in der Form Perfecto, für den deutschen Markt, so Brinkmannfinest.de und Noblego.de."}]',
        'Nordlicht Prieser GbR由Sascha Prieser、Holger Prieser和Denis Stute三位合伙人共同创立，位于德国北部的奥斯特霍尔茨-沙姆贝克，Nordlicht品牌围绕Sascha Prieser在不来梅附近的桑德豪森经营的海滩酒吧发展而来。首批雪茄诞生于2017年，供一小群爱好者享用，据Starke Zigarren介绍；配方于2018年正式确立（即Nordlicht Toro Limitada 2018），由Sascha Prieser与定居哥斯达黎加、创立Isthmus品牌的德国人Kurt Brandt共同研发，据Zigarren.zone介绍。生产其后一度中断，于2025年以新配方恢复，据Starke Zigarren介绍。该品牌未透露为其卷制雪茄的工厂名称。

Nordlicht系列的尼加拉瓜puro，以哈拉帕colorado茄衣，搭配双层哈拉帕茄套，以及融合哈拉帕、埃斯特利与孔德加烟叶、卷制前陈化四年的茄芯而成，据Noblego.de介绍；其风味起初近乎温和，随后逐节转浓，规格有Robusto、Gordo、Magnum与Short Torpedo。专为德国市场打造的Nordlicht Perfecto Maduro，茄衣为深色maduro，茄芯采用埃斯特利与孔德加烟叶，力度为medium。',
        '[{"name":"Nordlicht","color":"#A0522D","force":"Full","wrapper":"尼加拉瓜，哈拉帕（Colorado）","vitolas":[],"story":"哈拉帕colorado茄衣，双层哈拉帕茄套，茄芯融合哈拉帕、埃斯特利与孔德加烟叶，陈化四年，规格有Robusto、Gordo、Magnum与Short Torpedo，据Noblego.de介绍。"},{"name":"Nordlicht Perfecto Maduro","color":"#4A3728","force":"Medium","wrapper":"尼加拉瓜（Maduro）","vitolas":[],"story":"深色尼加拉瓜maduro茄衣，茄芯采用埃斯特利与孔德加烟叶，为Perfecto形制，专供德国市场，据Brinkmannfinest.de与Noblego.de介绍。"}]',
        'أسّس Sascha Prieser وHolger Prieser وDenis Stute شركة Nordlicht Prieser GbR في أوسترهولتس-شارمبيك بشمال ألمانيا، وطوّروا علامة Nordlicht حول الحانة الشاطئية التي يديرها Sascha Prieser في زاندهاوزن قرب بريمن. وُلدت أولى السيجارات عام 2017 لمجموعة صغيرة من الهواة، بحسب Starke Zigarren؛ وتبلورت الخلطة عام 2018 (Nordlicht Toro Limitada 2018)، التي أعدّها Sascha Prieser بالتعاون مع Kurt Brandt، الألماني المقيم في كوستاريكا ومؤسّس علامة Isthmus، بحسب Zigarren.zone. توقّف الإنتاج، ثم استؤنف عام 2025 بخلطة جديدة، بحسب Starke Zigarren. ولا تكشف الدار عن اسم المصنع الذي يلفّ سيجارها.

يجمع puro Nordlicht النيكاراغوي بين غلاف colorado من خالابا وغلاف داخلي من خالابا يُوضع بسماكة مضاعفة وحشوة تمزج بين خالابا وإستيلي وكونديغا، وتُترك لتنضج أربع سنوات قبل اللف، بحسب Noblego.de؛ وتنطلق النكهة شبه معتدلة لتشتدّ ثلثًا بعد ثلث، بمقاسات Robusto وGordo وMagnum وShort Torpedo. أما Nordlicht Perfecto Maduro، المصمَّمة للسوق الألماني، فتحمل غلاف maduro داكنًا فوق حشوة من إستيلي وكونديغا، بقوة medium.',
        '[{"name":"Nordlicht","color":"#A0522D","force":"Full","wrapper":"نيكاراغوا، خالابا (Colorado)","vitolas":[],"story":"غلاف colorado من خالابا، وغلاف داخلي من خالابا بسماكة مضاعفة، وحشوة تمزج بين خالابا وإستيلي وكونديغا نضجت أربع سنوات، بمقاسات Robusto وGordo وMagnum وShort Torpedo، بحسب Noblego.de."},{"name":"Nordlicht Perfecto Maduro","color":"#4A3728","force":"Medium","wrapper":"نيكاراغوا (Maduro)","vitolas":[],"story":"غلاف maduro نيكاراغوي داكن فوق حشوة من إستيلي وكونديغا، بشكل Perfecto، مخصّصة للسوق الألماني، بحسب Brinkmannfinest.de وNoblego.de."}]')
