:false},{"name":"Alcazar","desc":"1898 — marque de J.C. Newman, roulée à la PENSA d''Estelí","iconic":false},{"name":"Los Amigos","desc":"2024 — Ramos, Saes, Lahsen ; roulée à la Tabacalera Familia Disla, Estelí","iconic":false},{"name":"Schumacher","desc":"Ralf Schumacher & Paul Bugge GmbH ; roulée au Nicaragua, fabrique non nommée","iconic":false},{"name":"Umnum","desc":"Sœur économique de Condega (Gesinta, Espagne) ; roulée chez Aganorsa Leaf, Estelí","iconic":false},{"name":"Villa Vieja","desc":"2022 — Fernando Navarro ; roulée chez Aganorsa Leaf (TABSA), Estelí","iconic":false},{"name":"Bahia","desc":"Milieu des années 1990 (Tony Borhani), rachetée par Cigars International (STG) ; Blu roulée à Estelí.","iconic":false},{"name":"Marca Fina","desc":"FTAC (producteurs centraméricains) ; puros mono-pays en six lignes, roulés au Nicaragua.","iconic":false},{"name":"Horacio","desc":"2008 ou 2006 — trois amis, Genève (Suisse) ; roulée à Estelí, fabrique non nommée","iconic":false},{"name":"Ibis","desc":"August Schuster (Bünde, Allemagne) ; Nicaragua, Honduras, R. dominicaine ; fabriques non nommées.","iconic":false},{"name":"Mara","desc":"Ricardo Vasquez (né à Cuba) ; roulée au Nicaragua, fabrique non nommée ; quatre lignes.","iconic":false},{"name":"May''s Cigars","desc":"2018 — Maykelis Ketnath, Stuttgart ; roulée au Nicaragua, fabrique non nommée.","iconic":false},{"name":"Nordlicht","desc":"2017-2018 — Sascha Prieser, Osterholz-Scharmbeck ; relancée en 2025, fabrique non nommée.","iconic":false}]' WHERE `id` = 'nicaragua';

