INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Cigarkings','CSC','Despot','Don Duarte','Don Zuarin','Alcazar','Los Amigos','Schumacher','Umnum','Villa Vieja','Samana','SYN','Valentino Siesto','Xhaxhi Bobi','Cuba Aliados','Antonius','Bauza','Butera','Bahia','Marca Fina','Horacio','Ibis','Mara','May''s Cigars','Nordlicht')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 243';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 243','systeme','recensement_8_fiches','marque',0,
   'nicaragua : Cigarkings, CSC, Despot, Don Duarte, Don Zuarin, Alcazar, Los Amigos, Schumacher, Umnum, Villa Vieja, Bahia, Marca Fina, Horacio, Ibis, Mara, May''s Cigars, Nordlicht'),
  (NULL,'migration 243','systeme','recensement_8_fiches','marque',0,
   'dominican : Samana, SYN, Valentino Siesto, Xhaxhi Bobi, Antonius, Bauza, Butera'),
  (NULL,'migration 243','systeme','recensement_8_fiches','marque',0,
   'honduras : Cuba Aliados');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Cigarkings','CSC','Despot','Don Duarte','Don Zuarin','Alcazar','Los Amigos','Schumacher','Umnum','Villa Vieja','Samana','SYN','Valentino Siesto','Xhaxhi Bobi','Cuba Aliados','Antonius','Bauza','Butera','Bahia','Marca Fina','Horacio','Ibis','Mara','May''s Cigars','Nordlicht')) = 25 AS fiches,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Cigarkings"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"CSC"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Despot"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Don Duarte"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Don Zuarin"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Alcazar"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Los Amigos"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Schumacher"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Umnum"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Villa Vieja"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Bahia"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Marca Fina"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Horacio"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Ibis"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Mara"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"May''s Cigars"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Nordlicht"') FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Samana"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"SYN"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Valentino Siesto"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Xhaxhi Bobi"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Antonius"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Bauza"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Butera"') FROM `producer_countries` WHERE `id` = 'dominican') AS dominican_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Cuba Aliados"') FROM `producer_countries` WHERE `id` = 'honduras') AS honduras_annonce,
  (SELECT COUNT(*) FROM `translation_status` WHERE `entite` = 'brands' AND `entite_id` IN ('Cigarkings','CSC','Despot','Don Duarte','Don Zuarin','Alcazar','Los Amigos','Schumacher','Umnum','Villa Vieja','Samana','SYN','Valentino Siesto','Xhaxhi Bobi','Cuba Aliados','Antonius','Bauza','Butera','Bahia','Marca Fina','Horacio','Ibis','Mara','May''s Cigars','Nordlicht')) = 250 AS sceaux,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 243') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
